import type { BankQuestion } from "@/lib/bank";

/** Taxation & Business Law (Management & Commerce): 642 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-tax-law-1","question":"A registered supplier in Maharashtra sells goods to a buyer in Maharashtra, and the goods are delivered within Maharashtra. Which GST applies?","options":["CGST + SGST","IGST","Only CGST","Only SGST"],"answer":0,"explanation":"Supplier and place of supply are in the same state, so it is an intra-state supply, taxed half as CGST and half as SGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-2","question":"A supplier in Delhi sells goods to a buyer in Jaipur, and the goods move from Delhi to Jaipur. Which GST applies?","options":["CGST + SGST of Delhi","CGST + SGST of Rajasthan","IGST","No GST, as it is a stock transfer"],"answer":2,"explanation":"The supplier is in Delhi and the place of supply (where movement ends) is Rajasthan, so it is an inter-state supply attracting IGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-3","question":"The list price of goods is ₹1,00,000. A 5% trade discount on the list price is shown on the invoice; packing charged separately is ₹2,000 and freight charged by the supplier for delivering the goods is ₹3,000. What is the taxable value?","options":["₹1,00,000","₹1,05,000","₹95,000","₹97,000"],"answer":0,"explanation":"The discount shown on the invoice at the time of supply is excluded: 95,000. Packing and freight charged by the supplier are incidental and included: 95,000 + 2,000 + 3,000 = ₹1,00,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-4","question":"A supplier sells goods for ₹50,000 (excluding GST). It also receives a subsidy of ₹5,000 from a private trust, directly linked to this sale's price, and charges ₹1,000 interest for late payment. What is the taxable value?","options":["₹50,000","₹55,000","₹56,000","₹51,000"],"answer":2,"explanation":"Value includes subsidies directly linked to price unless given by the Central or State Government, and also interest or late fees for delayed payment: 50,000 + 5,000 + 1,000 = ₹56,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-5","question":"Three months after a sale, a supplier decides to give the customer a 5% discount that was not provided for in any agreement made before the supply. Under GST:","options":["The taxable value can be reduced through a GST credit note","The discount cannot reduce the taxable value; only a commercial (financial) credit note can be issued","The government refunds the tax on the discount","The customer's ITC rises by the discount"],"answer":1,"explanation":"A post-supply discount reduces value only if it was agreed before or at the time of supply, is linked to specific invoices and the recipient reverses the matching ITC. An unplanned later discount does not qualify.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-6","question":"For a month, output tax is IGST ₹50,000, CGST ₹30,000 and SGST ₹30,000. Input tax credit available is IGST ₹70,000, CGST ₹10,000 and SGST ₹15,000. What is the minimum cash payment needed?","options":["₹35,000","₹15,000","₹20,000","₹25,000"],"answer":1,"explanation":"IGST credit is used first: ₹50,000 against IGST, and the remaining ₹20,000 against CGST/SGST in any proportion. If at least ₹5,000 goes to SGST, no credit is stranded: total output 1,10,000 − total credit 95,000 = ₹15,000 cash. Using IGST credit only against IGST leaves ₹35,000 to pay.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-7","question":"Which of these set-offs of input tax credit is NOT allowed under GST?","options":["IGST credit against CGST liability","CGST credit against IGST liability","SGST credit against IGST liability","CGST credit against SGST liability"],"answer":3,"explanation":"CGST and SGST belong to different governments, so neither credit can pay the other. Both can pay IGST, and IGST credit can pay either.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-8","question":"A company receives legal services worth ₹2,00,000 from an advocate, on which GST is payable under reverse charge at 18% (assume). Its electronic credit ledger has ₹1,00,000. How does it discharge the liability?","options":["Pay ₹36,000 in cash, then claim ₹36,000 as input tax credit","Set off ₹36,000 from the credit ledger","Nothing: the advocate pays the tax","Pay ₹36,000 in cash with no input tax credit allowed"],"answer":0,"explanation":"Tax under reverse charge must be paid through the cash ledger, not from existing credit. Once paid, it is available as ITC if the service is used in the business.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-9","question":"A, registered in Gujarat, orders goods from S in Maharashtra and asks S to deliver them directly to C, also in Maharashtra; S bills A. What tax does S charge A?","options":["CGST + SGST of Maharashtra, as the goods move within Maharashtra","IGST, as the place of supply is A's principal place of business in Gujarat","No GST, as the goods never leave Maharashtra","CGST + SGST of Gujarat"],"answer":1,"explanation":"In a bill-to-ship-to supply, the place of supply for S's sale is the principal place of business of the person on whose direction the goods are delivered (A, Gujarat). Supplier in Maharashtra + place of supply in Gujarat = IGST.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-10","question":"A shop sells a festival hamper of sweets, dry fruits and a packaged juice for one price. Sold separately, the items would attract 5%, 12% and 18% (assume these rates). How is the hamper taxed?","options":["As a composite supply at 5%, the rate of the main item","Each item at its own rate on an apportioned price","As a mixed supply at 18% on the whole price","At the average of the three rates"],"answer":2,"explanation":"The items are not naturally bundled (each is sold on its own), so it is a mixed supply, taxed at the highest rate applicable to any item in it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-11","question":"Which statement about a supplier of goods under the GST composition scheme is correct?","options":["It can charge GST separately on its invoices","It cannot claim input tax credit and cannot collect tax from customers","It can freely make inter-state outward supplies","It must issue tax invoices"],"answer":1,"explanation":"A composition taxpayer pays tax on turnover out of its own pocket, issues a bill of supply, cannot collect tax from buyers, cannot take ITC and cannot make inter-state outward supplies of goods.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-12","question":"How many statements about a composition taxpayer supplying goods are correct? (1) It issues a bill of supply, not a tax invoice. (2) It can claim input tax credit on its purchases. (3) It cannot make inter-state outward supplies of goods. (4) It pays tax on its reverse-charge inward supplies at normal rates, without input tax credit.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct. (2) is wrong: a composition taxpayer cannot claim ITC on any purchase.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-13","question":"In which case is input tax credit allowed?","options":["A 30-seater bus bought by a factory to carry its workers","Outdoor catering for an employees' party that no law requires","Club membership for the company's directors","Goods given away as free samples"],"answer":0,"explanation":"The block on motor vehicles covers only vehicles for carrying persons with a seating capacity of up to 13 (including the driver), so a 30-seater bus qualifies. Catering not required by law, club membership and free samples are blocked under Section 17(5).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-14","question":"For which of these is input tax credit allowed?","options":["Works contract for constructing the company's office building","Works contract for installing plant and machinery","Cement used to build the factory's boundary wall","Repairs capitalised to the office building"],"answer":1,"explanation":"Works contracts and goods for constructing immovable property are blocked, except for plant and machinery. A boundary wall and an office building are civil structures, not plant and machinery.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-15","question":"Assertion (A): A company that claims income-tax depreciation on the full cost of a machine including its ₹1,80,000 GST cannot also take ₹1,80,000 as input tax credit. Reason (R): The GST law denies input tax credit on the tax component of capital goods when depreciation is claimed on that tax component.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Section 16(3) prevents a double benefit: tax cannot be both capitalised for depreciation and claimed as credit. That rule is exactly what A applies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-16","question":"A recipient takes input tax credit but does not pay the supplier the value and tax within 180 days of the invoice. What happens?","options":["The credit must be reversed (added to output tax) with interest, and can be re-claimed once payment is made","The credit is lost permanently","Nothing, since the supplier has paid the tax","The supplier must refund the tax to the buyer"],"answer":0,"explanation":"The proviso to Section 16(2) requires payment within 180 days; otherwise the credit is reversed with interest, and it can be taken again when the payment is made.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-17","question":"Which of these is a supply under GST even though no consideration is received?","options":["Permanent transfer of business machinery, on which ITC was claimed, to the owner's relative","Distribution of free samples on which no ITC was claimed","A donation received by a charity","Salary paid to an employee"],"answer":0,"explanation":"Schedule I treats the permanent transfer or disposal of business assets on which ITC was availed as a supply even without consideration. Salary is outside GST (employee services, Schedule III).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-18","question":"A business has taxable intra-state supplies of ₹40 lakh, exempt supplies of ₹10 lakh and exports of ₹15 lakh. It also received inward supplies of ₹5 lakh on which it paid tax under reverse charge, and it charged GST of ₹7.2 lakh on its taxable supplies. What is its aggregate turnover?","options":["₹70 lakh","₹65 lakh","₹72.2 lakh","₹55 lakh"],"answer":1,"explanation":"Aggregate turnover includes taxable, exempt and export supplies (40 + 10 + 15 = ₹65 lakh) but excludes inward supplies under reverse charge and the taxes themselves.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-19","question":"A Karnataka supplier makes intra-state sales of ₹10,00,000 and inter-state sales of ₹5,00,000, all at 18% (assume). Its input tax credit is IGST of ₹1,50,000 only. How much does it pay in cash?","options":["₹1,80,000","₹2,70,000","₹1,20,000","₹1,50,000"],"answer":2,"explanation":"Output: CGST 90,000 + SGST 90,000 + IGST 90,000 = 2,70,000. IGST credit pays IGST 90,000 and the balance 60,000 goes to CGST/SGST. Cash = 2,70,000 − 1,50,000 = ₹1,20,000. Using IGST credit only against IGST leaves ₹1,80,000 to pay.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-20","question":"Exports are zero-rated under GST. How can an exporter handle them?","options":["Only by paying IGST and claiming a refund","Only under a letter of undertaking, with no refund of input tax credit","Either export under a letter of undertaking without paying IGST and claim a refund of unused ITC, or pay IGST and claim its refund","Exports are exempt, so the related ITC must be reversed"],"answer":2,"explanation":"Zero-rating keeps the exporter's ITC alive through either route. Exempt supplies, by contrast, require ITC reversal.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-21","question":"Which of these is a composite supply?","options":["Goods sold with packing, transport and insurance for a single price","A hamper of chocolates and a water bottle sold for one price","Two unrelated products sold as a combo offer","A gift box of dry fruits and a wristwatch"],"answer":0,"explanation":"In a composite supply the items are naturally bundled and supplied together in the ordinary course of business, with one principal supply (here the goods). The others are mixed supplies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-22","question":"A company pays sitting fees to an independent director who is not its employee, and salary to its whole-time director who is an employee. Which is correct?","options":["Both are supplies and the directors charge GST","Neither is within GST","The company pays GST under reverse charge on the sitting fees; the employee director's salary is not a supply","The employee director's salary attracts GST under reverse charge"],"answer":2,"explanation":"Services by a director to the company are under reverse charge, so the company pays tax on the sitting fees. Services by an employee to the employer in the course of employment are outside GST (Schedule III).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-23","question":"GST is best described as:","options":["An origin-based tax on production","A destination-based tax on consumption","A direct tax on income","A tax on goods only"],"answer":1,"explanation":"GST accrues to the state where the goods or services are consumed, with credit at every stage so that only value addition is taxed.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-24","question":"Which of these was NOT subsumed into GST?","options":["Central excise duty on most goods","Service tax","Basic customs duty","State VAT"],"answer":2,"explanation":"Basic customs duty on imports continues separately; IGST is levied on imports in addition. Excise (except on certain items such as petroleum and tobacco), service tax and VAT were subsumed.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-25","question":"A supplier in Tamil Nadu sells goods to an SEZ unit located in Tamil Nadu. How is the supply treated under GST?","options":["As an intra-state supply attracting CGST + SGST","As an exempt supply with ITC reversal","As a non-taxable supply outside GST","As an inter-state, zero-rated supply (IGST with refund, or under a letter of undertaking)"],"answer":3,"explanation":"The IGST Act treats a supply to an SEZ developer or unit as inter-state even when both are in the same state, and it is zero-rated.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-26","question":"The price of an article, inclusive of GST at 18% (assume), is ₹11,800. How much GST is included in it?","options":["₹2,124","₹1,800","₹1,180","₹1,416"],"answer":1,"explanation":"Tax = 11,800 × 18/118 = ₹1,800 on a value of ₹10,000. Taking 18% of the tax-inclusive price gives ₹2,124.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-27","question":"Common inputs carry input tax credit of ₹1,00,000. In the period, taxable turnover is ₹60 lakh and exempt turnover ₹40 lakh. How much credit must be reversed?","options":["₹40,000","₹60,000","₹66,667","Nil"],"answer":0,"explanation":"Credit on common inputs is reversed in the ratio of exempt turnover to total turnover: 1,00,000 × 40/100 = ₹40,000. Dividing by taxable turnover instead gives ₹66,667.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-28","question":"A company holds GST registrations in Karnataka and Kerala under the same PAN. Which is correct?","options":["Both form one taxable person, so transfers between them are not supplies","Each registration is a distinct person, and a stock transfer between them is a supply even without consideration","Only services between them are supplies","Transfers between them are exempt"],"answer":1,"explanation":"Separate registrations of the same PAN are distinct persons, and Schedule I treats supplies between distinct persons in the course of business as supplies even without consideration.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-29","question":"An architect registered in Mumbai designs a building to be built in Pune for a client registered in Delhi. What tax does the architect charge?","options":["IGST, as the client is in Delhi","CGST + SGST of Delhi","No GST, as immovable property is outside GST","CGST + SGST of Maharashtra, as the place of supply is where the property is"],"answer":3,"explanation":"For services directly related to immovable property, including architects' services, the place of supply is the location of the property (Maharashtra). The supplier is also in Maharashtra, so it is intra-state. Using the general B2B rule (recipient's location) wrongly gives IGST.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-30","question":"Which of these is treated as neither a supply of goods nor a supply of services?","options":["Sale of a building after its completion certificate has been issued","Sale of old office furniture by a company","Renting of a commercial shop","Transfer of stock between registrations of the same company in different states"],"answer":0,"explanation":"Schedule III excludes the sale of land and of a building after its completion certificate. Renting is a supply of services; selling business assets and inter-state stock transfers are supplies.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-31","question":"Which of these is NOT one of the five heads of income under Indian income tax?","options":["Salaries","Income from house property","Capital gains","Income from investments"],"answer":3,"explanation":"The five heads are salaries, house property, profits and gains of business or profession, capital gains and income from other sources. Investment income falls under one of these (usually other sources or capital gains).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-32","question":"Assume the basic rule: an individual is resident if in India for 182 days or more in the year, or for 60 days or more in the year and 365 days or more in the four preceding years. Mr X, a foreign citizen, was in India for 70 days this year and 400 days in the four preceding years. What is his status?","options":["Non-resident, because he is a foreign citizen","Non-resident, because he stayed less than 182 days","Resident, under the 60-day + 365-day test","Resident only for income received in India"],"answer":2,"explanation":"Residence depends on physical presence, not citizenship. 70 ≥ 60 and 400 ≥ 365, so the second condition is met and he is resident.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-33","question":"Assume the basic residence tests (182 days; or 60 days in the year plus 365 days in the four preceding years), and that for an Indian citizen who leaves India during the year for employment abroad the 60-day figure is replaced by 182 days. Ms Y, an Indian citizen, leaves for a job abroad after spending 150 days in India this year; she was in India throughout the four preceding years. What is her status?","options":["Resident, because she is an Indian citizen","Resident, because of more than 365 days in the preceding four years","Resident but only for Indian income","Non-resident, because she was in India for less than 182 days"],"answer":3,"explanation":"For a citizen leaving for employment, the relaxed 60-day test does not apply; she needs 182 days. With 150 days she fails both tests and is non-resident, whatever her past stay.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-34","question":"Mr Z is non-resident this year. How many of these are taxable in India in his hands? (1) Salary for work done in India, credited to his Dubai account (2) Profits of a business controlled from abroad, earned and received abroad (3) Interest on a savings account with an Indian bank (4) Rent from a house in London, received in London","options":["One","Two","Three","Four"],"answer":1,"explanation":"A non-resident is taxed only on income received, or accruing or arising, in India. (1) accrues in India because the work is done here; (3) arises in India. (2) and (4) are foreign income received abroad. Two are taxable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-35","question":"A let-out house has a gross annual value of ₹3,60,000. The owner paid municipal taxes of ₹30,000 and interest of ₹1,00,000 on a loan taken to buy it. Assume a standard deduction of 30% of net annual value. What is the income from house property?","options":["₹1,52,000","₹2,31,000","₹1,22,000","₹1,31,000"],"answer":3,"explanation":"Net annual value = 3,60,000 − 30,000 = 3,30,000. Standard deduction 30% = 99,000 → 2,31,000. Less interest 1,00,000 = ₹1,31,000. Taking 30% of the gross value instead (and ignoring taxes) gives ₹1,52,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-36","question":"Take expected rent as the higher of municipal value and fair rent, but not more than the standard rent under rent-control law; gross annual value is the higher of expected rent and actual rent received. Municipal value ₹2,40,000; fair rent ₹2,70,000; standard rent ₹2,60,000; actual rent received ₹2,50,000. What is the gross annual value?","options":["₹2,70,000","₹2,50,000","₹2,60,000","₹2,40,000"],"answer":2,"explanation":"Higher of municipal value and fair rent = 2,70,000, capped at standard rent → expected rent 2,60,000. GAV = higher of 2,60,000 and actual rent 2,50,000 = ₹2,60,000. Forgetting the standard-rent cap gives ₹2,70,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-37","question":"For a self-occupied house, assume annual value is nil, interest deduction is capped at ₹2,00,000, and pre-construction interest is allowed in five equal instalments starting from the year construction is completed. Pre-construction interest was ₹1,50,000 and interest for the current year (the year of completion) is ₹1,80,000. What is the income from house property?","options":["Loss of ₹2,00,000","Loss of ₹2,10,000","Loss of ₹3,30,000","Loss of ₹1,80,000"],"answer":0,"explanation":"Interest allowable = 1,50,000 ÷ 5 + 1,80,000 = 2,10,000, but the cap limits it to 2,00,000. With nil annual value, the loss is ₹2,00,000. Claiming all the pre-construction interest at once gives ₹3,30,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-38","question":"Under a regime that allows HRA exemption, assume the exemption is the least of: HRA received; rent paid minus 10% of salary; and 50% of salary (metro city). Salary (for this purpose) is ₹6,00,000, HRA received ₹1,80,000 and rent paid ₹2,10,000 in a metro city. What is the exempt HRA?","options":["₹1,80,000","₹1,50,000","₹3,00,000","₹30,000"],"answer":1,"explanation":"The three limits are 1,80,000; 2,10,000 − 60,000 = 1,50,000; and 3,00,000. The least is ₹1,50,000, so ₹30,000 of the HRA is taxable.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-39","question":"Land is sold for ₹50,00,000, but its stamp duty value is ₹56,00,000. Assume that if the stamp duty value exceeds the consideration by more than 10%, the stamp duty value is taken as the sale consideration. Cost of acquisition (no indexation) is ₹30,00,000 and brokerage is 1% of the actual sale price. What is the capital gain?","options":["₹19,50,000","₹26,00,000","₹20,00,000","₹25,50,000"],"answer":3,"explanation":"110% of 50,00,000 = 55,00,000, and 56,00,000 exceeds it, so consideration = 56,00,000. Brokerage = 50,000. Gain = 56,00,000 − 30,00,000 − 50,000 = ₹25,50,000. Using the actual price gives ₹19,50,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-40","question":"Property is sold for ₹80,00,000; its stamp duty value is ₹87,00,000. Assume the stamp duty value replaces the consideration only if it exceeds the consideration by more than 10%. Cost of acquisition is ₹45,00,000, cost of improvement ₹5,00,000 and transfer expenses ₹1,00,000 (no indexation). What is the capital gain?","options":["₹36,00,000","₹29,00,000","₹34,00,000","₹30,00,000"],"answer":1,"explanation":"110% of 80,00,000 = 88,00,000; 87,00,000 does not exceed it, so the actual ₹80,00,000 is used. Gain = 80,00,000 − 45,00,000 − 5,00,000 − 1,00,000 = ₹29,00,000. Using the stamp duty value gives ₹36,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-41","question":"Which set-off of losses is permitted?","options":["Long-term capital loss against short-term capital gain","Business loss against salary income","Speculation business loss against non-speculation business income","Short-term capital loss against long-term capital gain"],"answer":3,"explanation":"A short-term capital loss can be set off against both short-term and long-term gains, but a long-term capital loss only against long-term gains. Business losses cannot be set off against salary, and speculation losses only against speculation income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-42","question":"An individual has salary income of ₹8,00,000, a loss from house property of ₹2,50,000, business income of ₹1,00,000, a short-term capital gain of ₹50,000 and a long-term capital loss of ₹70,000. Assume a house-property loss can be set off against other heads only up to ₹2,00,000. What is the gross total income?","options":["₹7,50,000","₹7,00,000","₹6,50,000","₹8,00,000"],"answer":0,"explanation":"8,00,000 − 2,00,000 (capped HP loss) + 1,00,000 + 50,000 STCG = ₹7,50,000. The long-term capital loss cannot be set off against the short-term gain and is carried forward, as is ₹50,000 of the HP loss.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-43","question":"Which of these is agricultural income?","options":["Income from poultry farming","Dividend from a tea-plantation company","Rent received from agricultural land in India used for agriculture","Sale of trees that grew naturally, without any cultivation"],"answer":2,"explanation":"Rent or revenue from agricultural land in India used for agriculture is agricultural income. Poultry is not agriculture, a dividend is from a company, and naturally grown trees involve no agricultural operations.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-44","question":"A company credits a consultant's professional fees to his account in its books on 31 March and pays him on 15 April. For a TDS provision that applies at credit or payment, whichever is earlier, when must tax be deducted?","options":["On 15 April, when the cash is paid","When the consultant raises his invoice","At the end of the following quarter","On 31 March, when the amount is credited"],"answer":3,"explanation":"Under the 'credit or payment, whichever is earlier' rule, crediting the payee's account (including a suspense or provision account) triggers deduction, so TDS is due on 31 March.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-45","question":"A business paid a resident contractor ₹10,00,000 without deducting the TDS that was due. Its profit before this adjustment is ₹25,00,000. Assume 30% of an expense is disallowed when TDS is not deducted, and that the disallowed amount is allowed in the year the TDS is later deducted and paid. What is its business income this year?","options":["₹25,00,000","₹28,00,000","₹35,00,000","₹22,00,000"],"answer":1,"explanation":"Disallowance = 30% × 10,00,000 = 3,00,000, added back: 25,00,000 + 3,00,000 = ₹28,00,000. The ₹3,00,000 becomes deductible in the year the TDS is paid. Disallowing the whole expense gives ₹35,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-46","question":"Tax deducted at source (TDS) is best described as:","options":["A penalty for late filing","A tax on exempt income","An additional tax over and above the regular tax","A way of collecting tax at the point where income is paid, credited against the payee's final liability"],"answer":3,"explanation":"The payer deducts tax and deposits it; the payee claims it as a credit when computing final tax.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-47","question":"Which statement about advance tax is correct?","options":["It is paid after the year ends, along with the return","It is a tax on future income of the next year","It is paid in instalments during the same year in which the income is earned","It applies only to companies"],"answer":2,"explanation":"Advance tax ('pay as you earn') is paid in instalments during the year itself when estimated liability crosses the threshold; shortfalls attract interest.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-48","question":"Mr A gifts ₹10 lakh to his wife without adequate consideration. She invests it in a fixed deposit and earns ₹80,000 interest, which she reinvests and earns ₹6,000 more. Under the clubbing rules, what is included in Mr A's income?","options":["₹86,000","Nil, because a gift to a spouse is exempt","₹6,000","₹80,000"],"answer":3,"explanation":"Income from assets transferred to a spouse without adequate consideration is clubbed with the transferor's income: the ₹80,000. Income earned on that clubbed income (the ₹6,000 on reinvested interest) is not clubbed; it is the wife's income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-49","question":"A proprietor's profit and loss account shows a net profit of ₹12,00,000 after debiting income tax of ₹2,00,000, book depreciation of ₹1,50,000 and personal expenses of ₹30,000, and after crediting dividend income of ₹50,000 (taxed under another head). Tax depreciation allowable is ₹1,80,000. What is the business income?","options":["₹14,00,000","₹13,80,000","₹12,90,000","₹13,50,000"],"answer":3,"explanation":"12,00,000 + 2,00,000 (income tax) + 1,50,000 (book depreciation) − 1,80,000 (tax depreciation) − 50,000 (dividend) + 30,000 (personal expenses) = ₹13,50,000. Leaving the dividend in gives ₹14,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-50","question":"Which of these is taxed under 'Income from other sources'?","options":["Interest on a bank fixed deposit held as an investment by a salaried person","Rent from a let-out flat","Gain on sale of shares held as investments","Salary arrears"],"answer":0,"explanation":"Interest income not chargeable under another head goes to other sources. Rent from a building is house property, share gains are capital gains and arrears are salary.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-51","question":"Assume that gifts of money from non-relatives are fully taxable if their aggregate in the year exceeds ₹50,000, while gifts from relatives are exempt. During the year Ms P receives ₹80,000 from a friend and ₹2,00,000 from her brother. How much is taxable?","options":["₹30,000","₹80,000","₹2,80,000","Nil"],"answer":1,"explanation":"The brother is a relative, so ₹2,00,000 is exempt. Gifts from non-relatives total ₹80,000, which exceeds ₹50,000, so the whole ₹80,000 (not just the excess of ₹30,000) is taxable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-52","question":"Which statement correctly distinguishes tax planning, tax avoidance and tax evasion?","options":["All three are legal","Tax evasion is legal if disclosed later","Tax planning uses provisions as the law intends; avoidance exploits loopholes against the law's intent; evasion is illegal concealment","Tax planning and tax evasion mean the same thing"],"answer":2,"explanation":"Planning (e.g. claiming eligible deductions) is legitimate; avoidance is technically within the letter but against the spirit and can be countered by anti-avoidance rules; evasion (suppressing income, false expenses) is a crime.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-53","question":"How is the residential status of a company determined?","options":["By the residence of the majority of its shareholders","By where most of its sales are made","By the citizenship of its directors","An Indian company is always resident; a foreign company is resident if its place of effective management is in India"],"answer":3,"explanation":"Incorporation in India makes a company resident every year; a foreign company becomes resident only if its place of effective management (where key management decisions are actually taken) is in India.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-54","question":"Mr Q is non-resident. His income: salary for work done in India, received in Dubai ₹5,00,000; interest from an Indian bank ₹50,000; rent from a house in London received in London ₹3,00,000; dividend from a US company received in the US ₹1,00,000. What is his income taxable in India?","options":["₹5,50,000","₹9,50,000","₹50,000","₹8,50,000"],"answer":0,"explanation":"A non-resident is taxed on income accruing or received in India: salary for Indian work (₹5,00,000) and Indian interest (₹50,000) = ₹5,50,000. The London rent and US dividend are foreign income received abroad. If he were an ordinarily resident, all ₹9,50,000 would be taxed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-55","question":"A block of assets taxed at 15% has an opening WDV of ₹10,00,000. An asset costing ₹4,00,000 is added and put to use for less than 180 days; an asset from the block is sold for ₹2,00,000. Assume only half the rate is allowed on an asset used for less than 180 days in the year. What is the depreciation?","options":["₹1,80,000","₹1,65,000","₹1,50,000","₹1,20,000"],"answer":2,"explanation":"Deduct the sale from the opening WDV first: (10,00,000 − 2,00,000) × 15% = 1,20,000. New asset: 4,00,000 × 7.5% = 30,000. Total ₹1,50,000. Full rate on everything gives ₹1,80,000; netting the sale against the new asset instead gives ₹1,65,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-56","question":"A block of depreciable assets has a WDV of ₹3,00,000 at the start of the year, with no additions. The only asset in the block, held for many years, is sold for ₹5,00,000. How is the ₹2,00,000 excess treated?","options":["As a long-term capital gain, because the asset was held for many years","As business income of ₹5,00,000","No gain arises; the WDV simply becomes negative","As a short-term capital gain, whatever the holding period"],"answer":3,"explanation":"For assets in a block, when sale proceeds exceed the opening WDV plus additions, the excess is deemed a short-term capital gain regardless of how long the asset was held.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-57","question":"A company incurs ₹40,000 of expenses wholly to earn dividend income that is exempt in its hands. Can it deduct these expenses from its taxable income?","options":["Yes, all business expenses are deductible","No, expenses related to exempt income are not deductible","Yes, but only half","Only if the dividend exceeds the expenses"],"answer":1,"explanation":"Expenditure incurred in relation to income that does not form part of total income is not allowed as a deduction.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-58","question":"Assertion (A): A small business opting for presumptive taxation may declare income at a prescribed percentage of turnover without maintaining detailed books. Reason (R): Presumptive schemes aim to reduce compliance burden by deeming income on a simple base.","options":["Both A and R are false","A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Presumptive schemes deem income at a percentage of turnover or receipts precisely to spare small taxpayers detailed accounting and audit, which explains A.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-59","question":"The Permanent Account Number (PAN) is issued by:","options":["The Income Tax Department","The Reserve Bank of India","The GST Council","The Ministry of Corporate Affairs"],"answer":0,"explanation":"PAN is a ten-character alphanumeric identifier issued by the Income Tax Department.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-60","question":"Which of these is a direct tax?","options":["GST","Customs duty","Excise duty","Income tax"],"answer":3,"explanation":"A direct tax is borne by the person on whom it is levied. Income tax is direct; GST, customs and excise are indirect taxes passed on to consumers.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-61","question":"Goods displayed in a shop window with price tags are, in contract law:","options":["An invitation to offer","An offer","An acceptance","A binding promise"],"answer":0,"explanation":"A display invites customers to make offers; the customer offers to buy and the shopkeeper may accept or refuse.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-62","question":"Under the Indian Contract Act, a contract is:","options":["Any agreement between two persons","An agreement enforceable by law","Any promise made in writing","Any agreement involving money"],"answer":1,"explanation":"Section 2(h): an agreement enforceable by law is a contract. All contracts are agreements, but social or illegal agreements are not contracts.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-63","question":"A offers to sell his bike to B for ₹1,00,000. B replies that he will pay ₹90,000. A refuses. B then writes that he accepts the price of ₹1,00,000. A no longer wishes to sell. What is the legal position?","options":["There is a contract at ₹1,00,000, since B accepted A's price","There is a contract at ₹90,000","There is no contract: B's counter-offer rejected A's offer, and A made no fresh offer","There is a voidable contract"],"answer":2,"explanation":"A counter-offer is a rejection of the original offer, which then lapses. B's later 'acceptance' is only a fresh offer, which A may decline.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-64","question":"A writes to B offering his car for ₹5 lakh and adds: 'If I hear nothing from you by Friday, I shall treat the car as sold to you.' B does not reply. What is the position on Friday?","options":["A contract arises on Friday","B is bound, because he did not reject the offer","A contract arises if B privately intended to accept","No contract: the offeror cannot make silence count as acceptance"],"answer":3,"explanation":"Acceptance must be communicated by some act or words. An offeror cannot impose silence as acceptance on the offeree.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-65","question":"A posts an offer on 1 January, which B receives on 3 January. B posts his acceptance on 5 January; it reaches A on 8 January. B sends a revocation of his acceptance by courier, which reaches A on 7 January. What is the result?","options":["The revocation is valid, because it reached A before the acceptance did","The revocation is invalid, because the contract was concluded on 5 January","The revocation is invalid, because an acceptance can never be revoked","There is no contract, because A did not reply"],"answer":0,"explanation":"Acceptance is complete against the acceptor only when it comes to the proposer's knowledge (8 January), so B may revoke it until then. His revocation reached A on 7 January, so no contract arises.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-66","question":"How many of these statements are correct? (1) Communication of an offer is complete when it comes to the knowledge of the offeree. (2) Communication of an acceptance is complete against the proposer when it is put in the course of transmission. (3) Communication of an acceptance is complete against the acceptor when it comes to the knowledge of the proposer. (4) An offer can still be revoked after the acceptance has been posted, if the acceptance has not yet reached the proposer.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (3) state Section 4 correctly. (4) is wrong: an offer can be revoked only before the acceptance is put in the course of transmission against the proposer, i.e. before it is posted.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-67","question":"A company advertises a reward of ₹10,000 to anyone who finds its missing dog. X reads the advertisement, finds the dog and returns it, without first telling the company that he accepts. Can X claim the reward?","options":["No, because he did not communicate his acceptance first","Yes: performing the conditions of a general offer is acceptance","Only if the company agrees afterwards","No, because an offer made to the public cannot be accepted"],"answer":1,"explanation":"A general offer is accepted by anyone who performs its conditions with knowledge of it; separate communication of acceptance is not needed (the Carlill principle).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-68","question":"A servant traces his master's missing nephew. Only later does he learn that the master had announced a reward for finding the boy. Can he claim the reward?","options":["Yes, because he performed the act","Yes, but only half","Yes, once he learns of the reward","No, because an offer cannot be accepted by someone who does not know of it"],"answer":3,"explanation":"Acceptance requires knowledge of the offer. Doing the act in ignorance of the offer is not acceptance (Lalman Shukla v Gauri Dutt).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-69","question":"A woman gifts her property to her daughter on condition that the daughter pays an annual sum to the woman's brother. The daughter later refuses, arguing that the brother gave no consideration. Can the brother enforce the promise?","options":["Yes: consideration may move from the promisee or from any other person","No, because no consideration moved from him","No, because the gift is void","Only the woman can sue"],"answer":0,"explanation":"Under Section 2(d), consideration may move from the promisee 'or any other person'. The gift of property by the woman is consideration for the daughter's promise (Chinnaya v Ramayya).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-70","question":"At B's request, A repaired B's roof last year without fixing any price. B now promises to pay A ₹20,000. Is the promise enforceable?","options":["No, because past consideration is no consideration","Yes: in India, past consideration given at the promisor's request is valid","Only if the promise is written and registered","No, because it is a gratuitous promise"],"answer":1,"explanation":"Section 2(d) recognises an act already done ('has done') at the desire of the promisor as consideration. Indian law accepts past consideration, unlike English law.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-71","question":"Which of these agreements made without consideration are valid? (a) A father's written and registered promise, made out of natural love and affection, to give a house to his son (b) An oral promise to pay a time-barred debt (c) A promise to compensate a person who has already voluntarily paid a tax on the promisor's behalf (d) An unwritten promise to give someone a gift in future","options":["(a) only","(a), (b) and (c)","(a) and (c) only","All four"],"answer":2,"explanation":"Section 25 exceptions: (a) written, registered, natural love and affection between near relations; (c) compensation for something already done voluntarily for the promisor. A promise to pay a time-barred debt must be in writing and signed, so (b) fails; (d) has no exception.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-72","question":"A minor mortgages his house to a moneylender in return for a loan and later sues to have the mortgage cancelled. What is the legal position of the mortgage?","options":["Valid, since the minor received the money","Voidable at the lender's option","Valid once the minor repays the loan","Void from the beginning; the minor cannot be held liable on it"],"answer":3,"explanation":"An agreement with a minor is void ab initio (Mohori Bibee v Dharmodas Ghose), so the mortgage cannot be enforced against him.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-73","question":"How many of these statements about minors are correct? (1) A minor can be a promisee or beneficiary under a contract. (2) A minor can ratify an agreement on attaining majority. (3) A minor can act as an agent. (4) A minor can be admitted to the benefits of an existing partnership with the consent of all partners.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct; the principal, not the minor agent, is bound in (3), and (4) is allowed by the Partnership Act. (2) is wrong: a void agreement cannot be ratified.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-74","question":"A person who is usually of unsound mind but occasionally of sound mind:","options":["Can never make a contract","May make a contract when he is of sound mind","Can contract only through a guardian","Can contract only for necessaries"],"answer":1,"explanation":"Section 12: a person usually of unsound mind but occasionally sound may contract when he is of sound mind; the reverse applies to a person usually sound but occasionally not.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-75","question":"C, a stranger to the deal, threatens to harm A's son unless A sells his car cheaply to B. B knows nothing of the threat. What is the status of the contract?","options":["Valid, because B did not use coercion","Void ab initio","Voidable at A's option, because coercion can come from any person","Illegal, so neither party can enforce it"],"answer":2,"explanation":"Coercion need not come from the other party, and it may be directed against anyone; it makes the contract voidable at the option of the party whose consent was so obtained.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-76","question":"A spiritual guru persuades a devotee to gift him most of her property. The devotee later challenges the gift. Which is correct?","options":["The gift is valid unless the devotee proves fraud","The gift is void because spiritual advisers cannot receive gifts","The gift is valid because gifts need no consideration","The gift is voidable, and the burden is on the guru to prove he did not use undue influence"],"answer":3,"explanation":"Where one party is in a position to dominate the will of the other (a spiritual adviser over a devotee) and the transaction looks unconscionable, undue influence is presumed and the dominant party must prove it was not used.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-77","question":"How many of these statements are correct? (1) Misrepresentation is an innocent false statement, while fraud is made knowingly or recklessly to deceive. (2) Both make the contract voidable at the option of the deceived party. (3) Mere silence about facts likely to affect consent is always fraud. (4) A contract is not voidable for misrepresentation if the party could have discovered the truth with ordinary diligence.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: silence is fraud only where there is a duty to speak or the silence is itself equivalent to speech.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-78","question":"How many of these statements about mistake are correct? (1) If both parties are mistaken about a fact essential to the agreement, it is void. (2) A unilateral mistake of fact makes the contract voidable. (3) A contract is not voidable because of a mistake about a law in force in India. (4) A mistake about a foreign law is treated like a mistake of fact.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) Section 20, (3) Section 21 and (4) its proviso are correct. (2) is wrong: under Section 22 a unilateral mistake of fact does not make a contract voidable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-79","question":"Which of these agreements is void?","options":["An agreement in restraint of the marriage of an adult","An agreement made with a pardanashin woman","An agreement made under coercion","An agreement to sell goods on credit"],"answer":0,"explanation":"Section 26 makes agreements in restraint of the marriage of any person other than a minor void. Coercion makes a contract voidable, not void.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-80","question":"A sells the goodwill of his business to B and agrees not to carry on a similar business within the same city for three years. Is the restraint enforceable?","options":["No, every agreement in restraint of trade is void","Yes, if the limits are reasonable, because sale of goodwill is an exception to the rule","Only if registered","Only if B pays extra consideration for it"],"answer":1,"explanation":"Section 27 makes restraints of trade void, but its exception allows a seller of goodwill to agree not to compete within specified local limits, so long as they are reasonable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-81","question":"Which of these clauses in a commercial contract are valid? (1) Future disputes will be referred to arbitration. (2) A party's rights are extinguished unless he sues within three months. (3) Only the courts of Mumbai, which have jurisdiction, will hear disputes. (4) Neither party may approach any court at all.","options":["(1) and (3) only","(1), (2) and (3)","(1) only","All four"],"answer":0,"explanation":"Section 28 voids agreements that absolutely restrict legal proceedings or extinguish rights on a shortened period. Arbitration clauses and choosing one of several competent courts are allowed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-82","question":"Consent is NOT free when it is caused by:","options":["Advertisement","Negotiation","Coercion","Discount"],"answer":2,"explanation":"Coercion, undue influence, fraud, misrepresentation and mistake prevent consent from being free.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-83","question":"A agrees to pay B ₹1 lakh if B marries C. C dies before any marriage. What happens to the agreement?","options":["B can claim the money","It becomes voidable at A's option","A must pay half","It becomes void, because the event has become impossible"],"answer":3,"explanation":"A contingent contract to do something if an uncertain event happens becomes void when that event becomes impossible (Section 32).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-84","question":"A promises to pay B ₹5 lakh if a certain ship does not return within a year. The ship sinks six months later. Can B enforce the promise now?","options":["Yes, because it is now certain that the ship will not return within the year","No, he must wait until the year ends","No, the contract is void","Only if the ship was insured"],"answer":0,"explanation":"Under Section 35, a contract contingent on an event not happening within a fixed time can be enforced when the time expires or when it becomes certain before then that the event will not happen.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-85","question":"Assertion (A): A contract of insurance is not a wagering agreement. Reason (R): The insured has an insurable interest in the subject matter, and the contract protects against a real loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In a wager neither party has any interest other than the stake. Insurance is valid because the insured stands to suffer a genuine loss, which is what R says.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-86","question":"A agrees to pay a public servant ₹2 lakh to secure a government job for A's son. What is the status of the agreement?","options":["Valid, if the job is obtained","Voidable at A's option","Void, because its object is unlawful and opposed to public policy","Valid, but the money is refundable"],"answer":2,"explanation":"An agreement whose object involves corruption of public officers is unlawful under Section 23 and void.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-87","question":"A agrees to sell his house to B for ₹50 lakh, and further agrees that if B uses it as a gambling den, B will pay ₹1 crore. Which is correct?","options":["The whole agreement is void","Both promises are enforceable","Only the second promise is enforceable","The first set of promises (sale for ₹50 lakh) is enforceable; the second is void"],"answer":3,"explanation":"Section 57: where persons promise first to do legal things and then, in specified circumstances, illegal things, the first set is a contract and the second a void agreement.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-88","question":"How does an illegal agreement differ from an agreement that is merely void?","options":["They are identical in effect","An illegal agreement taints collateral transactions too, while transactions collateral to a merely void agreement may be valid","A void agreement can be ratified, but an illegal one cannot","An illegal agreement is valid until challenged"],"answer":1,"explanation":"Every illegal agreement is void, but not every void agreement is illegal. Agreements collateral to an illegal one are also void; those collateral to a merely void agreement can be enforced.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-89","question":"Which of these is NOT an exception to the rule that a stranger to a contract cannot sue on it?","options":["A creditor of one of the parties who hopes to be paid from the contract proceeds","A beneficiary under a trust","A person entitled under a family settlement","A person in whose favour a party has acknowledged an obligation (estoppel)"],"answer":0,"explanation":"Recognised exceptions include trusts, family settlements, acknowledgement or estoppel, covenants running with land and agency. A mere creditor of a party has no right to sue on the contract.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-90","question":"At an auction, a bidder makes the highest bid but withdraws it before the auctioneer's hammer falls. Which is correct?","options":["He is bound, because the highest bid is an acceptance","He is liable to pay damages","He can withdraw: each bid is an offer, and the sale is complete only when the hammer falls","He can withdraw only with the seller's consent"],"answer":2,"explanation":"In an auction the auctioneer invites offers; each bid is an offer that can be withdrawn until it is accepted by the fall of the hammer.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-91","question":"A finds a wallet lying on the road and takes it. What is his legal position with respect to the wallet?","options":["He becomes its owner","He is in the position of a bailee","He is the owner's agent","He becomes a trustee only after one year"],"answer":1,"explanation":"Under Section 71, a person who finds goods belonging to another and takes them into custody has the same responsibility as a bailee.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-92","question":"A delivers goods to B's house by mistake, intending no gift. B knows this and uses the goods. What is B's liability?","options":["None, because there was no contract","B must return only what remains unused","B must pay only if he signed for them","B must compensate A, because A acted non-gratuitously and B enjoyed the benefit"],"answer":3,"explanation":"Section 70: where a person lawfully does something for another, not intending to do so gratuitously, and the other enjoys the benefit, the latter must compensate or restore it.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-93","question":"A pays ₹40,000 to a municipality as property tax under the mistaken belief that he owes it; in fact the liability is B's. What can A do?","options":["Recover the money from the municipality, since money paid by mistake must be repaid","Nothing, as tax once paid cannot be recovered","Recover only half","Recover only if the municipality agrees"],"answer":0,"explanation":"Section 72: a person to whom money is paid by mistake or under coercion must repay or return it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-94","question":"B holds land on lease from A. B fails to pay the government revenue due on it, and the land is advertised for sale. A pays the revenue to prevent the sale. What is A's right?","options":["None, because he paid voluntarily","He becomes owner of B's lease","He can recover the amount from B, as an interested person paying money another was bound to pay","He can recover it only from the government"],"answer":2,"explanation":"Section 69: a person interested in paying money that another is bound by law to pay, who pays it, is entitled to be reimbursed by that other.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-95","question":"A mill's broken crankshaft is given to a carrier to take to the makers as a pattern. The carrier is told nothing about the mill being idle without it, and delivers late. Can the mill owner recover the profits lost during the delay?","options":["Yes, all losses caused by the breach are recoverable","No: the loss of profit did not arise naturally and was not in the parties' contemplation","Yes, but only half","Only if the carrier was negligent"],"answer":1,"explanation":"Hadley v Baxendale: damages cover losses arising naturally from the breach or that both parties contemplated when contracting. Special circumstances not communicated make the loss too remote.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-96","question":"A contract states that ₹5 lakh is payable on breach. One party breaks it; the other's actual loss is ₹2 lakh. Under Section 74, what can the court award?","options":["Exactly ₹5 lakh, as agreed","Nothing, unless the loss exceeds ₹5 lakh","₹5 lakh plus actual loss","Reasonable compensation not exceeding ₹5 lakh, without the need to prove the exact loss"],"answer":3,"explanation":"Indian law does not distinguish strictly between penalty and liquidated damages: the aggrieved party gets reasonable compensation up to the stipulated amount, whether or not actual loss is proved, but not automatically the full sum.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-97","question":"On 1 March, A tells B he will not deliver the goods due on 1 June. What is B's position?","options":["B may treat the contract as ended and sue at once, or wait until 1 June","B must wait until 1 June before taking any action","The contract is automatically void","B can only claim specific performance"],"answer":0,"explanation":"An anticipatory breach lets the promisee rescind and sue immediately, or keep the contract alive until the due date (Section 39); if he waits, he takes the risk of supervening events.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-98","question":"B agreed to buy 1,000 units at ₹500 each but refused delivery on the due date, when the market price was ₹440. The seller resold a month later at ₹400. What damages can the seller recover?","options":["₹1,00,000","₹40,000","₹60,000","₹5,00,000"],"answer":2,"explanation":"Damages = (contract price − market price on the date of breach) × quantity = (500 − 440) × 1,000 = ₹60,000. The further fall to ₹400 is the seller's loss for not mitigating promptly.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-99","question":"A hires a hall for a concert, but the hall is destroyed by fire, through no one's fault, before the concert date. What happens to the contract?","options":["The hall owner must pay damages","It becomes void because performance has become impossible","A must still pay the rent","It is suspended until the hall is rebuilt"],"answer":1,"explanation":"Section 56: a contract to do an act that afterwards becomes impossible, through no fault of the promisor, becomes void (supervening impossibility, as in Taylor v Caldwell).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-100","question":"A owes B ₹1 lakh. A, B and C agree that B will accept C as his debtor instead of A. This is:","options":["Rescission","Alteration","Remission","Novation"],"answer":3,"explanation":"Substituting a new contract (here with a new party) for the old one is novation (Section 62); the original contract need not be performed.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-101","question":"A publisher commissions A to write a book for a series for ₹50,000. After A has written half the book, the publisher abandons the series. What can A claim?","options":["Reasonable payment for the work done, on a quantum meruit basis","Nothing, because the book was not completed","The full ₹50,000, but only after finishing the book","Only his out-of-pocket expenses"],"answer":0,"explanation":"When one party is prevented from completing performance by the other's breach, he can recover reasonable remuneration for what he has done (quantum meruit, as in Planche v Colburn).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-102","question":"A contract by which one party promises to save the other from loss caused by the conduct of the promisor or any other person is a contract of:","options":["Guarantee","Bailment","Indemnity","Agency"],"answer":2,"explanation":"Section 124 defines a contract of indemnity; a guarantee involves a promise to discharge a third person's liability on default.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-103","question":"In a contract of guarantee, the three parties are:","options":["Indemnifier, indemnity holder and creditor","Surety, principal debtor and creditor","Bailor, bailee and surety","Principal, agent and creditor"],"answer":1,"explanation":"The surety gives the guarantee, the principal debtor owes the money, and the creditor receives the guarantee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-104","question":"B borrows from C, with A as surety. B defaults. C sues A without first suing B. Is this allowed?","options":["No, the creditor must first exhaust remedies against the debtor","Yes, because the surety's liability is co-extensive with the principal debtor's","Only if B is insolvent","Only with the court's permission"],"answer":1,"explanation":"Section 128 makes the surety's liability co-extensive with the debtor's. Unless the contract says otherwise, the creditor may proceed against the surety directly.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-105","question":"A gives C a continuing guarantee for goods C supplies to B, up to ₹5 lakh. B buys goods worth ₹2 lakh and then ₹1.5 lakh. A then revokes the guarantee by notice to C. Afterwards B buys a further ₹1 lakh. B defaults on everything. What is A's liability?","options":["₹4.5 lakh","₹5 lakh","Nil","₹3.5 lakh"],"answer":3,"explanation":"A continuing guarantee can be revoked for future transactions by notice (Section 130). A remains liable for transactions before revocation: 2 + 1.5 = ₹3.5 lakh, not for the ₹1 lakh supplied afterwards.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-106","question":"A guarantees that C will lend B ₹5 lakh repayable in 12 months. Without A's consent, C and B change the loan to ₹8 lakh repayable in 24 months. What is A's position?","options":["A is discharged as to transactions after the variance","A is liable for ₹8 lakh","A is liable for ₹5 lakh repayable in 24 months","A must consent before C can sue B"],"answer":0,"explanation":"Section 133: any variance in the terms between the creditor and principal debtor without the surety's consent discharges the surety as to transactions after the variance.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-107","question":"How many of these discharge a surety, wholly or partly? (1) The creditor releases the principal debtor. (2) The creditor merely refrains from suing the debtor for some time. (3) The creditor makes a binding agreement to give the debtor extra time, without the surety's consent. (4) The creditor loses a security that was given at the time of the guarantee.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) Section 134 and (3) Section 135 discharge the surety; (4) discharges him to the extent of the value of the security lost (Section 141). (2) does not: mere forbearance to sue does not discharge the surety (Section 137).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-108","question":"A surety pays the whole debt to the creditor after the principal debtor defaults. What right does the surety get?","options":["Only a right to a share of the debtor's profits","None, because a guarantee is gratuitous","A right to sue the creditor","The creditor's rights against the debtor, including securities held (subrogation)"],"answer":3,"explanation":"On payment, the surety steps into the creditor's shoes (Section 140) and may recover the amount from the principal debtor (Section 145).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-109","question":"A, B and C separately guarantee the same debt with limits of ₹1 lakh, ₹2 lakh and ₹3 lakh, with no agreement among themselves. The debtor defaults on ₹4 lakh. How much does C bear?","options":["₹2 lakh","₹1.5 lakh","₹1.33 lakh","₹3 lakh"],"answer":1,"explanation":"Section 147: co-sureties bound in different sums pay equally as far as their limits allow. Equal shares would be ₹1.33 lakh each, but A's limit is ₹1 lakh; the remaining ₹3 lakh is shared equally by B and C: ₹1.5 lakh each. Sharing in proportion to limits (₹2 lakh) is wrong.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-110","question":"Which of these is a bailment?","options":["Leaving a car with a mechanic for repair","Depositing money in a savings account","Parking in a self-park lot while keeping the car keys","Buying goods on credit"],"answer":0,"explanation":"Bailment is delivery of goods for a purpose, to be returned or dealt with as directed. A bank deposit is a debt, not bailment of the same notes; keeping your keys means no delivery of possession.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-111","question":"A bailee takes the care of the goods that a prudent person would take of his own similar goods, but they are stolen by armed robbers. There is no special contract. Is the bailee liable?","options":["Yes, a bailee is an insurer of the goods","Yes, but only for half the value","No, because he took the care required of a bailee","Only if the goods were valuable"],"answer":2,"explanation":"Sections 151–152: a bailee must take the care of a man of ordinary prudence; having done so, he is not liable for loss in the absence of a special contract.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-112","question":"Which of these statements about liens are correct? (1) A tailor may keep a suit until he is paid for stitching it. (2) Without any agreement, a tailor may keep a suit to recover dues on earlier, already delivered suits. (3) Bankers have a general lien. (4) Wharfingers have a general lien.","options":["(1) and (3) only","(1), (3) and (4) only","(2), (3) and (4) only","All four"],"answer":1,"explanation":"(1) is a particular lien for skill and labour on the goods (Section 170). (2) would need a general lien, which only bankers, factors, wharfingers, attorneys of a High Court and policy brokers have, or one given by agreement (Section 171).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-113","question":"A mercantile agent in possession of goods with the owner's consent pledges them, in the ordinary course of business, to a pawnee who acts in good faith and has no notice of any lack of authority. Is the pledge valid?","options":["No, only the owner can pledge goods","Only if the owner later ratifies it","No, it is void as against the owner","Yes, it is as valid as if the owner had expressly authorised it"],"answer":3,"explanation":"Section 178 protects a good-faith pawnee who takes a pledge from a mercantile agent in possession with the owner's consent, acting in the ordinary course of business.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-114","question":"A pawns gold for a loan of ₹1,00,000 and defaults. After reasonable notice, the pawnee sells the gold for ₹1,30,000, incurring sale expenses of ₹5,000. What happens to the proceeds?","options":["The pawnee keeps the ₹30,000","₹30,000 is paid to the pawnor","₹1,25,000 is paid to the pawnor","₹25,000 is paid to the pawnor"],"answer":3,"explanation":"Section 176: on default and reasonable notice, the pawnee may sell; he recovers the debt and sale expenses, and any surplus goes to the pawnor: 1,30,000 − 1,00,000 − 5,000 = ₹25,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-115","question":"In agency, the person for whom the agent acts is called the:","options":["Principal","Bailor","Surety","Promisee"],"answer":0,"explanation":"An agent is employed to act for, or represent, another person, called the principal (Section 182).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-116","question":"An agent exceeds his authority and buys two machines on the principal's behalf. The principal wants to ratify the purchase of one and reject the other, which were bought in one transaction. Can he?","options":["No: ratifying part of a transaction ratifies the whole of it","Yes, he may ratify any part he chooses","Yes, but he must pay the agent's commission","Only with the seller's consent"],"answer":0,"explanation":"Section 199: a person ratifying an unauthorised act done on his behalf ratifies the whole transaction of which it forms part.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-117","question":"A authorises B to sell A's land and to pay himself, out of the proceeds, a debt that A owes him. A later wants to revoke B's authority, and then A dies. What is the position?","options":["A can revoke at any time, and his death ends the agency","The authority cannot be revoked, and A's death does not end it, because B has an interest in the subject matter","Only A's legal heirs can revoke it","The agency ends when the debt becomes due"],"answer":1,"explanation":"Section 202: where the agent has an interest in the property that is the subject of the agency, the agency cannot be ended to the prejudice of that interest, even by the principal's death or insanity.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-118","question":"An agent contracts with a third party without disclosing that he acts for a principal. The third party later discovers the principal. Whom can the third party hold liable?","options":["Only the agent","Only the principal","Neither, because the contract is void","Either the agent or the principal"],"answer":3,"explanation":"With an undisclosed principal, the third party can enforce the contract against the agent, or against the principal on discovering him (Section 231 and the following provisions).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-119","question":"How many of these statements are correct? (1) A sub-agent acts under the control of the original agent. (2) The agent is responsible to the principal for the acts of a properly appointed sub-agent. (3) A properly appointed sub-agent is directly responsible to the principal for ordinary negligence. (4) A substituted agent, named with the principal's authority, becomes the principal's own agent.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 191, 192 and 194). (3) is wrong: a sub-agent is responsible to the principal only for fraud or wilful wrong, otherwise only to the agent.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-120","question":"Which of these ordinarily ends an agency?","options":["The agent's change of address","A rise in the price of the goods","The death or insanity of the principal or the agent","The principal's failure to sign a letter"],"answer":2,"explanation":"Section 201: an agency ends on revocation, renunciation, completion of the business, death or insanity of either party, or the principal's insolvency (subject to the exception for agency coupled with interest).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-121","question":"Under the Sale of Goods Act, how does a 'sale' differ from an 'agreement to sell'?","options":["In a sale, ownership passes to the buyer at once; in an agreement to sell, it passes later or on fulfilment of conditions","In a sale, the price is paid later","An agreement to sell must be in writing","There is no difference"],"answer":0,"explanation":"A sale transfers property in the goods immediately; an agreement to sell becomes a sale when the time elapses or the conditions are met.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-122","question":"What remedy does a buyer have for a breach of warranty, as opposed to a breach of condition?","options":["He may reject the goods and claim damages","He may claim damages only, not reject the goods","He may only reject the goods","He has no remedy"],"answer":1,"explanation":"A condition is essential to the main purpose; its breach allows repudiation. A warranty is collateral; its breach gives only a claim for damages.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-123","question":"A buyer accepts goods under a contract that is not severable and later discovers a breach of a condition. What can he do (absent any contrary term)?","options":["Reject the goods and recover the price","Rescind the contract at any time","Nothing at all","Claim damages only, treating the breach of condition as a breach of warranty"],"answer":3,"explanation":"Section 13(2): once a buyer has accepted the goods under a non-severable contract, a breach of condition can be treated only as a breach of warranty.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-124","question":"In a sale by sample as well as by description, the goods must:","options":["Correspond with the sample only","Correspond with the description only","Correspond with both the sample and the description","Only be of merchantable quality"],"answer":2,"explanation":"Section 15: where goods are sold by sample as well as description, it is not enough that the bulk matches the sample if it does not also match the description.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-125","question":"A buyer asks a chemist for a hot-water bottle and relies on the chemist's choice. The bottle bursts on first use and injures her. Which is correct?","options":["The seller is liable: the purpose was made known, the buyer relied on his skill and the goods were unfit for it","No liability, because of caveat emptor","Liability only if the bottle carried a brand name","Only the manufacturer can be liable"],"answer":0,"explanation":"Section 16(1) implies a condition of fitness for purpose when the buyer makes the purpose known (it can be obvious, as here) and relies on the seller's skill or judgment, and the seller deals in such goods.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-126","question":"How many of these are implied in a contract of sale (unless excluded)? (1) A condition that the seller has the right to sell (2) A warranty that the buyer will enjoy quiet possession (3) A condition that the goods are fit for any purpose the buyer privately has in mind (4) A condition of merchantable quality where goods are bought by description from a seller who deals in such goods","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are implied (Sections 14 and 16(2)). (3) is not: fitness for purpose is implied only when the purpose is made known and the buyer relies on the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-127","question":"A buys a specific car that is in a deliverable state; delivery and payment are fixed for next week. That night the car is destroyed by fire without the seller's fault. Who bears the loss?","options":["The seller, because the car was still with him","They share it equally","The insurer only","The buyer, because property, and with it the risk, passed when the contract was made"],"answer":3,"explanation":"Section 20: for an unconditional contract for specific goods in a deliverable state, property passes when the contract is made, even if payment and delivery are postponed; risk prima facie passes with property (Section 26).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-128","question":"A agrees to sell B a specific heap of rice at ₹40 a kg; the seller must weigh it to fix the price. Before it is weighed, the rice is destroyed by flood without anyone's fault. Who bears the loss?","options":["The buyer, because the goods were specific","The seller, because property does not pass until the goods are weighed and the buyer is told","They share it in proportion","Neither: the contract is voidable"],"answer":1,"explanation":"Section 22: where the seller must weigh, measure or test specific goods to fix the price, property passes only when that is done and the buyer has notice. Risk therefore stayed with the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-129","question":"Goods are delivered to B on approval ('sale or return'). Before approving them, B pledges the goods with a moneylender. What is the effect?","options":["Property passes to B, as the pledge is an act adopting the transaction, and he is liable for the price","Nothing changes; B can still return the goods","The pledge is void","Property passes only when B pays"],"answer":0,"explanation":"Section 24: property passes on approval, on any other act adopting the transaction (such as pledging or selling the goods), or on retaining them beyond the fixed or a reasonable time.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-130","question":"Which of these is NOT an exception to the rule that no one can give a better title than he himself has?","options":["Sale by a mercantile agent in possession with the owner's consent","Sale by a seller who stays in possession after a sale","Sale by a person with a voidable title before it is rescinded","Sale by a thief to an innocent buyer for value"],"answer":3,"explanation":"The Act protects good-faith buyers in the first three situations. A thief has no title at all, so even an innocent buyer for value gets none.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-131","question":"Who is an 'unpaid seller' under the Sale of Goods Act?","options":["A seller who has received the whole price in cash","A seller paid by a cheque that was honoured","A seller who received a cheque that was later dishonoured","A seller paid in full by bank transfer"],"answer":2,"explanation":"Section 45: a seller is unpaid when the whole price has not been paid or tendered, or when a negotiable instrument received as conditional payment has been dishonoured.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-132","question":"When can an unpaid seller exercise the right of stoppage in transit?","options":["Whenever any part of the price is unpaid","When the buyer has become insolvent and the goods are still in transit","Only before the goods are handed to the carrier","Only if he holds the bill of lading"],"answer":1,"explanation":"Stoppage in transit (Section 50) is available only on the buyer's insolvency while the goods are with a carrier. Before handing over, the seller relies on his lien instead.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-133","question":"How many of these statements about an unpaid seller's rights are correct? (1) The lien depends on the seller keeping possession. (2) Stoppage in transit is available even if the buyer is solvent. (3) The lien is lost when the buyer lawfully obtains possession. (4) The lien is lost merely because the seller has obtained a court decree for the price.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) and (3) are correct. (2) is wrong: stoppage needs insolvency. (4) is wrong: Section 49(2) says the seller does not lose his lien just because he has obtained a decree for the price.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-134","question":"At an auction that was not notified as subject to the seller's right to bid, the seller secretly employs a person to bid up the price. What can the buyer do?","options":["Nothing, as bidding by anyone is allowed","Only claim the difference in price","Report it but remain bound","Treat the sale as fraudulent"],"answer":3,"explanation":"Section 64: unless the right to bid is expressly reserved and notified, the seller may not bid or employ anyone to bid, and a sale in breach may be treated as fraudulent by the buyer.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-135","question":"A buyer ordered 100 units; the seller delivers 120. What may the buyer do?","options":["Accept 100 and reject 20, reject all 120, or accept all 120 at the contract rate","He must accept all 120","He must reject all 120","He may accept all 120 at a price he chooses"],"answer":0,"explanation":"Section 37 gives the buyer these choices when a larger quantity is delivered; if a smaller quantity is delivered, he may reject it or accept it and pay at the contract rate.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-136","question":"Which of these is NOT a negotiable instrument under the Negotiable Instruments Act, 1881?","options":["Promissory note","Bill of exchange","Cheque","Share certificate"],"answer":3,"explanation":"The Act names promissory notes, bills of exchange and cheques; a share certificate is evidence of title to shares, not a negotiable instrument under this Act.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-137","question":"A cheque is:","options":["A bill of exchange payable after a fixed period","A bill of exchange drawn on a specified banker and payable only on demand, including electronic and truncated cheques","A promissory note issued by a bank","Any written order to pay money"],"answer":1,"explanation":"Section 6 defines a cheque this way; it is always on a banker and always payable on demand.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-138","question":"X receives a cheque from Y as a birthday gift and takes it in good faith before it is due. Is X a holder in due course?","options":["Yes, because he took it in good faith","Yes, because it was before maturity","No, because he did not take it for consideration","Only if Y was the drawer"],"answer":2,"explanation":"A holder in due course must obtain the instrument for consideration, before maturity and without cause to believe there is any defect in the transferor's title (Section 9). A gift fails the consideration test.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-139","question":"How many of these statements are correct? (1) A holder in due course can get a better title than his transferor. (2) A holder who takes through a holder in due course and was not a party to any fraud has the same rights. (3) A holder in due course of a forged instrument can enforce it against the person whose signature was forged. (4) Every holder is presumed to be a holder in due course until the contrary is proved.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) (Section 53) and (4) (Section 118(g)) are correct. (3) is wrong: a forgery is a nullity and gives no title, even to a holder in due course.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-140","question":"A cheque has two parallel transverse lines with 'HDFC Bank Ltd' written between them. This is a:","options":["Special crossing: it will be paid only to HDFC Bank, as collecting banker","General crossing","Not-negotiable crossing","Open cheque"],"answer":0,"explanation":"Writing a banker's name across the cheque, with or without lines, is a special crossing (Section 124). Two lines alone would be a general crossing.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-141","question":"A cheque is dishonoured and the payee sends the statutory demand notice under Section 138, which the drawer receives on 5 March. By what date must the drawer pay to avoid the offence?","options":["17 March","20 March","1 April","4 April"],"answer":1,"explanation":"The drawer has 15 days from receipt of the notice: 5 March + 15 days = 20 March. If he fails, the cause of action arises the next day and the complaint must be filed within one month of that.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-142","question":"Notice of dishonour is NOT necessary to charge the drawer when:","options":["The drawee is a public-sector bank","The amount is small","The holder is a minor","The drawer has countermanded payment (stopped the cheque)"],"answer":3,"explanation":"Section 98 dispenses with notice in cases such as when the drawer has countermanded payment, when the party entitled has waived it, or when the party charged could suffer no damage from lack of notice.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-143","question":"In a promissory note, the person who promises to pay is called the:","options":["Drawer","Maker","Drawee","Endorsee"],"answer":1,"explanation":"A promissory note has a maker (who promises) and a payee. A bill of exchange has a drawer, a drawee and a payee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-144","question":"A bill dated 15 January is payable two months after date. Three days of grace apply, and the resulting date is a public holiday. On what date is the bill due?","options":["17 March","18 March","19 March","15 March"],"answer":0,"explanation":"Two months after 15 January is 15 March; adding three days of grace gives 18 March. Because that day is a public holiday, the bill falls due on the preceding business day (Section 25): 17 March.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-145","question":"Which of these is NOT a material alteration of a negotiable instrument?","options":["Changing the date","Changing the amount","Converting a blank endorsement into a full endorsement","Changing the place of payment"],"answer":2,"explanation":"A holder may convert a blank endorsement into a full one (Section 49) without it being a material alteration. Changing the date, amount or place of payment without consent voids the instrument against non-consenting parties.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-146","question":"An endorser writes 'sans recourse' with his endorsement. What is the effect?","options":["He becomes liable to all later holders","The instrument stops being negotiable","He guarantees payment by the drawee","He excludes his own liability to later holders"],"answer":3,"explanation":"Section 52 lets an endorser exclude his own liability by express words such as 'sans recourse'; the instrument stays negotiable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-147","question":"A cheque reads 'Pay Ramesh or order'. Ramesh endorses it by signing only his name on the back. To whom is it now payable?","options":["To the bearer","Only to Ramesh","Only to Ramesh's bank","To no one until a full endorsement is added"],"answer":0,"explanation":"An endorsement in blank (signature only) makes the instrument payable to bearer (Section 54), until it is converted into a full endorsement.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-148","question":"A signs a blank promissory note on adequately stamped paper and gives it to B to fill in ₹20,000. B fills in ₹50,000 (within the stamp's coverage) and negotiates it for value to C, a holder in due course. How much can C recover from A?","options":["₹20,000 only, the agreed amount","₹50,000, because the stamp covers that amount","Nothing, as the note was incomplete when signed","₹30,000, the excess"],"answer":1,"explanation":"Section 20 (inchoate stamped instruments): the signer is liable to a holder in due course for any amount filled in, up to the amount the stamp covers. As between A and B, only ₹20,000 was authorised.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-149","question":"A agrees to sell B a specific cargo of wheat on a ship. Unknown to both, the ship had already sunk with the cargo before the agreement. What is the effect?","options":["The seller must supply another cargo","The buyer must pay the price","The contract is voidable at the buyer's option","The agreement is void"],"answer":3,"explanation":"Section 7 of the Sale of Goods Act: a contract for specific goods that, without the seller's knowledge, have perished at the time of the contract is void.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-150","question":"If the price is not fixed by the contract or by any agreed method, the buyer must pay:","options":["A reasonable price","The price the seller demands","The cost price","Nothing, as the contract is void"],"answer":0,"explanation":"Section 9(2): where the price is not determined, the buyer pays a reasonable price, which depends on the circumstances of each case.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-151","question":"Which case established that a company is a legal person separate from its members, even when one person holds almost all its shares?","options":["Royal British Bank v Turquand","Ashbury Railway Carriage v Riche","Salomon v Salomon & Co","Hadley v Baxendale"],"answer":2,"explanation":"Salomon v Salomon & Co (1897) held that a duly incorporated company is a distinct person from its members, so Mr Salomon as a secured creditor ranked ahead of unsecured creditors.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-152","question":"What is the minimum number of members needed to form a private company (other than a one person company)?","options":["Two","Seven","One","Three"],"answer":0,"explanation":"A private company needs at least two members, a public company seven and a one person company one.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-153","question":"A company's articles allow directors to borrow if authorised by a general-meeting resolution. A lender, acting in good faith, lends to the company on the directors' word, but no resolution had been passed. Is the company bound?","options":["No, because the lender had constructive notice of the articles","Only if the shareholders ratify it","No, the loan is void","Yes, under the doctrine of indoor management, outsiders may assume internal procedures were complied with"],"answer":3,"explanation":"Royal British Bank v Turquand: an outsider who knows the articles permit the act need not check that internal formalities, such as passing a resolution, were actually carried out.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-154","question":"In which situation can an outsider NOT rely on the doctrine of indoor management?","options":["The company's internal resolution was passed late","The document he relied on was a forgery","The directors had not yet signed the minutes","The company had not filed its annual return"],"answer":1,"explanation":"The doctrine does not protect an outsider who knew of the irregularity, was put on enquiry by suspicious circumstances, or relied on a forged document, since a forgery is a nullity.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-155","question":"The doctrine of constructive notice means that a person dealing with a company is deemed to know:","options":["Its internal board minutes","The private agreements among its directors","The contents of its memorandum and articles, which are public documents","Its future business plans"],"answer":2,"explanation":"Once registered, the memorandum and articles are public documents, so outsiders are presumed to know their contents (indoor management protects them on internal matters).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-156","question":"A company enters into a contract wholly outside the objects in its memorandum. All the shareholders later pass a resolution ratifying it. What is the status of the contract?","options":["Void; an ultra vires act cannot be ratified even unanimously","Valid after unanimous ratification","Voidable at the company's option","Valid if the directors approved it"],"answer":0,"explanation":"Ashbury Railway Carriage v Riche: an act ultra vires the memorandum is void ab initio and cannot be ratified, even by all the shareholders.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-157","question":"At a general meeting, 600 votes are cast in favour of a resolution, 220 against and 300 members abstain. Which is correct?","options":["It passes as both an ordinary and a special resolution","It passes as an ordinary resolution but fails as a special resolution","It fails as both","It passes as a special resolution only"],"answer":1,"explanation":"Ordinary: votes for (600) exceed votes against (220). Special: votes for must be at least three times votes against, 3 × 220 = 660; 600 falls short. Abstentions are not counted.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-158","question":"A company's financial year ends on 31 March 2026, and its previous AGM was held on 20 August 2025. Without any extension, by when must its next AGM be held?","options":["30 September 2026","20 November 2026","31 December 2026","20 August 2026"],"answer":0,"explanation":"An AGM (other than the first) must be held within six months of the end of the financial year (30 September 2026) and within 15 months of the last AGM (20 November 2026). The earlier date, 30 September 2026, applies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-159","question":"A company's articles provide for 11 directors, but two seats are vacant. Under Section 174, quorum is one-third of the total strength (a fraction counts as one) or two directors, whichever is higher, and vacant seats are not counted in total strength. What is the quorum?","options":["4","2","3","6"],"answer":2,"explanation":"Total strength = 11 − 2 vacancies = 9. One-third of 9 = 3, which is more than two, so the quorum is 3. Counting the vacant seats gives one-third of 11 = 3.67, rounded to 4.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-160","question":"What is the minimum number of directors a public company must have?","options":["One","Two","Seven","Three"],"answer":3,"explanation":"Under Section 149, a public company needs at least three directors, a private company two and a one person company one.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-161","question":"Which requirement does the Companies Act, 2013 impose on every company's board?","options":["At least one director must be a chartered accountant","At least one director must have stayed in India for at least 182 days in the financial year","All directors must be Indian citizens","At least half the directors must be independent"],"answer":1,"explanation":"Section 149(3) requires at least one resident director, meaning one who has stayed in India for 182 days or more during the financial year. Independent-director requirements apply to listed and prescribed companies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-162","question":"A listed public company has 10 directors. At least one-third of the total directors must be independent, and any fraction is rounded up to one. What is the minimum number of independent directors?","options":["3","4","5","2"],"answer":1,"explanation":"One-third of 10 = 3.33; the fraction counts as one, so at least 4 independent directors are needed. Truncating to 3 is the usual error.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-163","question":"If a company's articles conflict with its memorandum, which prevails?","options":["The articles, being more detailed","The later document","Whichever the board chooses","The memorandum, because the articles are subordinate to it"],"answer":3,"explanation":"The memorandum is the charter defining the company's powers; the articles regulate internal management within those limits. A conflicting article is void to that extent.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-164","question":"A Section 8 company is formed for charitable objects. Which feature does it have?","options":["It must apply its profits to its objects and cannot pay dividends to members","It pays a fixed dividend to members","It must have at least seven members","It cannot own property"],"answer":0,"explanation":"A Section 8 company promotes objects such as charity, education or art, applies its income to those objects and is prohibited from paying dividends to its members.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-165","question":"A former employee bound by a valid non-compete covenant forms a company, controlled by him and his family, to solicit his old employer's customers. What will the court most likely do?","options":["Refuse relief, because the company is a separate person not bound by the covenant","Wind up the company","Award damages only against the family members","Lift the corporate veil and restrain both him and the company, as the company is a sham to evade his obligation"],"answer":3,"explanation":"Courts disregard the separate personality of a company used as a façade to evade an existing legal obligation (as in Gilford Motor Co v Horne).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-166","question":"Which element of the definition of partnership in Section 4 of the Indian Partnership Act reflects mutual agency?","options":["An agreement between persons","The business is carried on by all or any of them acting for all","Profits are shared","The business must be lawful"],"answer":1,"explanation":"'Carried on by all or any of them acting for all' means each partner is both an agent of the others and a principal, which is the true test of partnership.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-167","question":"An unregistered firm wants to sue a customer to recover money due under a contract. What is the position?","options":["It can sue freely","It can sue only in small-cause courts","It cannot sue the customer to enforce the contract, though the customer can sue the firm","It can sue only if all partners consent"],"answer":2,"explanation":"Section 69 bars an unregistered firm (and its partners on its behalf) from suing third parties to enforce contractual rights; third parties can still sue the firm, and partners can sue for dissolution or accounts.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-168","question":"Which of these can a partner do under his implied authority, without specific authority from the other partners?","options":["Buy goods of the kind the firm usually deals in, for its business","Submit a dispute of the firm to arbitration","Transfer immovable property belonging to the firm","Open a bank account for the firm in his own name"],"answer":0,"explanation":"Section 19(2) excludes arbitration, opening an account in his own name, compromising claims, transferring immovable property and similar acts from implied authority. Ordinary trading acts are within it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-169","question":"How many of these statements are correct? (1) A person admitted as a partner is not liable for the firm's debts incurred before he joined. (2) A retiring partner remains liable to third parties for the firm's acts until public notice of his retirement is given. (3) A deceased partner's estate is liable for the firm's acts done after his death. (4) A person who holds himself out as a partner is liable to anyone who gave credit to the firm on that basis.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 31, 32 and 28). (3) is wrong: under Section 35 the estate of a deceased partner is not liable for acts of the firm after his death.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-170","question":"In which situation is a firm compulsorily dissolved, without any court order?","options":["A partner becomes of unsound mind","The firm suffers a loss for one year","A partner transfers his share to an outsider","All the partners, or all but one, are adjudged insolvent"],"answer":3,"explanation":"Section 41: compulsory dissolution occurs on the insolvency of all, or all but one, partners, or when the business becomes unlawful. Unsoundness of mind is a ground for dissolution by the court (Section 44).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-171","question":"Under the LLP Act, 2008, what is the minimum requirement for designated partners?","options":["One designated partner","At least two designated partners, of whom at least one is resident in India","Seven designated partners","No designated partners are needed"],"answer":1,"explanation":"Every LLP must have at least two partners and at least two designated partners who are individuals, at least one of them resident in India.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-172","question":"How many of these statements about an LLP are correct? (1) It is a body corporate with perpetual succession. (2) A partner is personally liable for another partner's wrongful act. (3) There is no upper limit on the number of partners. (4) Mutual rights are governed by the LLP agreement, and where it is silent, by the First Schedule to the Act.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct. (2) is wrong: a partner is not personally liable for another partner's wrongful act or misconduct, though he is liable for his own.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-173","question":"A minor admitted to the benefits of a partnership attains majority and does not give any public notice within six months. What is his position?","options":["He automatically ceases to be connected with the firm","He is liable only from the date of attaining majority","He may never become a partner","He becomes a partner and is personally liable for the firm's acts from the date he was admitted to its benefits"],"answer":3,"explanation":"Section 30: if he fails to give public notice of his election within six months, he becomes a partner and is personally liable for all acts of the firm since he was admitted to its benefits.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-174","question":"In a partnership at will, one partner wants to end the firm. What must he do?","options":["Give written notice to all the other partners of his intention to dissolve the firm","Obtain the consent of all partners","Apply to the court in every case","Wait until the firm makes a loss"],"answer":0,"explanation":"Section 43: a partnership at will may be dissolved by any partner giving notice in writing to all the other partners; it is dissolved from the date mentioned in the notice or the date of communication.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-175","question":"Company A holds 30% of Company B's shares but has the power to appoint and remove all of B's directors. Is B a subsidiary of A?","options":["No, because A holds less than half the shares","Yes, because A controls the composition of B's board","Only if A also holds preference shares","Only if B's articles say so"],"answer":1,"explanation":"Under Section 2(87), control of the composition of the board of directors is enough to make a company a subsidiary, regardless of shareholding.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-176","question":"Copyright protects:","options":["Inventions with industrial application","Brand names and logos","The geographical origin of goods","Original literary, artistic, musical and dramatic works"],"answer":3,"explanation":"Copyright protects the original expression of a work. Inventions are protected by patents, brand identifiers by trademarks and origin-linked goods by geographical indications.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-177","question":"A new process for making a medicine is protected by a:","options":["Trademark","Patent","Copyright","Design registration"],"answer":1,"explanation":"A patent protects an invention, a product or a process, that is new, involves an inventive step and is capable of industrial application.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-178","question":"A distinctive logo that identifies a company's goods in the market is protected as a:","options":["Patent","Geographical indication","Trademark","Copyright only"],"answer":2,"explanation":"A trademark is a mark capable of distinguishing one person's goods or services from another's, such as a logo, name or label.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-179","question":"A writes a bestselling novel about a school for young wizards. B writes his own novel on the same broad idea, with entirely different characters, plot and text. Has B infringed A's copyright?","options":["No: copyright protects the expression, not the underlying idea","Yes, because the idea was copied","Only if B's book sells more copies","Only if B fails to credit A"],"answer":0,"explanation":"Copyright does not protect ideas, themes or plots in the abstract, only their particular expression. Substantial copying of expression would be needed for infringement.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-180","question":"Under Section 3(d) of the Patents Act, a new form of a known substance is:","options":["Patentable if it is cheaper to make","Patentable for ten years","Patentable if it is patented abroad","Not patentable unless it shows significantly enhanced efficacy"],"answer":3,"explanation":"Section 3(d), applied in the Novartis case, excludes mere new forms of known substances unless they differ significantly in efficacy, to prevent 'evergreening' of patents.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-181","question":"'Darjeeling Tea' is protected in India as a:","options":["Patent","Geographical indication","Copyright","Industrial design"],"answer":1,"explanation":"A geographical indication identifies goods as originating in a territory where a given quality or reputation is essentially due to that origin.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-182","question":"Which set correctly states the three tests an invention must pass to be patentable in India?","options":["Novelty, aesthetic appeal and commercial success","Inventive step, a registered trademark and novelty","Novelty, inventive step and industrial applicability","Industrial applicability, public demand and originality of expression"],"answer":2,"explanation":"An invention must be new, involve an inventive step (not obvious to a skilled person) and be capable of industrial application. Aesthetic appeal relates to designs and originality of expression to copyright.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-183","question":"Under the Consumer Protection Act, 2019, who is NOT a consumer?","options":["A trader who buys mobile phones to resell them","A person who buys a phone online for personal use","A person who hires a taxi for a family trip","A self-employed tailor who buys a sewing machine to earn his livelihood"],"answer":0,"explanation":"A person who buys goods for resale or for a commercial purpose is excluded; buying for self-employment to earn a livelihood is allowed, and online purchases are covered.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-184","question":"Under the Consumer Protection Act, 2019, a product liability action can be brought against:","options":["Only the manufacturer","Only the retailer","Only the advertiser","The product manufacturer, product service provider or product seller, as the case may be"],"answer":3,"explanation":"The 2019 Act introduced product liability, making manufacturers, service providers and sellers liable for harm caused by defective products or deficient services, under specified conditions.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-185","question":"Under the Consumer Protection Act, 2019, where can a consumer file a complaint?","options":["Only where the seller has its head office","Also where the complainant resides or personally works for gain","Only in Delhi","Only where the goods were manufactured"],"answer":1,"explanation":"The 2019 Act allows a complaint to be filed where the complainant resides or personally works for gain, in addition to the opposite party's location or where the cause of action arose; it also permits e-filing.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-186","question":"Under the Consumer Protection Act, 2019, the pecuniary jurisdiction of the commissions is based on:","options":["The compensation the consumer claims","The complainant's income","The value of the goods or services paid as consideration","The number of complainants"],"answer":2,"explanation":"The 2019 Act shifted the test from compensation claimed to the value of consideration paid for the goods or services, which prevents forum shopping by inflating claims.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-187","question":"Which body, created by the Consumer Protection Act, 2019, can order recall of unsafe goods, penalise endorsers of misleading advertisements and start class actions?","options":["Central Consumer Protection Authority","National Consumer Disputes Redressal Commission","Competition Commission of India","Bureau of Indian Standards"],"answer":0,"explanation":"The CCPA is a regulator that protects consumers as a class; the commissions decide individual disputes.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-188","question":"A Maharashtra trader makes intra-state taxable supplies of ₹20,00,000 at 18% (assume). Its intra-state purchases of ₹12,00,000 carried 18% GST, but ₹1,00,000 of these purchases was food for a staff party (blocked credit). There are no other items. How much GST does it pay in cash?","options":["₹1,44,000","₹1,62,000","₹1,80,000","₹3,60,000"],"answer":1,"explanation":"Output tax = 3,60,000. Total input GST = 2,16,000, of which 18,000 on the staff food is blocked; eligible ITC = 1,98,000. Cash = 3,60,000 − 1,98,000 = ₹1,62,000. Claiming the blocked credit gives ₹1,44,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-189","question":"A Delhi company's output tax this month is CGST ₹50,000 and SGST ₹50,000. It also received legal services of ₹1,00,000 under reverse charge at 18% (assume), intra-state. Its credit ledger already holds CGST ₹70,000 and SGST ₹70,000. What is the minimum cash it must pay this month?","options":["Nil","₹1,18,000","₹30,000","₹18,000"],"answer":3,"explanation":"Reverse-charge tax (CGST 9,000 + SGST 9,000 = ₹18,000) must be paid in cash. The forward-charge output of ₹1,00,000 can be fully met from the existing credit. The ₹18,000 then becomes available as ITC.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-190","question":"A trader bought goods for ₹5,00,000 plus GST of ₹90,000 and claimed the full input tax credit. Goods costing ₹1,00,000 are later destroyed in a fire. What must he do about the credit?","options":["Reverse ₹18,000","Reverse ₹90,000","Nothing","Reverse ₹9,000"],"answer":0,"explanation":"Credit is blocked on goods lost, stolen or destroyed, so the credit on the destroyed goods (18% of 1,00,000 = ₹18,000) must be reversed.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-191","question":"An individual has salary income of ₹3,00,000, non-speculative business income of ₹4,00,000, a speculation business loss of ₹60,000, a short-term capital loss of ₹30,000 and a long-term capital gain of ₹50,000. What is the gross total income?","options":["₹6,60,000","₹7,50,000","₹7,20,000","₹6,90,000"],"answer":2,"explanation":"The short-term loss can be set off against the long-term gain: 50,000 − 30,000 = 20,000. A speculation loss can be set off only against speculation income, so it is carried forward. GTI = 3,00,000 + 4,00,000 + 20,000 = ₹7,20,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-192","question":"Assume a deduction for specified savings capped at ₹1,50,000. An individual pays provident fund ₹90,000, life insurance premium ₹40,000, children's tuition fees ₹30,000 and home-loan principal ₹50,000, all eligible. What is the deduction?","options":["₹2,10,000","₹1,50,000","₹1,60,000","₹1,20,000"],"answer":1,"explanation":"Eligible payments total ₹2,10,000, but the deduction is capped at ₹1,50,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-193","question":"An individual's total tax liability for the year is ₹1,20,000. Tax of ₹80,000 was deducted at source and ₹30,000 was paid as advance tax. Ignoring interest, how much self-assessment tax is payable?","options":["₹40,000","₹90,000","₹1,10,000","₹10,000"],"answer":3,"explanation":"TDS and advance tax are credited against the final liability: 1,20,000 − 80,000 − 30,000 = ₹10,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-194","question":"A 17-year-old falsely tells a lender he is 19 and borrows ₹50,000. Which is correct?","options":["The agreement is void, and the minor is not estopped from pleading his minority","The minor is bound because he lied about his age","The agreement becomes valid if he ratifies it at 18","The lender can sue the minor's parents on the contract"],"answer":0,"explanation":"An agreement with a minor is void, and the rule of estoppel does not apply against a minor, so he can plead minority despite his misstatement. A void agreement cannot be ratified, and parents are not liable on it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-195","question":"A famous singer refuses to perform at a concert as contracted. What remedy will a court usually give the organiser?","options":["Specific performance compelling the singer to perform","An order forcing the performance plus damages","Damages, since contracts for personal service are not specifically enforced","Nothing, since performance is personal"],"answer":2,"explanation":"Courts do not compel personal performance; the organiser gets damages (and, in suitable cases, an injunction restraining the singer from performing elsewhere in breach of a negative covenant).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-196","question":"A lends his car to B free of charge for a month. After a week, A needs it back. What is the position?","options":["A must wait until the month ends","A can demand it only if B misuses it","A cannot ask for it, since the bailment is for a fixed term","A can demand it early, but must indemnify B if B, having acted on the loan, suffers loss greater than the benefit he received"],"answer":3,"explanation":"Section 159: a lender in a gratuitous bailment may require return at any time, even before the agreed time, but must indemnify the bailee if the bailee, acting on the loan, suffers loss exceeding the benefit derived.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-197","question":"A government hospital provides treatment entirely free of charge to all patients. A patient alleges negligent treatment. Can he file a complaint under the Consumer Protection Act?","options":["Yes, it is a deficiency in service and the hospital is liable","No: services rendered entirely free of charge are outside the definition of 'service'","Only against the doctor personally","Only directly before the National Commission"],"answer":1,"explanation":"'Service' under the Act excludes services rendered free of charge. Where a hospital charges some patients, its free services can also be covered, but a wholly free service is not (Indian Medical Association v V.P. Shantha).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-198","question":"For a published literary work, how long does copyright generally last in India?","options":["The author's lifetime plus 60 years","50 years from publication","20 years from creation","The author's lifetime plus 70 years"],"answer":0,"explanation":"Under the Copyright Act, 1957, copyright in a published literary, dramatic, musical or artistic work lasts for the author's lifetime plus 60 years.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-199","question":"How many of these statements are correct? (1) An action for infringement requires a registered trademark. (2) Passing off can protect the goodwill of even an unregistered mark. (3) Once granted, a trademark registration lasts forever without renewal. (4) A patent protects an invention for a limited term, after which anyone may use it.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: a trademark registration is for a limited period and must be renewed, though it can be renewed indefinitely.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-200","question":"Which of these can be paid using the balance in a taxpayer's GST electronic credit ledger?","options":["Interest for delayed payment","Late fee for filing a return late","Tax payable under reverse charge","Output tax on outward supplies under forward charge"],"answer":3,"explanation":"Section 49(4) allows the credit ledger to be used only for output tax, and reverse-charge tax is excluded from that. Interest, late fees and penalties must be paid from the cash ledger.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-201","question":"A consultant receives an advance of ₹2,00,000 on 5 June, completes the service on 10 June and issues the invoice on 20 June, within the time allowed. Under GST, what is the time of supply for the advance?","options":["10 June","5 June","20 June","30 June"],"answer":1,"explanation":"For services, when the invoice is issued within the prescribed period, the time of supply is the earlier of the invoice date and the date payment is received. The advance came first, so tax on it is due with reference to 5 June.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-202","question":"A service is completed on 1 May. The invoice should have been issued within 30 days but is issued only on 15 June, and payment is received on 20 June. What is the time of supply under GST?","options":["15 June","20 June","1 May","31 May"],"answer":2,"explanation":"When the invoice is not issued within the prescribed period, the time of supply is the earlier of the date of provision of service and the date of receipt of payment. Provision on 1 May comes first. A late invoice cannot postpone the tax point.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-203","question":"A company receives a service taxable under reverse charge. The supplier's invoice is dated 1 March; the company pays the supplier on 15 May. Under GST, the time of supply is the earlier of the payment date and the date immediately after 60 days from the invoice date. Which date is it?","options":["15 May","1 March","1 May","1 June"],"answer":2,"explanation":"Sixty days from 1 March runs to 30 April, so the date immediately after is 1 May. That is earlier than the 15 May payment, so the time of supply is 1 May and the company must pay the reverse-charge tax with reference to it, even though it has not yet paid the supplier.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-204","question":"A company supplies goods to a related company that makes mainly exempt supplies and so is not eligible for full input tax credit. The invoice price is lower than the open market value of such goods. How is the taxable value determined?","options":["The invoice price, since it was agreed between the parties","Cost of production plus 10%, in every case","The open market value of the supply","Nil, as supplies between related persons are not supplies"],"answer":2,"explanation":"Between related persons the transaction value is not accepted where price is influenced by the relationship; the open market value is used (falling back to like goods, then cost plus 10%, only if it is not available). The invoice value is accepted as open market value only when the recipient is eligible for full input tax credit.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-205","question":"A customs broker charges a client ₹50,000 as its fee. It also pays ₹2,00,000 of customs duty on the client's behalf as a pure agent (shown separately and recovered at actual) and spends ₹5,000 on its own staff travel to do the job, which it also recovers from the client. What is the taxable value of the broker's service?","options":["₹2,55,000","₹50,000","₹55,000","₹2,50,000"],"answer":2,"explanation":"Amounts paid as a pure agent on the client's behalf and recovered at actual are excluded from value, so the duty is out. The broker's own travel costs are incurred for its own service and are part of the value: 50,000 + 5,000 = ₹55,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-206","question":"Goods have a list price of ₹1,00,000. The invoice shows a 2% discount on list price given at the time of supply, and separately charges packing of ₹3,000. Freight of ₹5,000, which was the supplier's liability under the contract, is paid by the buyer directly to the transporter and not shown on the invoice. GST is charged separately. What is the taxable value?","options":["₹1,01,000","₹1,08,000","₹1,06,000","₹1,03,000"],"answer":2,"explanation":"Start at 1,00,000 − 2% = ₹98,000 (an invoice discount at the time of supply is excluded). Add packing ₹3,000 and the ₹5,000 the buyer paid on the supplier's behalf, which forms part of the consideration: ₹1,06,000. ₹1,01,000 misses the freight; ₹1,08,000 ignores the discount.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-207","question":"A business's input tax credit for a month is ₹3,00,000: ₹60,000 on inputs used only for taxable supplies, ₹40,000 used only for exempt supplies, ₹20,000 blocked (for personal consumption), and ₹1,80,000 on common inputs. Turnover for the month is ₹90 lakh taxable and ₹30 lakh exempt. How much credit can it keep?","options":["₹1,95,000","₹2,25,000","₹2,40,000","₹1,80,000"],"answer":0,"explanation":"Credit used only for taxable supplies is kept in full (₹60,000); exempt-only and blocked credit go out entirely. Common credit is apportioned by turnover: 1,80,000 × 90/120 = ₹1,35,000. Total ₹1,95,000. ₹2,25,000 apportions the whole ₹3,00,000; ₹2,40,000 does not apportion the common credit.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-208","question":"How many of these are conditions for a registered person to take input tax credit? (1) It holds a tax invoice or other prescribed document. (2) It has received the goods or services. (3) The tax charged has actually been paid to the government. (4) It has furnished its return. (5) It has already paid the supplier the full value before taking credit.","options":["Three","Five","Two","Four"],"answer":3,"explanation":"(1) to (4) are statutory conditions. (5) is not: credit can be taken before paying the supplier; it must only be reversed if the value and tax are not paid within 180 days of the invoice.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-209","question":"A machine is bought under one invoice but delivered in three lots in July, August and September. When can the buyer take input tax credit for it?","options":["In July, on receipt of the first lot","One-third in each month","When the invoice is paid","On receipt of the last lot in September"],"answer":3,"explanation":"Where goods under one invoice arrive in lots or instalments, credit is available only on receipt of the last lot or instalment.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-210","question":"For a manufacturer, input tax credit is available on which of these? (1) A truck used to transport its goods (2) Food and beverages for an office party it is not legally required to provide (3) Construction of its factory building (4) A works contract for installing plant and machinery","options":["(1), (3) and (4) only","(2) and (4) only","(1) and (2) only","(1) and (4) only"],"answer":3,"explanation":"Motor vehicles used to transport goods are outside the block. Food and beverages (unless provided under a legal obligation) and construction of immovable property such as a factory building are blocked. Works contracts for plant and machinery are allowed, since plant and machinery excludes buildings and civil structures.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-211","question":"Under the TDS system, who deducts the tax and deposits it with the government?","options":["The person making the payment (the deductor)","The person receiving the payment (the deductee)","The bank through which payment is made","The tax department, from the deductee's account"],"answer":0,"explanation":"The payer deducts tax at the time of credit or payment and deposits it; the payee gets credit for it against his own tax liability.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-212","question":"Under tax collected at source (TCS), who collects the tax?","options":["The buyer, from the seller","The employer, from the employee's salary","The tax department, from both parties","The seller, from the buyer, in the specified transactions"],"answer":3,"explanation":"TCS is the mirror image of TDS: the seller (or receiver of money in specified cases) collects tax from the buyer along with the price and deposits it, and the buyer gets credit for it.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-213","question":"A company pays a professional ₹3,00,000 as fees plus GST of ₹54,000 shown separately on the invoice. Assume TDS of 10% applies and that, where GST is shown separately, TDS is computed on the amount excluding GST. How much tax is deducted?","options":["₹30,000","₹35,400","₹27,000","₹5,400"],"answer":0,"explanation":"TDS is on the fee alone: 10% × 3,00,000 = ₹30,000. ₹35,400 wrongly includes the GST; ₹5,400 applies the rate to the GST only.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-214","question":"Assume listed equity shares held for more than 12 months give long-term capital gains, taxed at 12.5% on the gain exceeding ₹1,25,000 a year, without indexation. Shares bought for ₹6,00,000 two years ago are sold for ₹10,25,000, with brokerage of ₹5,000 on the sale. There are no other gains. What is the tax (ignoring cess and surcharge)?","options":["₹36,875","₹52,500","₹37,500","₹59,000"],"answer":0,"explanation":"Gain = 10,25,000 − 5,000 − 6,00,000 = ₹4,20,000. Taxable = 4,20,000 − 1,25,000 = ₹2,95,000; tax at 12.5% = ₹36,875. ₹52,500 ignores the ₹1,25,000 exemption; ₹37,500 ignores the brokerage; ₹59,000 uses 20%.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-215","question":"An individual has a long-term gain of ₹80 lakh on selling a residential house and claims exemption by investing ₹50 lakh in a new house. Assume the rule that if the new house is sold within three years of purchase, its cost is reduced by the exemption claimed when computing the gain. Two years later he sells the new house for ₹60 lakh. What is the short-term capital gain?","options":["₹10 lakh","Nil","₹50 lakh","₹60 lakh"],"answer":3,"explanation":"The ₹50 lakh exemption is withdrawn by reducing the new house's cost: 50 − 50 = nil. Short-term gain = 60 − 0 = ₹60 lakh. ₹10 lakh ignores the withdrawal of the exemption.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-216","question":"Assume listed shares are long-term if held for more than 12 months, and land and unlisted shares if held for more than 24 months. Which classification is correct for: (a) listed shares held 14 months, (b) land held 20 months, (c) unlisted shares held 30 months?","options":["(a) long-term, (b) short-term, (c) long-term","(a) short-term, (b) short-term, (c) long-term","(a) long-term, (b) long-term, (c) long-term","(a) long-term, (b) short-term, (c) short-term"],"answer":0,"explanation":"(a) 14 months exceeds 12, so long-term; (b) 20 months does not exceed 24, so short-term; (c) 30 months exceeds 24, so long-term.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-217","question":"In the same year an individual has short-term capital gain ₹2,00,000, long-term capital gain ₹3,00,000, short-term capital loss ₹3,00,000 and long-term capital loss ₹1,00,000. A short-term loss can be set off against any capital gain; a long-term loss only against long-term gain. What capital gain remains taxable?","options":["₹2,00,000","₹1,00,000","₹5,00,000","Nil"],"answer":1,"explanation":"Long-term loss against long-term gain: 3,00,000 − 1,00,000 = ₹2,00,000. Short-term loss ₹3,00,000 wipes out short-term gain ₹2,00,000 and the remaining ₹1,00,000 reduces long-term gain to ₹1,00,000. ₹2,00,000 wrongly confines the short-term loss to short-term gains and carries the excess forward.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-218","question":"Under GST, a manufacturer's capital goods carry input tax credit of ₹6,00,000 and are used for both taxable and exempt supplies. The common credit on capital goods is spread over a useful life of 5 years (60 months). In a month where exempt turnover is 25% of total turnover, how much of that month's credit is attributable to exempt supplies?","options":["₹10,000","₹1,50,000","₹7,500","₹2,500"],"answer":3,"explanation":"Monthly credit = 6,00,000 ÷ 60 = ₹10,000; the exempt share is 25% × 10,000 = ₹2,500 (and ₹7,500 is kept). ₹1,50,000 applies 25% to the whole credit at once.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-219","question":"A supplier removes goods for delivery on 10 August but issues the invoice only on 14 August; payment is received on 1 September. The invoice was required to be issued before or at the time of removal. What is the time of supply under GST?","options":["10 August","14 August","1 September","31 August"],"answer":0,"explanation":"For goods, the time of supply is the earlier of the invoice date (or the last date on which it should have been issued) and the payment date. The invoice was due by removal on 10 August, so issuing it late does not shift the time of supply.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-220","question":"An Indian company buys consultancy services for its business from a firm in the US that has no presence in India. How is GST paid?","options":["The US firm must register in India and charge IGST","The Indian company pays IGST under reverse charge","No GST, as the supplier is outside India","The Indian company pays CGST and SGST under forward charge"],"answer":1,"explanation":"Import of services is an inter-state supply, and when the supplier is outside India the recipient pays IGST under reverse charge. It can then claim that tax as input tax credit if used for business.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-221","question":"Assume that any business expense paid in cash to one person in one day above ₹10,000 is disallowed. A business pays a supplier in cash ₹9,000 on 3 May and ₹8,000 on 4 May (separate bills), and pays a contractor ₹15,000 in cash on 10 May. How much is disallowed?","options":["₹32,000","₹15,000","₹17,000","Nil"],"answer":1,"explanation":"The limit is per person per day. The supplier was paid ₹9,000 and ₹8,000 on different days, each within the limit. The contractor's ₹15,000 in one day exceeds it, so the whole ₹15,000 is disallowed. ₹17,000 wrongly adds the two supplier payments.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-222","question":"Assume a minor child's income is clubbed with the income of the parent whose income is higher, with an exemption of ₹1,500 a year per child, and that income from the child's own skill or talent is not clubbed. A minor earns ₹20,000 interest on a fixed deposit gifted by his father and ₹30,000 from his own singing performances. The father's income is higher. How much is clubbed in the father's hands?","options":["₹48,500","₹18,500","₹50,000","₹20,000"],"answer":1,"explanation":"Income from the minor's own talent (₹30,000) is excluded. The interest is clubbed after the ₹1,500 exemption: 20,000 − 1,500 = ₹18,500. ₹48,500 also clubs the performance income; ₹20,000 forgets the exemption.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-223","question":"Under GST, a registered supplier who has charged tax on goods that the buyer later returns issues which document to reduce the tax liability?","options":["A debit note","A bill of supply","A delivery challan","A credit note"],"answer":3,"explanation":"A credit note reduces the value and tax on an earlier invoice, for example on returns or where the taxable value or tax charged was too high. A debit note increases them.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-224","question":"A company transfers goods from its Maharashtra unit to its own branch in Karnataka, separately registered and eligible for full input tax credit. The invoice shows ₹80,000; goods of that kind sell in the open market for ₹1,00,000. What is the taxable value?","options":["₹1,00,000","₹80,000","Nil, as there is no consideration","₹90,000"],"answer":1,"explanation":"Separately registered establishments of the same person are distinct persons, so the transfer is a supply even without consideration. Where the recipient is eligible for full credit, the value declared in the invoice is deemed to be the open market value: ₹80,000. The 90%-of-resale-price option applies only to goods meant for further supply as such, and only at the supplier's option.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-225","question":"Under the Companies Act, 2013, who declares an interim dividend?","options":["The board of directors","The shareholders at the annual general meeting","The auditors","The Registrar of Companies"],"answer":0,"explanation":"Interim dividend is declared by the board between two AGMs. Final dividend is declared by the shareholders at the AGM on the board's recommendation.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-226","question":"Under the Insolvency and Bankruptcy Code, which authority admits an application to start the corporate insolvency resolution process against a company?","options":["The Debts Recovery Tribunal","The Registrar of Companies","The National Company Law Tribunal","The High Court"],"answer":2,"explanation":"The NCLT is the adjudicating authority for companies and LLPs. The Debts Recovery Tribunal handles insolvency of individuals and partnership firms.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-227","question":"A company's board recommends a final dividend of 15%. At the AGM, some shareholders propose raising it to 20%. What can the general meeting do?","options":["Declare 20% by ordinary resolution","Declare 20% by special resolution","Only accept or reject 15%; it cannot change the rate at all","Declare 15% or less, but not more than the board recommended"],"answer":3,"explanation":"Shareholders declare the final dividend, but they cannot declare more than the board recommends. They may approve the recommended rate or a lower one.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-228","question":"How many of these statements about unpaid dividend are correct? (1) A declared dividend must be paid or the warrant posted within 30 days of declaration. (2) Dividend not paid or claimed within that period is transferred to a special Unpaid Dividend Account opened by the company in a scheduled bank. (3) Amounts lying unclaimed in that account for seven years are transferred to the Investor Education and Protection Fund. (4) Once transferred to the IEPF, the shareholder loses all right to claim the amount.","options":["Three","Two","Four","One"],"answer":0,"explanation":"(1), (2) and (3) are correct. (4) is wrong: a shareholder whose dividend (or shares) has gone to the IEPF can still claim a refund from the IEPF Authority by following the prescribed procedure.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-229","question":"A company paid dividends of 12%, 10% and 8% in its three preceding financial years. In the current year it has incurred a loss up to the end of the quarter immediately before the board meets to declare an interim dividend. What is the maximum rate of interim dividend it can declare?","options":["12%","10%","8%","Nil, as no dividend can be declared in a loss year"],"answer":1,"explanation":"Where a company has incurred a loss in the current year up to the quarter before the interim declaration, the interim dividend cannot exceed the average rate of the three preceding years: (12 + 10 + 8) ÷ 3 = 10%.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-230","question":"A company's current-year profit before depreciation is ₹50 lakh and depreciation for the year is ₹10 lakh. It carries forward losses of ₹15 lakh from earlier years. Ignoring transfers to reserves, what is the maximum dividend it can declare out of the current year's profits?","options":["₹40 lakh","₹35 lakh","₹25 lakh","₹50 lakh"],"answer":2,"explanation":"Dividend from current profits can be paid only after providing depreciation and setting off carried-over losses: 50 − 10 − 15 = ₹25 lakh. ₹40 lakh ignores the past losses; ₹35 lakh ignores depreciation.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-231","question":"A company issues equity shares of ₹10 each to the public at ₹9. What is the legal position under the Companies Act, 2013?","options":["The issue is valid if approved by special resolution","The issue is void, as shares cannot be issued at a discount except sweat equity shares (and limited debt-conversion cases)","The issue is valid if the discount is under 10%","The issue is valid but the discount must be written off within five years"],"answer":1,"explanation":"The Act prohibits issuing shares at a discount; such an issue is void and attracts penalties. Sweat equity shares (and shares issued on conversion of debt under a statutory or RBI-approved scheme) are the exceptions.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-232","question":"A company's authorised capital is ₹10 crore and issued capital ₹6 crore. Shares of ₹5 crore face value have been subscribed, with ₹8 per ₹10 share called up. Calls in arrears are ₹20 lakh. What is the paid-up capital?","options":["₹3.8 crore","₹4 crore","₹5 crore","₹4.8 crore"],"answer":0,"explanation":"Called-up capital = 5 crore × 8/10 = ₹4 crore. Paid-up capital is what shareholders have actually paid: 4 crore − 20 lakh = ₹3.8 crore. ₹4 crore is the called-up figure; ₹5 crore is subscribed capital.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-233","question":"Which of these alterations of share capital needs confirmation by the Tribunal? (1) Subdividing shares of ₹10 into shares of ₹1 (2) Reducing share capital by returning surplus capital to shareholders (3) Increasing authorised capital (4) Consolidating shares of ₹1 into shares of ₹10 without changing voting rights","options":["(1) and (2) only","(2) only","(2) and (3) only","All four"],"answer":1,"explanation":"Reduction of share capital needs a special resolution and confirmation by the Tribunal, to protect creditors. Increasing authorised capital, subdivision and consolidation (without change in voting percentages) need only the authority in the articles and an ordinary resolution.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-234","question":"A listed company appoints an audit firm as its statutory auditor. Under the rotation rules, which is correct?","options":["The firm may serve one term of five years and then must leave for ten years","The firm may be reappointed every year without limit","The firm may serve three terms of five years each","The firm may serve at most two terms of five consecutive years, and then cannot be reappointed for five years"],"answer":3,"explanation":"For listed and other prescribed companies, an individual auditor can serve one term of five consecutive years and an audit firm two such terms. After that there is a five-year cooling-off period before reappointment.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-235","question":"Which of these services may a company's statutory auditor provide to it, with the approval of the board or audit committee?","options":["Internal audit","Book-keeping and maintaining accounting records","Preparing and filing the company's tax returns","Investment advisory services"],"answer":2,"explanation":"The Act bars the statutory auditor from providing services such as accounting and book-keeping, internal audit, design of financial information systems, actuarial, investment advisory, investment banking, outsourced financial and management services. Taxation services are not on that list.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-236","question":"The shareholders of a company want to remove its statutory auditor before the end of his five-year term. What is required?","options":["An ordinary resolution at any general meeting","A special resolution, with the prior approval of the Central Government, after giving the auditor a reasonable opportunity of being heard","A board resolution with the audit committee's consent","An application to the Tribunal by members holding 10% of the shares"],"answer":1,"explanation":"Removing an auditor before his term ends needs prior Central Government approval and a special resolution, and the auditor must be given a reasonable opportunity of being heard. (Separately, the Tribunal can order a change of auditor for fraud.)","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-237","question":"Who appoints the first auditor of a newly registered company (other than a government company)?","options":["The shareholders at the first AGM","The Registrar of Companies","The Comptroller and Auditor-General","The board of directors, within 30 days of registration"],"answer":3,"explanation":"The board appoints the first auditor within 30 days of registration. If it fails, the members appoint one at an extraordinary general meeting within 90 days. The first auditor holds office until the end of the first AGM.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-238","question":"A company falls under the CSR provisions. Its net profits (computed as required) for the three immediately preceding years were ₹30 crore, ₹45 crore and ₹15 crore. Assume it must spend 2% of the average net profit of those years. What is its CSR obligation?","options":["₹90 lakh","₹1.8 crore","₹60 lakh","₹30 lakh"],"answer":2,"explanation":"Average net profit = (30 + 45 + 15) ÷ 3 = ₹30 crore; 2% = ₹60 lakh. ₹90 lakh uses only the highest year; ₹1.8 crore uses the total instead of the average; ₹30 lakh uses only the latest year.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-239","question":"A company covered by CSR made net profits of ₹40 crore and ₹30 crore in two of its three immediately preceding years and a loss of ₹10 crore in the other. Assume the obligation is 2% of the average net profit of the three years. What is the obligation?","options":["₹46.67 lakh","₹70 lakh","₹1.2 crore","₹40 lakh"],"answer":3,"explanation":"The loss year is included in the average: (40 + 30 − 10) ÷ 3 = ₹20 crore; 2% = ₹40 lakh. Ignoring the loss but dividing by three gives ₹46.67 lakh; averaging only the two profit years gives ₹70 lakh.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-240","question":"How many of these statements about unspent CSR amounts are correct? (1) An unspent amount that does not relate to an ongoing project must be transferred to a fund specified in Schedule VII within six months of the end of the financial year. (2) An unspent amount relating to an ongoing project must be moved to a special Unspent CSR Account within 30 days of the end of the year. (3) Money in the Unspent CSR Account must be spent within three financial years, failing which it goes to a Schedule VII fund. (4) A company may simply explain the shortfall in the board's report and carry it forward indefinitely.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (2) and (3) describe the current scheme. (4) is wrong: since the amendments, a shortfall cannot just be explained away; it must be transferred as described, with penalties for default.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-241","question":"Which of these would NOT count as CSR expenditure?","options":["Building toilets in government schools in a backward district","Contribution to a fund specified in Schedule VII","A medical scheme that benefits only the company's own employees and their families","Funding a skill-training programme for unemployed youth"],"answer":2,"explanation":"Activities that benefit only the company's employees and their families are excluded from CSR. Schools' sanitation, skill training and contributions to specified funds are recognised CSR activities.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-242","question":"In a liquidation under the IBC, arrange these claims in the order of payment from highest priority: (a) workmen's dues for the 24 months before liquidation, ranking equally with secured creditors who have relinquished their security; (b) insolvency resolution process and liquidation costs; (c) unsecured financial creditors; (d) equity shareholders; (e) wages and unpaid dues of employees other than workmen for 12 months.","options":["a, b, e, c, d","b, e, a, c, d","b, a, c, e, d","b, a, e, c, d"],"answer":3,"explanation":"The waterfall starts with process and liquidation costs, then workmen's dues (24 months) equally with secured creditors who relinquished security, then other employees' dues (12 months), then unsecured financial creditors; equity shareholders come last.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-243","question":"In a corporate insolvency, the committee of creditors has these voting shares: Bank A 40%, Bank B 25%, NBFC C 20%, Bank D 15%. Assume a resolution plan needs the approval of at least 66% of the voting share. Which group of assenting creditors is enough to approve it?","options":["A, B and D","A and B","B, C and D","A and C"],"answer":0,"explanation":"A + B + D = 80%, which clears 66%. A + B = 65% falls just short; B + C + D = 60% and A + C = 60% also fail.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-244","question":"Under the IBC, an operational creditor (such as a supplier) wants to start insolvency proceedings against a company that owes it money. What must it do first?","options":["Deliver a demand notice to the company and wait for the prescribed period for payment or notice of a dispute","File the application directly before the NCLT without any notice","Obtain the consent of all financial creditors","Get a decree from a civil court"],"answer":0,"explanation":"An operational creditor must first deliver a demand notice (with a copy of the invoice). Only if the debtor neither pays nor points out a pre-existing dispute within the prescribed period can it apply to the NCLT. A financial creditor can apply directly.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-245","question":"Once the NCLT admits a corporate insolvency application and declares a moratorium, how many of these follow? (1) No suit or proceeding can be started or continued against the corporate debtor. (2) A secured creditor cannot enforce its security against the debtor's assets. (3) The supply of essential goods and services to the debtor cannot be terminated during the moratorium. (4) Creditors are barred from proceeding against a personal guarantor of the debtor.","options":["Two","Three","Four","One"],"answer":1,"explanation":"(1), (2) and (3) follow from the moratorium. (4) does not: the moratorium protects the corporate debtor, and creditors can still proceed against a personal guarantor, as the Supreme Court has confirmed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-246","question":"Which statements comparing an LLP with a company are correct? (1) An LLP has no upper limit on the number of partners. (2) A private company needs at least two members (unless it is a one person company). (3) An LLP partner's liability is limited to his agreed contribution, except in case of fraud. (4) An LLP must be managed by a board of directors.","options":["(1), (2) and (3) only","(1) and (3) only","(2), (3) and (4) only","All four"],"answer":0,"explanation":"(1), (2) and (3) are correct. (4) is wrong: an LLP is managed by its partners under the LLP agreement, with designated partners responsible for compliance; it has no board of directors.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-247","question":"How many of these statements about a casual vacancy in the office of auditor of a non-government company are correct? (1) A vacancy for a reason other than resignation is filled by the board within 30 days. (2) If the vacancy arises from the auditor's resignation, the board's appointment must also be approved by the company at a general meeting within three months. (3) An auditor appointed in a casual vacancy holds office until the end of the next AGM. (4) A resigning auditor need not inform anyone other than the board.","options":["Two","Three","Four","One"],"answer":1,"explanation":"(1), (2) and (3) are correct. (4) is wrong: a resigning auditor must file a statement with the company and the Registrar giving the reasons for resignation.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-248","question":"X, a partner in an LLP, negligently gives wrong advice to a client, and the LLP is held liable for ₹50 lakh. The LLP's assets are only ₹30 lakh. Partner Y had nothing to do with the advice. Who is liable for the loss?","options":["X and Y jointly and severally, like partners in an ordinary firm","The LLP from its own assets, and X personally for his own wrongful act; Y is not personally liable","Only the LLP, up to ₹30 lakh; the rest is lost and no partner is liable","Y and X equally, in proportion to their contributions"],"answer":1,"explanation":"The LLP is liable for a partner's wrongful act in the course of its business. A partner is not personally liable for another partner's wrongful acts, but remains personally liable for his own. So X bears the shortfall personally and Y does not.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-249","question":"A cheque given to pay a debt is dishonoured because there is not enough money in the drawer's account. Once the statutory conditions are met, what can the payee pursue?","options":["Both a criminal complaint for dishonour and a civil suit to recover the money","Only a civil suit for recovery","Only a complaint to the bank's ombudsman","Nothing, as dishonour is a matter between the drawer and his bank"],"answer":0,"explanation":"Dishonour of a cheque issued for a legally enforceable debt is a criminal offence once notice is given and payment is not made in time. The payee can also file a civil suit for the money; the two remedies run independently.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-250","question":"In contract law, the remedy 'quantum meruit' means:","options":["Specific performance of the whole contract","A fixed penalty agreed in the contract","Payment of a reasonable sum for work actually done","Cancellation of the contract with no payment"],"answer":2,"explanation":"Quantum meruit ('as much as earned') lets a party recover a reasonable amount for what he has actually done, for example when the other party prevents him from completing the work.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-251","question":"After issuing a cheque for an existing debt, the drawer tells his bank to stop payment, and the cheque is returned 'payment stopped by drawer' although the account had enough money. In a prosecution for dishonour, which is correct?","options":["Stopping payment is always a complete defence, as the account had funds","The stop-payment instruction is no defence by itself; the offence can be made out if the other conditions are met","Only dishonour for 'insufficient funds' is covered, so no offence arises","The bank is liable for not honouring the cheque"],"answer":1,"explanation":"Courts have held that a drawer cannot escape liability merely by stopping payment. If the cheque was for a legally enforceable debt and the drawer fails to pay after the statutory notice, the offence is made out; he may still rebut the presumption by showing there was no debt.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-252","question":"A borrower gives the lender a cheque as 'security' when taking a loan. He defaults when the loan falls due, and the lender presents the cheque, which is dishonoured. Can the dishonour provisions apply?","options":["Yes, if a legally enforceable debt existed on the date the cheque was presented","No, a security cheque can never attract liability for dishonour","Only if the cheque was post-dated by less than one month","Only if the borrower had signed a separate promissory note"],"answer":0,"explanation":"The Supreme Court has held that a cheque given as security is not excluded. If the loan had become due and payable when the cheque was presented, the cheque represents an enforceable debt and its dishonour can attract liability.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-253","question":"How many of these statements about a prosecution for cheque dishonour are correct? (1) The court presumes that the holder received the cheque for the discharge of a debt or liability. (2) The accused can rebut the presumption on a preponderance of probabilities. (3) The complainant must first prove the debt beyond reasonable doubt before any presumption arises. (4) The cheque must have been issued for a legally enforceable debt or other liability.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (2) and (4) are correct. (3) is wrong: once the cheque and signature are admitted, the presumption arises in favour of the holder, and the burden shifts to the accused, who need only raise a probable defence.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-254","question":"A company's cheque is dishonoured. How many of these statements about who can be prosecuted are correct? (1) Persons in charge of and responsible for the conduct of the company's business when the offence was committed can be liable. (2) Every director, including an independent non-executive director, is automatically liable. (3) The company itself should be made an accused for its officers to be prosecuted. (4) A director who proves the offence was committed without his knowledge, or that he exercised due diligence, is not liable.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (3) and (4) reflect the law. (2) is wrong: liability is not automatic; the complaint must show the director was in charge of and responsible for the business, and non-executive directors are generally not liable merely because they hold office.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-255","question":"Assume a cheque is valid for three months from its date. A cheque dated 1 January is presented on 15 April and dishonoured for insufficient funds. Which is correct?","options":["No criminal liability for dishonour arises, but the payee can still sue on the underlying debt","The drawer is criminally liable, as the funds were insufficient","The payee can present it again within one more month to revive liability","The bank must pay the cheque from its own funds"],"answer":0,"explanation":"The criminal provision applies only if the cheque is presented within its validity period. A cheque presented after it has gone stale does not attract it, though the debt itself can still be recovered through a civil suit.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-256","question":"A draws an order cheque in favour of B. B endorses it to C for value. The cheque is dishonoured, and C gives notice of dishonour only to A. None of the exceptions that excuse notice applies. On the instrument, whom can C hold liable?","options":["Only A, as B is discharged for want of notice","Both A and B, jointly and severally","Only B, as the immediate endorser","Neither, as the notice was incomplete"],"answer":0,"explanation":"A holder must give notice of dishonour to every party he wants to hold liable. Notice to the drawer does not keep the endorser liable, so B is discharged on the instrument and C can proceed only against A.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-257","question":"A seller agrees to export goods to a foreign buyer and receives an advance of ₹2 lakh. Before shipment, the government bans export of those goods, and the ban was not foreseeable. What is the position?","options":["The contract becomes void and the seller must return the ₹2 lakh advance","The seller may keep the advance as compensation","The buyer can claim damages for non-delivery","The contract is only suspended until the ban is lifted, and the advance stays with the seller"],"answer":0,"explanation":"A later law that makes performance unlawful frustrates the contract, making it void. A person who received an advantage under a contract that becomes void must restore it, so the seller refunds the advance; neither side owes damages.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-258","question":"A agrees to sell his car to B. A knows the car was destroyed in a fire the day before, but B does not know and could not have known. What is B's remedy?","options":["B can compel A to deliver another car of the same model","No remedy, as the agreement is void for impossibility","B can only report A to the police","The agreement is void, but A must compensate B for any loss caused by the non-performance"],"answer":3,"explanation":"An agreement to do something impossible is void. But where the promisor knew of the impossibility and the promisee did not, the promisor must compensate the promisee for the loss caused.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-259","question":"A buyer contracts to buy 500 units at ₹200 each and pays a 20% advance. The seller fails to deliver. On the delivery date the market price is ₹230; the buyer delays and buys a week later at ₹250. How much can the buyer recover from the seller in total?","options":["₹45,000","₹15,000","₹20,000","₹35,000"],"answer":3,"explanation":"Damages for non-delivery are the difference between the contract price and the market price on the date of breach: 500 × (230 − 200) = ₹15,000; the extra cost from delaying the purchase is the buyer's own loss. He also recovers his advance of 20% × 1,00,000 = ₹20,000. Total ₹35,000. Using ₹250 gives ₹45,000; forgetting the advance gives ₹15,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-260","question":"A owes B three debts: ₹10,000 due in January (now time-barred), ₹20,000 due in March and ₹15,000 due in May. A pays ₹15,000 without saying which debt it is for, and B does not appropriate it either. Under the Indian Contract Act, how is the payment applied?","options":["₹10,000 to the January debt and ₹5,000 to the March debt","₹15,000 to the May debt","₹15,000 to the March debt, as a time-barred debt cannot be paid","Proportionately across the three debts"],"answer":0,"explanation":"When neither party appropriates, the payment is applied to the debts in order of time, whether or not they are barred by limitation. So the January debt is cleared first and the balance goes towards the March debt.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-261","question":"In a contract where time is of the essence, the supplier delivers a week late and the buyer accepts the goods without saying anything. Later the buyer claims compensation for the delay. Which is correct?","options":["He can claim, as time was of the essence","He cannot claim, because he did not give notice of his intention to claim compensation when he accepted late performance","He can reject the goods now and recover the price","He can claim only if the contract had a penalty clause"],"answer":1,"explanation":"When time is essential, the promisee may avoid the contract on delay. If he instead accepts late performance, he cannot claim compensation for the delay unless he gives notice of that intention to the promisor at the time of acceptance.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-262","question":"A seller brings the agreed goods to the agreed place at the agreed time, but the buyer refuses to take delivery. What is the effect of this tender of performance?","options":["The seller must keep tendering the goods every day until accepted","The contract is automatically discharged with no remedy for either side","The seller is not responsible for non-performance and keeps his rights against the buyer","The seller must sell the goods at once and remit the proceeds to the buyer"],"answer":2,"explanation":"A proper offer to perform that is refused discharges the promisor from liability for non-performance, and he does not lose his rights under the contract, so he can claim damages from the buyer.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-263","question":"An indemnity-holder (promisee) is sued by a third party in a matter covered by the indemnity. Acting prudently and within his authority, he settles the case. Which can he recover from the indemnifier? (1) Damages he was compelled to pay (2) Costs of defending the suit (3) The sum paid under the compromise (4) Compensation for the time he personally spent, beyond legal costs","options":["(1) and (2) only","(1) only","(1), (2) and (3) only","All four"],"answer":2,"explanation":"An indemnity-holder acting within the terms of the promise, prudently, can recover damages he was compelled to pay, costs he was compelled to pay in the suit, and sums paid under a reasonable compromise. There is no such statutory right to a fee for his own time.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-264","question":"A recipient takes input tax credit of ₹18,000 but has not paid the supplier when 180 days from the invoice have passed. It pays the supplier in full two months later. Which is correct?","options":["It loses the credit permanently","It must reverse the credit (with interest) after 180 days, and can take it again when it pays","Nothing happens, as the supplier has already paid the tax","The supplier must reverse its output tax"],"answer":1,"explanation":"Credit must be reversed, with interest, if value and tax are not paid within 180 days of the invoice. On later payment the recipient is entitled to take the credit again.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-265","question":"A father bought land for ₹10 lakh years ago and died; his son inherited it and has now sold it for ₹60 lakh, paying ₹1 lakh of brokerage. Its fair market value when the son inherited it was ₹30 lakh. Assume the gain is long-term and taxed at 12.5% without indexation. What is the tax (ignoring cess and surcharge)?","options":["₹3.625 lakh","₹7.5 lakh","₹6.125 lakh","₹6.25 lakh"],"answer":2,"explanation":"For an inherited asset, the cost is the previous owner's cost (₹10 lakh), and his holding period counts too. Gain = 60 − 1 − 10 = ₹49 lakh; tax = 12.5% × 49 = ₹6.125 lakh. Using the value on inheritance gives ₹3.625 lakh; ignoring the brokerage gives ₹6.25 lakh.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-266","question":"An investor bought 1,000 shares at ₹300 each and later received 1,000 bonus shares (1 : 1). She now sells the 1,000 bonus shares at ₹500 each, ignoring expenses. Assume bonus shares have a cost of nil. What is the capital gain?","options":["₹3,50,000","₹5,00,000","₹2,00,000","₹3,00,000"],"answer":1,"explanation":"The bonus shares cost nothing, so the whole sale price of 1,000 × 500 = ₹5,00,000 is the gain; the original 1,000 shares keep their ₹300 cost. ₹3,50,000 wrongly averages the cost to ₹150 a share; ₹2,00,000 uses the original ₹300 cost.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-267","question":"A company's shareholders must approve a material related-party transaction by resolution. Who may NOT vote on that resolution?","options":["All the directors who hold shares","Members who are related parties to that particular transaction","All members holding less than 1% of the shares","The company's auditors"],"answer":1,"explanation":"To prevent interested parties from approving their own deals, members who are related parties in the context of the transaction cannot vote on its approval. Other shareholders vote as usual.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-268","question":"How many of these statements about issuing further shares are correct? (1) A rights issue is offered to existing equity shareholders in proportion to their holdings. (2) Unless the articles provide otherwise, the offer includes a right to renounce the shares in favour of another person. (3) A preferential issue to selected persons needs a special resolution. (4) Shares under an employee stock option scheme can be issued with only an ordinary resolution.","options":["Two","Four","Three","One"],"answer":2,"explanation":"(1), (2) and (3) are correct. (4) is wrong: issuing shares to employees under a stock option scheme requires a special resolution.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-269","question":"Under the IBC, which of these cannot, merely in that capacity, apply to start a corporate insolvency resolution process against a company?","options":["A financial creditor","An operational creditor","An equity shareholder of the company","The corporate debtor itself"],"answer":2,"explanation":"The Code allows a financial creditor, an operational creditor or the corporate debtor itself to apply. A shareholder is not a creditor and has no such right as a shareholder.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-270","question":"How many of these statements about who may submit a resolution plan under the IBC are correct? (1) A person whose loan account has been classified as a non-performing asset for the specified period is ineligible unless he clears the overdue amounts before submitting the plan. (2) An undischarged insolvent is ineligible. (3) A wilful defaulter may submit a plan if the committee of creditors agrees. (4) The resolution professional finally approves the plan.","options":["One","Three","Two","Four"],"answer":2,"explanation":"(1) and (2) are correct ineligibility rules. (3) is wrong: a wilful defaulter is ineligible regardless of what the committee wants. (4) is wrong: the committee of creditors approves the plan and the NCLT then approves it; the resolution professional only examines it and presents it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-271","question":"A agrees to sell B 'a hundred tonnes of oil' at a stated price. Nothing in the agreement or the circumstances shows what kind of oil was meant. What is the status of the agreement?","options":["Valid, and B can choose any oil","Valid, and A can deliver any oil","Voidable at B's option","Void for uncertainty"],"answer":3,"explanation":"An agreement whose meaning is not certain, and cannot be made certain, is void. Had A been known to deal only in one kind of oil, the meaning could be made certain and the agreement would be valid.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-272","question":"An order cheque payable to A is stolen. The thief forges A's endorsement and negotiates it to C, who takes it in good faith and for value. What is C's position?","options":["C is a holder in due course and can enforce the cheque against the drawer","C can enforce it, but only after giving notice to A","C gets no title, as no title passes through a forged endorsement, and A remains the true owner","C and A share the right to the cheque equally"],"answer":2,"explanation":"A forged endorsement is a nullity, so nobody claiming through it, even in good faith and for value, gets title to an order instrument. A remains the owner and can recover it or its value. (A bearer cheque, which needs no endorsement, is treated differently.)","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-273","question":"A posts an offer to B on 1 March, which B receives on 4 March. On 5 March A posts a letter revoking the offer; it reaches B on 7 March. B posted his acceptance on 6 March, and it reaches A on 8 March. What is the legal position?","options":["A binding contract arose on 6 March; the revocation is too late","The revocation is effective because A posted it before B posted the acceptance","No contract arises because A learnt of the acceptance only after posting the revocation","A contract arose only on 8 March, when the acceptance reached A"],"answer":0,"explanation":"An offer can be revoked only before acceptance is complete against the proposer, which happens when the acceptance is posted (6 March). A revocation is complete only when it reaches the offeree (7 March), so it came too late; the date of posting a revocation does not count.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-274","question":"A makes a written offer to sell his warehouse to B. A dies the next day. B, who has no knowledge of the death, posts an unconditional acceptance within the time allowed. Under the Indian Contract Act, what is the position?","options":["The offer lapsed automatically on A's death, whether or not B knew","The contract binds B but not A's legal representatives","The acceptance is valid, because death revokes an offer only if the acceptor learns of it before accepting","A contract arises only if A's legal heirs ratify B's acceptance"],"answer":2,"explanation":"Section 6(4) revokes a proposal on the proposer's death or insanity only if that fact comes to the acceptor's knowledge before acceptance. B accepted in ignorance, so a contract arises and binds A's estate (a sale of property is not a personal contract).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-275","question":"A's offer says 'reply by e-mail only'. B accepts by a registered letter, which reaches A. A keeps quiet for several weeks and then claims there was no contract because the prescribed mode was not used. Is he right?","options":["Yes; an acceptance in any other mode is a counter-offer that needs fresh acceptance","No; a proposer who does not insist on the prescribed mode within a reasonable time after receiving the acceptance is taken to have accepted it","Yes; deviating from the prescribed mode makes the acceptance void","No; the mode of acceptance is never relevant under Indian law"],"answer":1,"explanation":"Section 7(2) lets the proposer, within a reasonable time after the acceptance is communicated, insist that it be made in the prescribed manner. If he fails to do so, he accepts the acceptance. A's long silence waived the condition.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-276","question":"At the Collector's request, A spent his own money building a market. Later, traders who rented shops there promised A a commission on goods sold. When they did not pay, A sued. What is the result?","options":["A succeeds, because past consideration is valid in India","A succeeds, because consideration may move from any person","A fails, because the agreement is not in writing and registered","A fails, because his act was not done at the desire of the traders, so there is no consideration for their promise"],"answer":3,"explanation":"Under Section 2(d) the act must be done at the desire of the promisor. Building at the Collector's request is not consideration for the traders' promise (Durga Prasad v Baldeo). Past consideration is valid only if the past act was done at the promisor's desire.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-277","question":"A trader sells 12 shirts on credit to B, a 17-year-old college student from a wealthy family, at prices suited to B's station. B's parents had already supplied him with an ample wardrobe. Can the trader recover the price from B's property?","options":["Yes, because clothes are always necessaries","Yes, but only from B's parents, who are personally liable","No, but B must return the shirts because a minor is always liable to restore benefits","No; goods are 'necessaries' only if the minor actually needs them at the time, and B was already well supplied"],"answer":3,"explanation":"Section 68 allows reimbursement from a minor's property only for necessaries – goods suited to his condition in life and his actual requirements at the time. A minor already adequately supplied does not need more (Nash v Inman). Parents are not liable merely by relationship.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-278","question":"In which of these cases does a seller's silence amount to fraud?","options":["A sells B a horse he knows to be unsound; B is A's daughter who has just come of age and relies on him","A sells B a horse he knows to be unsound; B is a stranger and asks nothing","A sells B a used car 'as it is' after B inspects it at leisure","A sells B shares without mentioning that he expects the price to fall"],"answer":0,"explanation":"Mere silence is not fraud unless there is a duty to speak or the silence is itself equivalent to speech (Section 17, Explanation). A fiduciary-type relationship, such as a father dealing with a daughter who relies on him, creates that duty; a stranger owes none.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-279","question":"B buys a factory after A says it earns ₹20 lakh a year. The figure is false, but A believed it, and the audited books, which B was invited to inspect and could easily have checked, show the true profit of ₹12 lakh. B did not look at them. Can B avoid the contract?","options":["Yes; any misrepresentation makes a contract voidable","No; for innocent misrepresentation, the contract is not voidable if the truth could have been discovered with ordinary diligence","Yes; the statement is fraud because it turned out to be false","No; the contract is void because of a mutual mistake of fact"],"answer":1,"explanation":"The Exception to Section 19 says a contract caused by misrepresentation (or fraud by silence) is not voidable if the party had the means of discovering the truth with ordinary diligence. A honestly believed the figure, so it is misrepresentation, not fraud, and B ignored an easy check.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-280","question":"B agrees to pay A a monthly salary of ₹50,000. In return A will manage B's lawful textile business and also run an illegal betting operation for B. B later refuses to pay. Can A enforce the salary for the lawful work?","options":["Yes, for the lawful part only, because the two parts are severable","Yes, because A has actually done the lawful work","No; where a single consideration is given for lawful and unlawful objects together, the whole agreement is void","No, but only because betting agreements are wagering agreements"],"answer":2,"explanation":"Section 24 makes the whole agreement void if any part of a single consideration for one or more objects is unlawful. The salary is one consideration for both objects, so nothing can be enforced, unlike reciprocal promises where the legal set can be separated.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-281","question":"A software firm's employment contract has two clauses: (1) while employed, the employee shall not work for any other firm; (2) for two years after leaving, he shall not join any competitor anywhere in India. How are they treated in India?","options":["Both clauses are valid because the employee agreed to them","Both clauses are void as restraints of trade","Clause (1) is valid; clause (2) is void as a restraint of trade","Clause (1) is void; clause (2) is valid if it is reasonable"],"answer":2,"explanation":"A negative covenant operating during employment is valid (Niranjan Shankar Golikari). A post-employment restraint falls under Section 27 and is void however reasonable, because the only statutory exception concerns the sale of goodwill (Superintendence Co. v Krishan Murgai).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-282","question":"A agrees to pay B ₹2 lakh if B marries C. C then marries D. What is the status of the agreement?","options":["It remains contingent, because C could divorce D and marry B","It is enforceable at once, because the event can no longer happen","It was void from the start as a restraint of marriage","It becomes void, because B marrying C is now treated as impossible, even though C might later be free to marry"],"answer":3,"explanation":"Section 34: where the event is the way a living person will act at an unspecified time, it is treated as impossible when that person does anything that makes it impossible within a definite time. C's marriage to D does so, though a later divorce is conceivable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-283","question":"A, B and C jointly promise to pay D ₹3,00,000. D recovers the whole amount from C. A is insolvent, and his estate can pay only half of his share. How much can C recover from B?","options":["₹1,00,000","₹1,25,000","₹1,50,000","₹1,75,000"],"answer":1,"explanation":"Each share is ₹1,00,000. A's estate pays ₹50,000, leaving ₹50,000 of A's share unpaid; under Section 43 that default is borne equally by B and C. So B owes his own ₹1,00,000 plus ₹25,000 = ₹1,25,000.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-284","question":"A fails to deliver a machine under contract. B could have hired a similar machine at once for ₹10,000 but, out of irritation, kept his plant idle for a month and lost profits of ₹2,00,000 that he could have avoided. What damages can B recover?","options":["Only the loss he could not have avoided by reasonable steps, such as the hire charge, not the avoidable lost profits","The full ₹2,00,000, because A's breach caused the plant to stand idle","Nothing, because B refused to mitigate his loss","Only nominal damages, because the breach was not wilful"],"answer":0,"explanation":"The Explanation to Section 73 requires the means of remedying the inconvenience to be taken into account. B can recover losses that reasonable mitigation would not have prevented; profits lost only because he failed to act reasonably are not recoverable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-285","question":"A training firm registered only in Maharashtra conducts a two-day workshop in Goa for the employees of a company registered in Karnataka. What is the place of supply, and which tax applies?","options":["Place of supply is Goa; IGST","Place of supply is Maharashtra; CGST + SGST","Place of supply is Karnataka; IGST","Place of supply is Goa; CGST + SGST of Goa"],"answer":2,"explanation":"For training services supplied to a registered person, the place of supply is the recipient's location (Karnataka); the place of performance matters only for unregistered recipients. The supplier is in Maharashtra, so the supply is inter-state and IGST applies.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-286","question":"An employee of a company registered only in Delhi stays on business at a hotel registered in Rajasthan, and the bill is raised on the company's Delhi GSTIN. Which statement is correct?","options":["The hotel charges IGST, and the Delhi registration takes full input tax credit","The hotel charges CGST + SGST of Rajasthan, and the Delhi registration cannot use that tax as input tax credit","The hotel charges CGST + SGST of Delhi, because the recipient is registered in Delhi","No GST applies, because accommodation is used outside the recipient's state"],"answer":1,"explanation":"Services directly related to immovable property, including hotel accommodation, take the property's location as the place of supply. The supply is intra-state in Rajasthan, and Rajasthan CGST + SGST cannot be credited to a Delhi registration.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-287","question":"For a year a business with one PAN has: intra-state taxable supplies ₹30 lakh; exempt supplies ₹5 lakh; exports ₹8 lakh; transfers to its own branch registered in another state ₹4 lakh; inward supplies on which it paid tax under reverse charge ₹3 lakh; GST charged on its outward supplies ₹5.4 lakh. What is its aggregate turnover?","options":["₹52.4 lakh","₹50 lakh","₹43 lakh","₹47 lakh"],"answer":3,"explanation":"Aggregate turnover includes taxable, exempt and export supplies and inter-state supplies between distinct persons with the same PAN, but excludes GST and inward supplies taxed under reverse charge: 30 + 5 + 8 + 4 = 47. Adding the tax gives 52.4; adding reverse-charge purchases gives 50.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-288","question":"Which of these is a supply under GST even though no consideration is charged?\nI. A Delhi factory sends goods to the company's own depot in Haryana, which holds a separate GST registration.\nII. A factory moves goods to a second warehouse in the same state covered by the same registration.\nIII. A company permanently gives away an office laptop, on which it had taken input tax credit, to a charity.","options":["I and III only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Schedule I treats supplies between distinct persons (separate registrations of the same PAN) and the permanent disposal of business assets on which credit was taken as supplies even without consideration. A movement within one registration is not a supply to another person.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-289","question":"A company distributes branded gift hampers, bought for the purpose, to its dealers at Diwali free of charge. What is the GST position of the tax paid on the hampers?","options":["Input tax credit is allowed because the gifts promote the business","Input tax credit is allowed, but the company must pay output tax on the gifts","Input tax credit is allowed only if each gift is below a stated value","Input tax credit is blocked because the goods are disposed of by way of gift"],"answer":3,"explanation":"Section 17(5) blocks credit on goods disposed of by way of gift or free samples. Business promotion does not unblock it. Since no credit is taken, there is also no deemed supply of business assets on which credit was taken.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-290","question":"Match each receipt with the head of income under which it is taxed.\n1. Rent received by a tenant from sub-letting part of his flat\n2. Salary and interest received by a partner from his firm\n3. Salary received by a Member of Parliament\n4. Rent received by the owner of a building let to a tenant who runs a shop in it\na. Income from house property  b. Profits and gains of business or profession  c. Income from other sources","options":["1-c, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-b","1-c, 2-c, 3-a, 4-a","1-a, 2-a, 3-b, 4-a"],"answer":0,"explanation":"House property income is taxed only in the owner's hands, so sub-letting income is 'other sources'. A partner's salary and interest are business income, not salary. An MP is not an employee, so the salary is 'other sources'. The tenant's use of the building does not change the owner's head.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-291","question":"In which case is the guarantee unenforceable for want of consideration?","options":["A agrees to sell goods to B on credit only because C promises to pay if B defaults","A has sued B for a debt; at C's request A agrees not to sue for a year, and C guarantees payment","A lends money to B, and C guarantees repayment in exchange for a fee from B","A sold goods to B on credit last month; today C, receiving nothing, promises A that he will pay if B defaults"],"answer":3,"explanation":"Under Section 127, anything done or promised for the benefit of the principal debtor is enough consideration for the surety. Forbearance to sue and a fresh supply are such benefits; a guarantee of a past, already-completed sale with nothing new given is void.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-292","question":"A gives a bank a continuing guarantee for loans to B up to ₹10 lakh. B borrows ₹4 lakh. A then dies; the bank, not knowing this, lends B a further ₹3 lakh. B defaults on both. For how much is A's estate liable, absent any contrary term?","options":["₹7 lakh","₹10 lakh","₹4 lakh","Nothing"],"answer":2,"explanation":"Under Section 131, the surety's death revokes a continuing guarantee for future transactions, unless the contract says otherwise. The estate stays liable for the ₹4 lakh lent before death but not for later advances.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-293","question":"C lends B ₹5 lakh with A as surety. When the loan falls due, (P) C makes a binding agreement with B to give him six months more, without A's consent; or (Q) C makes a binding agreement with X, a stranger, to give B six months more, without A's consent. In which case is A discharged?","options":["In Q only","In P only","In both P and Q","In neither P nor Q"],"answer":1,"explanation":"Section 135 discharges the surety when the creditor contracts with the principal debtor to give him time. Section 136 says an agreement to give time made with a third person, not with the principal debtor, does not discharge the surety.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-294","question":"A employs C to collect rents. C misappropriates some rent. Without telling B, A asks B to guarantee C's honesty in future; B does so. C later misappropriates again. Is B liable?","options":["No; the guarantee is invalid because it was obtained by concealing a material fact","Yes; a surety must make his own enquiries before signing","Yes; the earlier fraud is irrelevant to future conduct","No; guarantees of an employee's honesty are void as being against public policy"],"answer":0,"explanation":"Section 143 makes a guarantee invalid if the creditor obtains it by keeping silence about a material circumstance. C's earlier dishonesty was plainly material to the risk B was taking on.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-295","question":"A guarantees a loan to B on the understanding with the creditor C that C will not act on it until D also signs as a co-surety. D never signs. Can C enforce A's guarantee?","options":["Yes; A's liability is independent of D","Yes, but only for half the loan","No, but only if A informs C before B defaults","No; the guarantee is not valid if the agreed co-surety does not join"],"answer":3,"explanation":"Section 144: where a guarantee is given on a contract that the creditor shall not act on it until another person joins as co-surety, the guarantee is not valid if that person does not join.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-296","question":"A rents out a car to B for a week. The car has a brake defect that A did not know of and could not easily have discovered. The brakes fail and B is injured. Is A liable?","options":["Yes; in a bailment for hire, the bailor is responsible for faults even if he was not aware of them","No; a bailor is liable only for faults he knew of","No; the bailee must examine the goods before use","Yes, but only if A was negligent in maintaining the car"],"answer":0,"explanation":"Section 150: a gratuitous bailor must disclose faults he knows of, but if the goods are bailed for hire, the bailor is responsible for damage arising from such faults whether or not he was aware of them.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-297","question":"B hires a car from A for his family's personal use only. B starts using it as a taxi for paying passengers. What right does A have?","options":["None until the agreed hire period ends","Only a claim for extra hire charges","A may terminate the bailment, because B has done an act inconsistent with its conditions","A may treat the car as sold to B"],"answer":2,"explanation":"Section 153 makes a bailment voidable at the bailor's option if the bailee does any act with the goods inconsistent with the conditions of the bailment. Commercial use breaches the agreed purpose.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-298","question":"A bails 100 bags of his rice with B, a warehouse keeper. Without A's consent, B mixes them with his own identical rice so that they cannot be separated. What is the position?","options":["A and B become joint owners in proportion to their shares","B must compensate A for the loss of the rice","A must bear the cost of separating the rice","A loses his rice because it is no longer identifiable"],"answer":1,"explanation":"Section 157: if the bailee mixes the goods without consent with his own so that they cannot be separated, the bailor is entitled to compensation. Proportional joint ownership (Section 155) arises only when the mixing is with consent.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-299","question":"A pledges gold with a bank for a loan of ₹2 lakh. Later the bank lends him a further ₹50,000 without any security being mentioned. A tenders ₹2 lakh with interest and demands the gold. What is the position?","options":["The bank must return the gold, because a pledge secures only the debt for which it was made","The bank may retain the gold only if A has signed a fresh pledge deed","The bank may sell the gold at once to recover the later advance","The bank may retain the gold for the later advance too, because a contract to that effect is presumed for subsequent advances"],"answer":3,"explanation":"Section 174 says the pawnee cannot, without a contract, retain the goods for any debt other than the one for which they were pledged, but such a contract is presumed, unless the contrary appears, for subsequent advances made by the pawnee.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-300","question":"X obtains jewellery from its owner by fraud, under a contract voidable at the owner's option. Before the owner rescinds the contract, X pledges the jewellery with Y, who acts in good faith and without notice of the fraud. What is Y's position?","options":["Y gets a good title as pawnee","Y must return the jewellery to the owner without any claim","Y gets a good title only if the owner fails to sue within a year","The pledge is void because X had no title"],"answer":0,"explanation":"Section 178A: a person in possession under a voidable contract can make a valid pledge before the contract is rescinded, if the pawnee acts in good faith without notice of the defect in the pledgor's title.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-301","question":"A, without B's authority, demands on B's behalf that C deliver goods belonging to B. C refuses. B now ratifies A's demand and sues C for damages for refusing a demand made by B's agent. Will B succeed?","options":["Yes; ratification relates back to the time of A's demand","No; ratification cannot subject a third person to damages or terminate his rights","Yes; C should have checked A's authority before refusing","No; an act can be ratified only by a principal of full age who knew of it in advance"],"answer":1,"explanation":"Ratification normally relates back, but Section 200 bars it where it would subject a third person to damages or end his right or interest. C cannot be made liable for refusing an unauthorised demand.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-302","question":"A principal revokes his agent's authority on 1 May but does not inform anyone else. On 5 May, the agent, still holding himself out as agent, buys goods from a regular supplier who knows nothing of the revocation. Is the principal bound?","options":["No; the authority ended on 1 May for all purposes","No; the agent alone is liable because he knew of the revocation","Yes; termination of authority does not take effect against third persons before it becomes known to them","Yes, but only if the principal later ratifies the purchase"],"answer":2,"explanation":"Section 208: termination of an agent's authority takes effect for third persons only when it becomes known to them. The principal is bound to the supplier, though he may claim against the agent for acting after revocation.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-303","question":"B, falsely claiming to be A's agent, contracts with C to sell A's land. A refuses to ratify. What is C's remedy?","options":["C can compel A to complete the sale","C can enforce the sale against B as if B owned the land","C has no remedy because the contract was void","C can claim compensation from B for any loss caused by B's false claim of authority"],"answer":3,"explanation":"Section 235 makes a person who untruly represents himself as an agent liable to the third party for any loss caused, if the alleged principal does not ratify. The principal is not bound by an unauthorised act he never ratified.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-304","question":"A clerk of a solicitors' firm, acting within his ostensible duties, induces a client to transfer her property to him and then sells it for his own benefit. Is the firm liable to the client?","options":["No; the firm gained nothing from the fraud","Yes; a principal is liable for an agent's fraud committed in the course of his employment, even if it benefits only the agent","No; an agent's fraud always binds the agent alone","Yes, but only if the firm's partners knew of the fraud"],"answer":1,"explanation":"Under Section 238 and Lloyd v Grace, Smith & Co., misrepresentations or frauds by agents acting in the course of their business bind the principal as if he had committed them, whether or not he benefited.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-305","question":"A instructs his agent B to beat up C, who owes A money. B does so and is made to pay damages to C. Can B recover the damages from A?","options":["No; a principal is not bound to indemnify an agent for doing a criminal act","Yes; the principal must indemnify the agent for all acts done on his instructions","Yes, but only half the damages","No, unless A promised the indemnity in writing"],"answer":0,"explanation":"Sections 222–223 give an agent indemnity for lawful acts and acts done in good faith, but Section 224 says the employer is not liable for a criminal act even if he expressly promised to indemnify.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-306","question":"A cow kept by a farmer under a contract of bailment gives birth to a calf during the bailment. To whom must the calf be delivered when the bailment ends?","options":["To the bailee, as compensation for keeping the cow","To be shared equally between bailor and bailee","To the bailor, together with the cow","To the bailee, unless the bailor paid for its feed"],"answer":2,"explanation":"Section 163: in the absence of a contract to the contrary, the bailee must deliver to the bailor any increase or profit that has accrued from the goods bailed – the illustration in the Act is a cow and its calf.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-307","question":"B agrees to buy a specific machine installed in A's factory; A is to dismantle and pack it before B collects it. Before A finishes dismantling, the factory catches fire without anyone's fault and the machine is destroyed. Who bears the loss?","options":["B, because property in specific goods passes when the contract is made","B, because he agreed to the price before the fire","A, because property and risk pass only after the machine is put in a deliverable state and B has notice","The loss is shared equally between A and B"],"answer":2,"explanation":"Section 21: where the seller must do something to specific goods to put them into a deliverable state, property does not pass until that is done and the buyer has notice. Risk follows property (Section 26), so A bears the loss.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-308","question":"A seller agrees to sell 500 kg of unascertained sugar to a buyer in another city. He separates 500 kg, delivers it to a railway carrier consigned to the buyer and does not reserve any right of disposal. The goods are lost in transit through no one's fault. Who bears the loss?","options":["The buyer, because unconditional appropriation by delivery to the carrier passed the property","The seller, because the buyer never received the goods","The carrier, who is always absolutely liable","The seller, because property in unascertained goods passes only on delivery to the buyer"],"answer":0,"explanation":"Under Section 23, delivering goods to a carrier for transmission to the buyer, without reserving the right of disposal, is an unconditional appropriation that passes property. Risk passes with property, so the buyer bears the loss.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-309","question":"Goods are delivered to B on 'sale or return' terms for 7 days. B keeps them for three weeks without giving any notice of rejection, and they are then destroyed in a fire at his premises without his fault. Who bears the loss?","options":["The seller, because B never expressed approval","The seller, because goods on approval remain at the seller's risk until paid for","The loss is split because neither party was at fault","B, because the property passed to him when the 7 days expired"],"answer":3,"explanation":"Section 24: property passes to the buyer on approval if he retains the goods beyond the time fixed for return without giving notice of rejection. With property went the risk, so B must pay the price.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-310","question":"A sells his car to B and is paid, but B leaves the car with A for a few days. Meanwhile A sells and delivers the same car to C, who pays and has no notice of the first sale. Who gets the title?","options":["B, because property had already passed to him","C, because a seller who continues in possession can pass good title to a buyer in good faith","B, because no one can give a better title than he has","Neither; the car must be returned to A"],"answer":1,"explanation":"Section 30(1) is an exception to the nemo dat rule: where a seller continues in possession after the sale, a sale and delivery by him to a person receiving in good faith without notice is valid. B's remedy is against A.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-311","question":"A buyer orders 'Brand Z industrial adhesive' by its trade name from a dealer, mentioning that he needs it for bonding glass. The adhesive is of good quality but does not bond glass well. Does the buyer have a claim for breach of the implied condition of fitness for purpose?","options":["Yes; he made his purpose known to the seller","Yes; caveat emptor does not apply to dealers","No; implied conditions apply only to sales by sample","No; under the Act there is no implied condition of fitness where a specified article is bought under its trade name"],"answer":3,"explanation":"The proviso to Section 16(1) says that, for the sale of a specified article under its patent or other trade name, there is no implied condition as to fitness for a particular purpose, because the buyer relies on the brand, not the seller's skill.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-312","question":"A buyer lawfully rejects goods delivered to him because they are not of the contracted quality. What must he do with the goods?","options":["Return them to the seller at his own cost","Sell them and remit the proceeds to the seller","Inform the seller that he refuses them; he need not send them back","Keep them and pay a reduced price"],"answer":2,"explanation":"Section 43: unless otherwise agreed, a buyer who lawfully refuses delivery need not return the goods to the seller; it is enough to intimate the refusal.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-313","question":"A seller hands goods to a carrier for delivery to the buyer at a distant city without reserving any right of disposal. While they are in transit, the seller learns that the buyer has become insolvent and has not paid. Which right can the seller now use?","options":["Stoppage in transit, because his lien ended when the goods were delivered to the carrier","Lien, because the goods have not yet reached the buyer","Resale of the goods at once, without stopping them","No right, because property has passed to the buyer"],"answer":0,"explanation":"Section 49 ends the lien when goods go to a carrier for transmission to the buyer without reservation of the right of disposal. Section 50 then lets an unpaid seller resume possession while the goods are in transit if the buyer becomes insolvent.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-314","question":"Goods are in transit to an insolvent buyer. In which situation does the unpaid seller still have the right of stoppage in transit?","options":["The buyer has collected the goods from the carrier halfway through the journey","The goods have reached their destination, but the carrier is still holding them and has not yet acknowledged that it holds them for the buyer","The carrier has acknowledged at the destination that it now holds the goods on the buyer's behalf","The carrier has wrongfully refused to deliver the goods to the buyer at the destination"],"answer":1,"explanation":"Under Section 51, transit ends if the buyer takes delivery before the destination, if the carrier attorns to the buyer after arrival, or if the carrier wrongfully refuses to deliver to the buyer. Goods merely lying with the carrier at the destination are still in transit.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-315","question":"A buyer of non-perishable goods fails to pay. The unpaid seller, still holding the goods, resells them at a loss without giving the buyer any notice of his intention to resell. What is the consequence?","options":["The seller can recover the loss, because the buyer was in default","The resale is void and the buyer can reclaim the goods","The seller can recover the loss but must pay interest to the buyer","The seller cannot recover the loss on resale from the buyer, and the buyer would be entitled to any profit"],"answer":3,"explanation":"Under Section 54(2), the seller may resell non-perishable goods and recover the loss only after giving notice of his intention to resell. If he resells without notice, he cannot recover the loss, and the buyer is entitled to any profit.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-316","question":"Which of these is a valid promissory note under the Negotiable Instruments Act?","options":["'I promise to pay B ₹5,000 seven days after my marriage with C.'","'I promise to pay B ₹5,000 on C's death.'","'Mr B, I.O.U. ₹5,000.'","'I promise to pay B ₹5,000 and all other sums which shall be due to him.'"],"answer":1,"explanation":"A promissory note needs an unconditional promise to pay a certain sum. Death is certain to happen, though its time is not, so payment is not conditional. Marriage may never happen; an I.O.U. is a mere acknowledgment of debt; 'all other sums' makes the amount uncertain.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-317","question":"A cheque was originally drawn 'Pay Ravi or bearer'. Ravi endorses it 'Pay Sunil' and signs. It is then stolen from Sunil and presented by the thief at the bank, which pays it in good faith and without negligence. Is the bank discharged?","options":["No; the special endorsement made it payable only to Sunil","No; the bank should have verified the identity of the presenter","Yes; a cheque originally payable to bearer remains payable to bearer for the paying banker despite any endorsement","Yes, but only if Sunil had endorsed it in blank"],"answer":2,"explanation":"Section 85(2): where a cheque is originally expressed to be payable to bearer, the drawee is discharged by payment in due course to the bearer, notwithstanding any endorsement, whether in full or in blank.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-318","question":"A cheque crossed generally with the words 'not negotiable' is stolen from the payee and transferred to C, who gives full value and has no notice of the theft. Can C enforce it against the drawer?","options":["No; a person taking a 'not negotiable' crossed cheque cannot get a better title than the person from whom he took it","Yes; C is a holder in due course","Yes; 'not negotiable' only stops further endorsement","No; a 'not negotiable' cheque cannot be transferred at all"],"answer":0,"explanation":"Section 130: a person taking a cheque crossed 'not negotiable' does not have, and cannot give, a better title than the transferor. The thief had no title, so C gets none, although the cheque remains transferable.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-319","question":"A cheque shows ₹25,000 in figures and 'Rupees Twenty Thousand only' in words. What amount is payable?","options":["₹25,000, the amount in figures","₹20,000, the amount in words","Nothing, because the cheque is void for uncertainty","Whichever amount the holder chooses"],"answer":1,"explanation":"Section 18: if the amount is stated differently in figures and words, the amount stated in words is the amount undertaken or ordered to be paid. (Banks in practice may return such cheques, but the legal rule is clear.)","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-320","question":"An instrument is so worded that it could be read either as a promissory note or as a bill of exchange. How must it be treated?","options":["It is void for ambiguity","It must be treated as a bill of exchange","The court decides which it is, based on the drafter's intention","The holder may treat it as either, at his election, and once chosen it is treated accordingly"],"answer":3,"explanation":"Section 17: where an instrument may be construed either as a promissory note or as a bill of exchange, the holder may at his election treat it as either, and it is thereafter treated accordingly.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-321","question":"A bank wrongly dishonours a customer's cheque even though his account had enough funds. Who can claim compensation from the bank under the Negotiable Instruments Act?","options":["The payee, because the cheque was not paid","Both the drawer and the payee equally","The drawer (the customer), for any loss or damage caused by the default","No one, because a bank owes duties only under its account terms"],"answer":2,"explanation":"Section 31: the drawee of a cheque having sufficient funds must pay it when duly required, and in default must compensate the drawer for any loss or damage. The payee has no contract with the drawer's bank; his remedy is against the drawer.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-322","question":"X finds a bearer cheque lying on the road and keeps it. Is X a 'holder' of the cheque within the meaning of the Negotiable Instruments Act?","options":["No; a holder must be entitled in his own name to possession and to receive the amount, which a finder is not","Yes; anyone in possession of a bearer cheque is its holder","Yes, but not a holder in due course","No, but he becomes a holder if he presents it within three months"],"answer":0,"explanation":"Section 8 defines a holder as a person entitled in his own name to the possession of the instrument and to receive the amount. A finder or thief has possession but no such entitlement, though a later transferee in good faith may still become a holder in due course.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-323","question":"A cheque has two parallel transverse lines across its face with the words 'and Co.' between them and nothing else. A second cheque has 'State Bank of India' written across its face without any lines. How are they treated?","options":["The first is generally crossed and the second is specially crossed","Both are generally crossed","The first is specially crossed and the second is not crossed","The first is generally crossed and the second is not crossed"],"answer":0,"explanation":"A general crossing is two parallel transverse lines, with or without 'and company' (Section 123). A special crossing is the name of a banker written across the face – the lines are not needed (Section 124).","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-324","question":"M owns all but one of the shares of a timber company and is also its largest creditor. He insures the company's timber in his own name. The timber is destroyed by fire. Can M recover under the policy?","options":["No; the timber belongs to the company, so M as shareholder has no insurable interest in it","Yes; as near-sole owner he bears the whole economic loss","Yes, but only to the extent of his loan to the company","No, because the company should have taken the policy jointly with him"],"answer":0,"explanation":"A company is a separate legal person and owns its property; a shareholder, even a dominant one, or an unsecured creditor has no insurable interest in specific company assets (Macaura v Northern Assurance Co.).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-325","question":"During a war, a company registered in India supplies goods to a firm. Almost all its shareholders and all its directors are nationals of the enemy country. On which ground can a court lift the corporate veil here?","options":["To make the shareholders personally liable for the company's trade debts","To treat the company as a partnership","To tax the shareholders on the company's undistributed profits","To determine whether the company has an enemy character"],"answer":3,"explanation":"Courts look behind the corporate form to see who controls a company when deciding whether it has an enemy character (Daimler Co. v Continental Tyre). Limited liability for trade debts is otherwise preserved.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-326","question":"A private company's register shows 190 non-employee member entries, of which 6 are three pairs of persons holding shares jointly. In addition, 25 current employees and 8 former employees (who became members while employed and kept their shares) are members. How many members count towards the 200-member limit?","options":["223","187","190","215"],"answer":1,"explanation":"Joint holders count as one member, so 190 entries become 187. Current employees, and former employees who became members while employed and continue as members, are excluded. Counting everyone gives 223.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-327","question":"A company wants to move its registered office (i) to another building within the same city; (ii) to another state. Which approvals are needed?","options":["(i) A special resolution; (ii) a special resolution and the Tribunal's approval","(i) A board resolution; (ii) an ordinary resolution only","(i) A board resolution; (ii) a special resolution and the Central Government's approval","(i) Approval of the Regional Director; (ii) approval of the Registrar only"],"answer":2,"explanation":"A shift within the local limits of the same city is a board matter; moving outside the city's local limits would need a special resolution (Section 12(5)), and changing ROC jurisdiction within the state needs the Regional Director's confirmation. A shift to another state alters the memorandum, so it needs a special resolution and confirmation by the Central Government under Section 13(4).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-328","question":"The articles of a public company contain an entrenchment clause stating that a specified provision may be altered only with the consent of all members. Which statement about entrenchment is correct?","options":["Entrenchment provisions are not permitted under the Companies Act, 2013","In a private company entrenchment needs the agreement of all members; in a public company a special resolution suffices to adopt it","Entrenchment provisions may be included only in the memorandum","Entrenchment provisions can be adopted only with the Tribunal's approval"],"answer":1,"explanation":"Section 5(3)–(4) allows articles to say that specified provisions can be altered only if conditions stricter than a special resolution are met. Such provisions can be made at formation or by amendment – with all members' agreement in a private company and by special resolution in a public one.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-329","question":"A company's articles state that X shall be its solicitor for life. X is not a member. The company later appoints a different solicitor, and X sues the company relying on the articles. What is the likely outcome?","options":["X fails, because the articles bind the company and its members only in their capacity as members, not outsiders","X succeeds, because the articles are a public document binding the company","X succeeds, because the company is estopped by its own articles","X fails only because a life appointment is void for uncertainty"],"answer":0,"explanation":"Section 10 makes the memorandum and articles a contract between the company and its members as members. An outsider cannot enforce them, even if named in them (Eley v Positive Government Security Life Assurance).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-330","question":"Before a company was incorporated, its promoter signed a contract on its behalf to buy machinery. After incorporation the company wants to be bound by and enforce the contract. Which statement best reflects Indian law?","options":["The company automatically becomes a party on incorporation","The company can ratify the contract by a board resolution like any agent's act","Pre-incorporation contracts are void, and even the promoter is not liable","The company cannot simply ratify it, but under the Specific Relief Act it may enforce it if the contract was warranted by its terms of incorporation and it accepted it and communicated acceptance"],"answer":3,"explanation":"A company not in existence cannot ratify, as ratification needs a principal in existence at the time (Kelner v Baxter); the promoter remains personally liable. The Specific Relief Act, 1963 lets the company enforce or be bound if the contract was for its purposes and it adopted it after incorporation.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-331","question":"A prospectus containing an untrue statement names X as a director. X proves that the prospectus was issued without his knowledge or consent and that, on becoming aware of its issue, he at once gave reasonable public notice of this. What is his civil liability to subscribers under Section 35?","options":["He is fully liable, because he was named as a director","He is liable only for the part of the loss he could have prevented","He is not liable, because he proves lack of knowledge or consent and prompt public notice","He is not liable only if he also resigns as director"],"answer":2,"explanation":"Section 35(2) protects a person who, having consented to be a director, withdrew his consent before the issue, or who proves that the prospectus was issued without his knowledge or consent and that on becoming aware of its issue he forthwith gave reasonable public notice to that effect.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-332","question":"A company has cumulative preference shares on which no dividend has been paid for the last two years. In general meetings, on which resolutions may these preference shareholders vote?","options":["Only on resolutions that directly affect the rights attached to their shares","On every resolution placed before the company","Only on resolutions to wind up the company","On no resolution until arrears are paid"],"answer":1,"explanation":"Section 47(2): preference shareholders ordinarily vote only on resolutions directly affecting their rights, or on winding up or reduction of capital. But if their dividend has not been paid for two years or more, they get the right to vote on all resolutions.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-333","question":"For which of these purposes may a company NOT use its securities premium account?","options":["Issuing fully paid bonus shares","Writing off preliminary expenses","Paying a dividend to equity shareholders","Providing the premium payable on redemption of debentures"],"answer":2,"explanation":"Section 52 limits the securities premium to purposes such as fully paid bonus shares, writing off preliminary expenses, writing off issue expenses, commissions or discounts, providing premium on redemption of preference shares or debentures, and buy-back. Dividends cannot be paid out of it.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-334","question":"Which of these statements about a bonus issue under the Companies Act, 2013 are correct?\nI. It may be made out of the securities premium account.\nII. It may be made out of a reserve created by revaluation of assets.\nIII. It may be made in lieu of a dividend.\nIV. It may be made out of the capital redemption reserve account.","options":["I and IV only","I and II only","I, III and IV only","II and III only"],"answer":0,"explanation":"Section 63 allows bonus shares out of free reserves, securities premium or the capital redemption reserve, but not out of revaluation reserves, and never in lieu of dividend. The capital redemption reserve is expressly allowed as a source.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-335","question":"A company wants to buy back its equity shares. From which source can it NOT finance the buy-back?","options":["Its free reserves","Its securities premium account","The proceeds of an earlier issue of preference shares","The proceeds of an earlier issue of the same kind of equity shares"],"answer":3,"explanation":"Section 68(1) permits buy-back out of free reserves, securities premium or the proceeds of an issue of shares or other securities, but no buy-back of any kind of shares can be made out of the proceeds of an earlier issue of the same kind of shares.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-336","question":"A member pays the full amount on his partly paid shares before the company makes the calls (calls in advance), as the articles allow. Which statement is correct?","options":["He gets full voting rights on the amount at once","He is not entitled to voting rights on the amount paid in advance until it becomes payable","The amount must be refunded because calls in advance are prohibited","He becomes a creditor and loses his membership rights"],"answer":1,"explanation":"Section 50 lets a company accept calls in advance if its articles authorise it (and it may pay interest on them), but the member is not entitled to voting rights on that amount until it is called and becomes payable.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-337","question":"How does transmission of shares differ from transfer of shares?","options":["Transmission is a voluntary sale and needs a stamped transfer deed","Transmission requires the consent of all other members","Transmission applies only to preference shares","Transmission happens by operation of law, such as on a holder's death or insolvency, and needs no transfer deed"],"answer":3,"explanation":"A transfer is a deliberate act of the holder by a duly stamped instrument of transfer. Transmission occurs by operation of law – death, insolvency or lunacy – and the legal heir or representative gets the shares on producing evidence, without a transfer deed or stamp duty.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-338","question":"A company creates a charge on its machinery in favour of a lender but neither files it with the Registrar within the time allowed nor gets it registered later. The company goes into liquidation. What is the position of the lender?","options":["The charge is not taken into account by the liquidator or other creditors, though the debt itself remains payable","The debt is extinguished","The charge is valid because registration is only a formality","The lender gets priority over all creditors because the charge was created first"],"answer":0,"explanation":"Under Section 77(3), an unregistered charge is not taken into account by the liquidator or any creditor. The lender becomes an unsecured creditor; the underlying debt is not destroyed.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-339","question":"X signed the memorandum of a company as a subscriber but was never allotted shares, and his name was never entered in the register of members. Is he a member?","options":["No; only persons entered in the register are members","No; a subscriber must also apply for shares in writing","Yes; subscribers are deemed to have agreed to become members and are entered as members on registration","Yes, but only after the first general meeting"],"answer":2,"explanation":"Under Section 2(55), the subscribers to the memorandum are deemed to have agreed to become members and, on registration, are entered as members. Membership of subscribers arises from subscription itself, unlike other members who need agreement plus entry in the register.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-340","question":"Members holding 12% of a company's paid-up capital with voting rights validly requisition an extraordinary general meeting. The board does nothing. What can the requisitionists do?","options":["Apply to the Tribunal, which alone can call the meeting","Call the meeting themselves within three months of the requisition, and recover their reasonable expenses from the company","Nothing, because calling general meetings is solely the board's power","Call the meeting at any time, without any time limit"],"answer":1,"explanation":"Section 100: if the board does not, within 21 days of a valid requisition, proceed to call a meeting to be held within 45 days, the requisitionists may themselves call and hold it within three months, and the company must reimburse their reasonable expenses.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-341","question":"A public company wants to hold an extraordinary general meeting at shorter notice than 21 clear days. Whose consent is needed?","options":["A majority in number of members entitled to vote who represent at least 95% of the paid-up share capital carrying voting rights","At least 95% of the members entitled to vote, irrespective of capital","The board alone, if there is urgency","Members holding a simple majority of the paid-up capital"],"answer":0,"explanation":"Section 101(1): for an AGM, consent of at least 95% of the members entitled to vote; for any other general meeting, a majority in number of members entitled to vote who represent at least 95% of the paid-up capital giving voting rights (or of total voting power for companies without share capital).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-342","question":"A public company has 3,200 members. Unless its articles require more, what is the quorum for its general meeting?","options":["5 members personally present","30 members personally present","15 members personally present","Members holding one-tenth of the paid-up capital"],"answer":2,"explanation":"Section 103: for a public company, quorum is 5 members if members are not more than 1,000; 15 if more than 1,000 but not more than 5,000; and 30 if more than 5,000. A private company needs 2.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-343","question":"A shareholder appoints a proxy for a general meeting of a company with share capital. Which statement about the proxy is correct?","options":["The proxy must be a member of the company","The proxy can speak and vote on a show of hands","The proxy can vote on a show of hands but not on a poll","The proxy cannot speak at the meeting and can vote only on a poll"],"answer":3,"explanation":"Under Section 105, a proxy need not be a member, but he has no right to speak at the meeting and is not entitled to vote except on a poll.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-344","question":"For which of these resolutions is a special notice required under the Companies Act, 2013?","options":["A resolution to declare a final dividend","A resolution to alter the articles of association","A resolution to remove a director before the end of his term","A resolution to approve the annual financial statements"],"answer":2,"explanation":"Special notice (from members with the prescribed holding, at least 14 days before the meeting) is required for removing a director under Section 169 and for appointing an auditor other than the retiring auditor, among others. Altering the articles needs a special resolution, which is different.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-345","question":"A newly registered company held its first board meeting 25 days after incorporation. Its next meetings were held 100 days, 230 days and 300 days after incorporation. Has it complied with the requirement on the gap between board meetings?","options":["Yes; it held four meetings within its first year","Yes; the gap rule does not apply in the first year","No; the first meeting should have been held within 15 days","No; the gap between the second and third meetings exceeds 120 days"],"answer":3,"explanation":"Section 173(1) requires the first board meeting within 30 days of incorporation (met) and at least four meetings a year, with not more than 120 days between two consecutive meetings. Meetings on day 100 and day 230 are 130 days apart.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-346","question":"A director attends no board meetings in person over a 12-month period, but he joins one of the five meetings held during that time by video conferencing. The other four he misses after obtaining leave. Has his office become vacant under Section 167?","options":["Yes; he was absent from all meetings in person","No; he attended one meeting, and participation through video conferencing counts as attendance","Yes; leave of absence does not count as attendance","No; a director's office never becomes vacant for absence if leave was granted"],"answer":1,"explanation":"Section 167(1)(b) vacates the office if a director absents himself from all board meetings held during 12 months, with or without leave. Attending even one meeting, including through the permitted video-conferencing mode, avoids this.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-347","question":"Shareholders want to remove a director who was appointed by the Tribunal under Section 242 in an oppression and mismanagement case. Can they do it by an ordinary resolution under Section 169?","options":["No; a director appointed by the Tribunal under Section 242 cannot be removed under Section 169","Yes; any director can be removed by an ordinary resolution after special notice","Yes, but only by a special resolution","No, unless the director consents in writing"],"answer":0,"explanation":"Section 169(1) allows removal of a director by ordinary resolution after giving him a reasonable opportunity of being heard, but it expressly excludes a director appointed by the Tribunal under Section 242.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-348","question":"A director is appointed as an additional director by the board under powers in the articles. Until when does he hold office?","options":["For a full term of five years","Until the next board meeting","Until he is removed by the shareholders","Up to the date of the next annual general meeting, or the last date on which it should have been held, whichever is earlier"],"answer":3,"explanation":"Section 161(1): an additional director holds office up to the date of the next AGM or the last date on which the AGM should have been held, whichever is earlier. He must then be appointed by the members to continue.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-349","question":"A company's paid-up capital is ₹50 crore, free reserves ₹30 crore and securities premium ₹20 crore. Its existing borrowings are ₹70 crore, of which ₹10 crore are temporary loans from its bankers in the ordinary course of business. The board wants a fresh 5-year term loan of ₹45 crore. Is a special resolution under Section 180 needed?","options":["No; total borrowings of ₹115 crore are within twice the paid-up capital","Yes; non-temporary borrowings would become ₹105 crore, exceeding the ₹100 crore limit","No; borrowings would be ₹100 crore, exactly at the limit","Yes, because any term loan over ₹40 crore needs a special resolution"],"answer":1,"explanation":"Section 180(1)(c) needs a special resolution where borrowings, excluding temporary loans from bankers in the ordinary course, exceed paid-up capital + free reserves + securities premium = ₹100 crore. After the loan: ₹60 crore + ₹45 crore = ₹105 crore.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-350","question":"A company's paid-up capital is ₹100 crore, free reserves ₹60 crore and securities premium ₹20 crore. Under Section 186, up to what aggregate amount can it give loans, guarantees and investments in other bodies corporate without a special resolution?","options":["₹108 crore","₹80 crore","₹180 crore","₹96 crore"],"answer":0,"explanation":"The limit is the higher of 60% of (paid-up capital + free reserves + securities premium) = 60% × 180 = ₹108 crore, and 100% of (free reserves + securities premium) = ₹80 crore. So ₹108 crore. ₹96 crore applies 60% to paid-up capital and free reserves only.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-351","question":"Which of these is NOT a key managerial personnel (KMP) as defined in the Companies Act, 2013?","options":["The company secretary","The chief financial officer","The internal auditor","A whole-time director"],"answer":2,"explanation":"Section 2(51) lists the CEO, managing director or manager; the company secretary; the whole-time director; the CFO; and such other officers (not more than one level below directors, in whole-time employment) designated by the board. The internal auditor is not KMP by definition.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-352","question":"Company A holds 60% of the voting power of Company B. A also holds 30% of the voting power of Company D, and B holds another 30% of D. Is D a subsidiary of A?","options":["No; A holds only 30% of D directly","No; D is an associate of A, not a subsidiary","Yes, but only if A also controls D's board","Yes; A controls more than half of D's voting power together with its subsidiary B"],"answer":3,"explanation":"Section 2(87) treats a company as a subsidiary if the holding company exercises or controls more than one-half of its total voting power either on its own or together with one or more of its subsidiaries. A + B = 60% of D.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-353","question":"Company P holds 25% of the total voting power of Company Q, and Q is not its subsidiary or joint venture. How is Q classified in relation to P?","options":["As a subsidiary, because P holds more than 20%","As a related party only if P's directors sit on Q's board","As an associate company, because P has significant influence","As a holding company of P"],"answer":2,"explanation":"Under Section 2(6), an associate is a company in which another company has significant influence, meaning control of at least 20% of total voting power or of business decisions under an agreement, but which is not its subsidiary.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-354","question":"A company with share capital has 600 members. A group of 70 members, together holding 6% of the issued share capital (all calls paid), wants to file a petition for oppression and mismanagement under Section 241. Are they eligible to apply under Section 244, without any waiver?","options":["Yes; they number at least one-tenth of the members, which is less than 100","No; they need at least 100 members","No; they need members holding at least 10% of the issued share capital","Yes, but only with the Central Government's prior sanction"],"answer":0,"explanation":"Section 244 allows not less than 100 members or one-tenth of the total members, whichever is less (here 60), or members holding at least one-tenth of the issued share capital. 70 members satisfy the numerical test even though their holding is only 6%.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-355","question":"A one person company (OPC) is being incorporated. Which requirement relates specifically to an OPC?","options":["It must have at least two directors","The memorandum must name a nominee who will become the member on the sole member's death or incapacity","Its single member may be a body corporate","It must hold an annual general meeting every year with a quorum of two"],"answer":1,"explanation":"Section 3(1)(c) requires an OPC's memorandum to name a person, with his consent, who will become the member if the subscriber dies or becomes incapable of contracting. Only a natural person can be its member, it can have one director, and Section 96 on AGMs does not apply to it.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-356","question":"For a month, a registered person's output tax is IGST ₹40,000, CGST ₹10,000 and SGST ₹10,000. Its input tax credit is IGST nil, CGST ₹30,000 and SGST ₹5,000. Using credit in the legally permitted order, how much must it pay in cash under each head?","options":["IGST ₹40,000; CGST nil; SGST ₹5,000","IGST ₹15,000; CGST nil; SGST nil","IGST ₹20,000; CGST nil; SGST nil","IGST ₹20,000; CGST nil; SGST ₹5,000"],"answer":3,"explanation":"CGST credit first pays CGST (₹10,000) and the balance ₹20,000 may pay IGST. SGST credit pays SGST ₹5,000, leaving ₹5,000 SGST in cash. CGST credit can never pay SGST, and SGST credit cannot pay CGST, so ₹5,000 of SGST stays payable in cash.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-357","question":"A supplier quotes a list price of ₹1,00,000 and gives a 5% discount on the invoice at the time of supply. The invoice also charges ₹3,000 for delivery to the buyer and ₹1,000 of a local levy that is not GST. Separately, the buyer pays ₹2,000 directly to a testing laboratory, a fee the supplier was contractually liable to pay and which is not included in the invoice price. What is the value of supply for GST?","options":["₹1,01,000","₹99,000","₹96,000","₹1,06,000"],"answer":0,"explanation":"Value = 95,000 (net of the invoice discount) + 3,000 incidental delivery charge + 1,000 non-GST tax + 2,000 supplier's liability borne by the recipient = ₹1,01,000. Leaving out the buyer-paid fee gives ₹99,000; ignoring the discount gives ₹1,06,000.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-358","question":"An Indian subsidiary receives management support services free of charge from its parent company located abroad, in the course of its business. What is the GST position?","options":["It is not a supply because there is no consideration","It is an export of services by the parent and hence zero-rated","It is a supply even without consideration, being an import of services from a related person, taxable under reverse charge","It is a supply only if the parent registers in India"],"answer":2,"explanation":"Schedule I treats import of services by a person from a related person outside India, in the course or furtherance of business, as a supply even without consideration. Tax on imported services is paid by the Indian recipient under reverse charge.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-359","question":"Which of these is a supply under GST?\nI. Sale of a completed flat after the completion certificate is issued and the builder has received the entire price after that date\nII. Sale of a flat in an under-construction project where the buyer pays instalments before completion\nIII. Sale of agricultural land","options":["I and II only","II only","I and III only","I, II and III"],"answer":1,"explanation":"Schedule III treats sale of land and, subject to the completion-certificate condition, sale of a completed building as neither goods nor services. Construction of a complex where any consideration is received before completion is a supply of services under Schedule II.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-360","question":"A contractor gives a machine on hire to a builder for six months; ownership stays with the contractor, and the builder gets the right to use it. How is this treated under GST?","options":["As a supply of goods","As a supply of services","As neither goods nor services","As a composite supply of goods and services taxed as goods"],"answer":1,"explanation":"Schedule II: transfer of the right to use goods without transfer of title is a supply of services. A transfer of title in goods would be a supply of goods.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-361","question":"A machinery maker registered in Gujarat sells a machine to a buyer registered in Maharashtra. Under the contract it must deliver and install the machine at the buyer's plant in Karnataka. What is the place of supply?","options":["Maharashtra, the buyer's registered location","Gujarat, where the movement begins","Maharashtra or Karnataka, at the buyer's choice","Karnataka, where the machine is installed"],"answer":3,"explanation":"Under Section 10(1)(d) of the IGST Act, where goods are assembled or installed at site, the place of supply is the place of installation or assembly – Karnataka. The usual 'movement terminates' rule gives way to this specific rule.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-362","question":"A catering company sells packaged meals to passengers on a train from Delhi to Mumbai. The meals were taken on board at Delhi and are sold as the train passes through Rajasthan and Gujarat. What is the place of supply of the meals?","options":["Rajasthan or Gujarat, where each meal is sold","Mumbai, the final destination of the train","Delhi, where the goods were taken on board","The supplier's principal place of business"],"answer":2,"explanation":"Section 10(1)(e) of the IGST Act: where goods are supplied on board a conveyance such as a train, the place of supply is the location where the goods are taken on board – Delhi.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-363","question":"An unregistered person living in Bengaluru buys a Mumbai–Delhi air ticket for himself from an airline registered in Maharashtra. What is the place of supply and which tax applies?","options":["Maharashtra, where he embarks; CGST + SGST","Karnataka, his place of residence; IGST","Delhi, the destination; IGST","Maharashtra, the airline's location; IGST"],"answer":0,"explanation":"For passenger transport to an unregistered person, the place of supply is where the passenger embarks on the conveyance for a continuous journey – Mumbai. The airline is in Maharashtra, so the supply is intra-state.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-364","question":"An unregistered individual in Pune hands over a parcel at a courier's Pune office for delivery to Kolkata. The courier company's supplying office is registered in Maharashtra. What is the place of supply of the courier service?","options":["West Bengal, where the parcel is delivered","The courier company's head office state","Maharashtra, where the goods are handed over for transport","Either state, at the courier's choice"],"answer":2,"explanation":"For transport of goods, including mail and courier, to an unregistered person, the place of supply is the location where the goods are handed over for transport. So the supply is intra-state in Maharashtra.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-365","question":"The Indian branch of a foreign bank provides IT support to its head office abroad and receives payment in foreign exchange. Is this an export of services?","options":["No; the supplier and recipient are merely establishments of a distinct person, so the condition for export fails","Yes; the recipient is outside India and payment is in foreign exchange","Yes, provided the place of supply is outside India","No; IT services can never be exported"],"answer":0,"explanation":"An export of services needs, among other conditions, that the supplier and the recipient are not merely establishments of a distinct person (a branch and its head office). This condition fails even if the other conditions are met.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-366","question":"A registered dealer in Delhi (A) orders goods from a supplier in Haryana (S) and directs S to deliver them straight to A's customer in Delhi (C). A pays S. For input tax credit on S's invoice, when is A treated as having received the goods?","options":["Only when A physically inspects the goods","Only when C pays A","Never; only C can take the credit","When S delivers the goods to C on A's direction"],"answer":3,"explanation":"Under Section 16(2)(b), goods delivered by the supplier to another person on the direction of the registered person are deemed received by the registered person. So A can take credit (subject to other conditions) when C receives the goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-367","question":"In which case is input tax credit available to the recipient, assuming GST rates and other conditions are met?","options":["A manufacturer buys a sedan for its sales director","A car dealer buys cars for resale","A company pays for club memberships for its managers","A firm pays for its employees' holiday travel"],"answer":1,"explanation":"Section 17(5) blocks credit on passenger motor vehicles (up to 13 seats), club memberships and travel benefits to employees on vacation. Vehicles bought for further supply of such vehicles are an express exception, so the dealer gets credit.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-368","question":"A registered professional buys a laptop for ₹1,00,000 plus GST of ₹18,000. He uses it 60% for his profession and 40% for personal purposes. How much input tax credit can he take?","options":["₹18,000","₹7,200","₹10,800","Nil"],"answer":2,"explanation":"Section 17(1): where goods are used partly for business and partly for other purposes, credit is restricted to the part attributable to business – 60% of ₹18,000 = ₹10,800. ₹7,200 is the personal share.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-369","question":"A supplier issues a credit note after a post-supply price reduction that was agreed before the supply. The recipient has already passed on the whole tax to its own customers by charging it in their prices and has not reversed any credit. What is the supplier's position?","options":["It can always reduce its output tax once a credit note is issued","It cannot reduce its output tax, because the incidence of tax has been passed on to another person","It can reduce output tax only in the following financial year","It must issue a debit note instead"],"answer":1,"explanation":"The proviso to Section 34(2) bars a reduction in output tax liability if the incidence of tax and interest on the supply has been passed on to any other person – unjust enrichment is not allowed.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-370","question":"Three weeks after a supply, a supplier and buyer agree that, because of increased input costs, the buyer will pay ₹10,000 more than the invoice value. What document should the supplier issue?","options":["A debit note","A credit note","A revised bill of supply","A fresh tax invoice for a new supply"],"answer":0,"explanation":"Section 34(3): where the taxable value or tax in an invoice is less than the amount payable, the supplier issues a debit note. A credit note is for reductions or returns.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-371","question":"A customer orders food from a restaurant through a food-delivery app (an electronic commerce operator). Who is liable to pay GST on the restaurant service?","options":["The restaurant, under forward charge","The customer, under reverse charge","Nobody; food delivered through apps is exempt","The e-commerce operator"],"answer":3,"explanation":"Under Section 9(5) of the CGST Act, the government has notified restaurant services supplied through an e-commerce operator, so the operator pays the tax as if it were the supplier. Its own platform fee is a separate supply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-372","question":"A registered trader sells only goods that are fully exempt from GST. What document should it issue to its customers?","options":["A tax invoice showing nil tax","A debit note","A receipt voucher","A bill of supply"],"answer":3,"explanation":"A registered person supplying exempt goods or services, or paying tax under the composition scheme, issues a bill of supply instead of a tax invoice under Section 31(3)(c).","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-373","question":"A buyer in Delhi imports goods from Germany. Which statement about GST on this import is correct?","options":["IGST is levied at the time of import along with customs duty, and the importer can take input tax credit of it","CGST and SGST of Delhi are levied, because the importer is in Delhi","No GST applies because imports are zero-rated","The German supplier must register in India and charge IGST"],"answer":0,"explanation":"Import of goods is treated as an inter-state supply. IGST is levied under the Customs Tariff Act on the assessable value plus customs duty, collected with customs duty, and the importer can take credit of this IGST in the usual way.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-374","question":"An importer, while the goods are still on the high seas and before they are cleared for home consumption, sells them to a buyer by endorsing the bill of lading. How is this sale treated under GST?","options":["As an inter-state supply on which the importer must pay IGST","As neither a supply of goods nor a supply of services; IGST is paid by the buyer at the time of customs clearance","As an export of goods","As a supply of services by the importer"],"answer":1,"explanation":"Schedule III treats the supply of goods by the consignee to another person, by endorsement of documents of title, after dispatch from the port of origin abroad but before clearance for home consumption, as neither goods nor services. Tax is collected at the customs stage.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-375","question":"An Indian trader buys goods from a supplier in China and sells them to a buyer in the UAE; the goods are shipped directly from China to the UAE and never enter India. What is the GST position of the trader's sale?","options":["It is an export of goods and zero-rated","It is an inter-state supply liable to IGST","It is neither a supply of goods nor a supply of services","It is an import of goods liable to IGST"],"answer":2,"explanation":"Schedule III covers supply of goods from a place outside India to another place outside India without the goods entering India, so merchant trading of this kind is outside GST.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-376","question":"A supplier delivers goods along with transport to the buyer's warehouse and transit insurance, all for one inclusive price, as is normal in the trade. How is the supply taxed?","options":["As a mixed supply taxed at the highest rate among goods, transport and insurance","Each element is taxed separately at its own rate","As a composite supply taxed at the rate applicable to the goods, the principal supply","Transport is exempt and only the goods are taxed"],"answer":2,"explanation":"Goods, transport and insurance supplied together in the ordinary course of business, with the goods as the principal supply, form a composite supply (Section 2(30)), taxed at the rate of the principal supply.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-377","question":"Which of these must register under GST even if its aggregate turnover is below the threshold?","options":["A casual taxable person making taxable supplies","A trader making only intra-state exempt supplies","An agriculturist supplying produce from his own cultivation","A person making only supplies not liable to tax"],"answer":0,"explanation":"Section 24 requires compulsory registration, irrespective of threshold, for persons such as casual taxable persons, those liable under reverse charge, non-resident taxable persons and certain e-commerce suppliers. Persons making only exempt or non-taxable supplies, and agriculturists for their own produce, need not register.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-378","question":"A company runs a canteen for workers in its factory because the Factories Act obliges it to. It hires an outside caterer for this. Is input tax credit on the catering service available, assuming the company recovers nothing from the workers?","options":["No; credit on food and beverages is always blocked","Yes, but only half the credit","No, unless the workers pay for the meals","Yes; the block on food and catering does not apply where providing it is obligatory for an employer under any law"],"answer":3,"explanation":"The proviso to Section 17(5)(b) allows credit on goods or services that an employer is obliged to provide to its employees under any law in force, which covers a statutory canteen.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-379","question":"The karta of a Hindu undivided family lives in Dubai and takes most decisions there, but some important decisions about the family's affairs are taken by family members in India. What is the HUF's residential status (assume the usual rule for HUFs)?","options":["Non-resident, because the karta lives abroad","Resident only if the karta stays in India for 182 days","Non-resident, because most decisions are taken abroad","Resident, because control and management of its affairs is not wholly outside India"],"answer":3,"explanation":"An HUF (like a firm) is resident unless the control and management of its affairs is situated wholly outside India. Even partial control in India makes it resident; the karta's own stay matters only for deciding whether a resident HUF is ordinarily resident.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-380","question":"Assume: an individual who is resident is 'not ordinarily resident' (RNOR) if he was non-resident in 9 of the 10 preceding years. Mr K returns to India after 12 years abroad and is resident this year. His income: (1) salary for work done in India; (2) profits of a business in London controlled from London; (3) fees from a profession set up in India but carried on abroad; (4) rent from a flat in Singapore, received in Singapore. Which are taxable in India?","options":["(1) only","(1) and (3) only","(1), (2) and (3) only","All four"],"answer":1,"explanation":"An RNOR is taxed on income received or accruing in India, plus foreign income from a business controlled in, or a profession set up in, India. The London business is controlled abroad and the Singapore rent is foreign income received abroad, so both escape.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-381","question":"Assume that arrears of rent are taxed in the year of receipt after a deduction of 30%, whether or not the assessee still owns the property. Mr P sold his let-out house last year. This year he receives ₹1,00,000 of rent arrears for the period when he owned it. How much is taxable this year?","options":["₹70,000 under 'Income from house property'","Nil, because he no longer owns the property","₹1,00,000 under 'Income from other sources'","₹70,000 under 'Income from other sources'"],"answer":0,"explanation":"Arrears of rent are deemed income from house property in the year of receipt, even if the assessee is no longer the owner, after the stated 30% deduction: ₹1,00,000 × 70% = ₹70,000. The usual ownership condition is relaxed for arrears.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-382","question":"Mr R lets out a furnished flat under one agreement but at separately stated rents: ₹20,000 a month for the flat and ₹5,000 a month for the furniture, and the tenant could have rented the flat without the furniture. How is the rent taxed?","options":["The whole ₹25,000 under 'House property'","The whole ₹25,000 under 'Other sources'","Flat rent under 'House property' and furniture rent under 'Other sources'","The whole ₹25,000 under 'Business or profession'"],"answer":2,"explanation":"When the building and other assets are let together but the lettings are separable, rent for the building is house-property income and rent for the other assets is taxed under 'Other sources' (or business). Only an inseparable composite letting is taxed wholly as other sources or business.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-383","question":"A trader owns a building and uses it as the shop for his own business. How is the building treated for income-tax purposes?","options":["Its annual value is taxed under 'House property'","Its fair rent is added to business income","Its annual value is taxed under 'Other sources'","No income from house property is computed, because it is used for his own business"],"answer":3,"explanation":"House-property income excludes property occupied by the owner for his own business or profession whose profits are taxable. No notional rent is taxed; the use is reflected through business expenses such as depreciation and repairs.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-384","question":"Employer X allots shares to employee Y under an ESOP at ₹100 each; the fair market value on the date of exercise is ₹400. Y sells them two years later at ₹650. Per share, how much is taxed as a perquisite and how much as capital gain?","options":["Perquisite ₹550; capital gain nil","Perquisite ₹300; capital gain ₹250","Perquisite nil; capital gain ₹550","Perquisite ₹300; capital gain ₹550"],"answer":1,"explanation":"The perquisite is FMV on exercise minus the amount paid: 400 − 100 = ₹300, taxed as salary. For capital gains, the cost is that FMV (₹400), so the gain is 650 − 400 = ₹250. Using ₹100 as the cost would tax ₹300 twice.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-385","question":"Salary for April of the next financial year is paid to an employee in advance, in March of the current financial year. In which year is it taxed?","options":["In the current year, because salary is taxed on a due or receipt basis, whichever is earlier","In the next year, when it falls due","Half in each year","In the year the employee chooses"],"answer":0,"explanation":"Salary is charged on the earlier of the due basis and the receipt basis. Advance salary is taxed when received, and it is not taxed again when it falls due.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-386","question":"An employee receives ₹5 lakh from his employer as compensation for the premature termination of his employment, which is not covered by any specific exemption. How is it taxed?","options":["As a capital receipt, not taxable","Under 'Income from other sources'","As 'profits in lieu of salary', under the head 'Salaries'","As a short-term capital gain"],"answer":2,"explanation":"Compensation received from an employer on termination of employment, or on modification of its terms, is 'profits in lieu of salary' and taxed under 'Salaries', unless a specific exemption applies.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-387","question":"A business wrote off a bad debt of ₹80,000 two years ago and was allowed a deduction for it. This year it unexpectedly recovers ₹50,000 of that debt. How is the recovery treated?","options":["Nothing is taxable because it is a capital receipt","₹50,000 is taxable as business income this year","₹80,000 is taxable because the earlier deduction is reversed","Only ₹30,000 is taxable"],"answer":1,"explanation":"When a bad debt allowed earlier is recovered, the amount recovered (to the extent of the deduction allowed) is deemed business income in the year of recovery, even if the business is no longer carried on.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-388","question":"Assume the block-of-assets rules: if the sale proceeds of assets sold in a year exceed the opening WDV of the block plus additions, the excess is a short-term capital gain. A block has an opening WDV of ₹5 lakh, and an asset costing ₹2 lakh was added this year. One old asset is sold for ₹9 lakh; other assets remain in the block. What follows?","options":["Short-term capital gain of ₹2 lakh, and no depreciation on the block this year","No capital gain, because the block still has assets","Short-term capital gain of ₹4 lakh","Long-term capital gain of ₹2 lakh because the asset was old"],"answer":0,"explanation":"Proceeds (9) exceed opening WDV + additions (5 + 2 = 7) by ₹2 lakh, which is deemed a short-term capital gain whatever the holding period. The block's WDV becomes nil, so no depreciation arises, even though assets remain.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-389","question":"A trader converts land held as a capital asset into stock-in-trade when its fair market value is ₹80 lakh (cost ₹30 lakh). He sells the land as stock two years later for ₹1 crore. Assume the usual rules for conversion of a capital asset into stock-in-trade. What is taxed, and when?","options":["Capital gain of ₹70 lakh in the year of conversion","Business profit of ₹70 lakh in the year of sale","Capital gain on ₹80 lakh as full value, and business profit of ₹20 lakh, both taxed in the year of sale","Capital gain on ₹80 lakh as full value in the year of conversion, and business profit of ₹20 lakh in the year of sale"],"answer":2,"explanation":"Conversion is a transfer, with the FMV on conversion as the full value of consideration, but the gain is taxed in the year the stock is sold. The business profit is sale price minus that FMV: 100 − 80 = ₹20 lakh, also in the year of sale.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-390","question":"Which of these is a capital asset for an individual who is not a dealer in it?","options":["A car held for personal use","Furniture held for personal use","Clothes held for personal use","Gold jewellery held for personal use"],"answer":3,"explanation":"Movable property held for personal use is excluded from 'capital asset', but jewellery, archaeological collections, drawings, paintings, sculptures and works of art are expressly kept within it.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-391","question":"A person wins ₹5,00,000 in a lottery after buying tickets worth ₹20,000 over the year. Assume the special rules for winnings. How much is taxable under 'Other sources'?","options":["₹4,80,000, after deducting the cost of tickets","₹5,00,000, because no expenditure or allowance is deductible from such winnings","Nil, because lottery winnings are casual receipts","₹4,80,000, but taxed at normal slab rates"],"answer":1,"explanation":"Winnings from lotteries, crossword puzzles and similar games are taxed at a special flat rate on the gross amount; no expenditure, allowance or basic exemption is set off against them, so the ticket cost is ignored.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-392","question":"Mr S holds 40% of the shares of a company. His wife, who has no technical or professional qualification, is employed there and gets a salary of ₹6 lakh. Assume the clubbing rule for a spouse's remuneration from a concern in which the individual has a substantial interest. In whose hands is the salary taxed?","options":["In Mr S's hands","In his wife's hands","Half in each person's hands","In the company's hands"],"answer":0,"explanation":"The remuneration of a spouse from a concern in which the individual has a substantial interest is clubbed with the individual's income, unless it is solely attributable to the spouse's technical or professional knowledge and experience.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-393","question":"Mr F transfers a house to his son's wife without adequate consideration. She lets it out and earns rent. Assume the clubbing provisions. Whose income is the rent?","options":["His son's","His daughter-in-law's","Mr F's","The family's, as an HUF"],"answer":2,"explanation":"Income from assets transferred without adequate consideration to the son's wife is clubbed in the transferor's (father-in-law's) hands, just as with transfers to one's own spouse.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-394","question":"An individual files his income-tax return after the due date (a belated return). He has a business loss and a loss from house property for the year. Which loss can he carry forward to later years?","options":["Only the business loss","Both losses","Neither loss","Only the house-property loss"],"answer":3,"explanation":"A business loss (and a capital loss) can be carried forward only if the return is filed within the due date. A house-property loss and unabsorbed depreciation are not subject to this condition.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-395","question":"Why is agricultural income, though exempt, considered when computing the tax of an individual who also has non-agricultural income above the exemption limit?","options":["Because it is taxed at a flat rate in such cases","Because the exemption lapses once total income crosses the limit","To determine the rate of tax on the non-agricultural income ('partial integration')","Because it is added to business income"],"answer":2,"explanation":"Under partial integration, net agricultural income is added only to fix the rate slab for non-agricultural income; the tax on agricultural income itself is then removed, so it stays exempt but pushes other income into higher slabs.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-396","question":"A 12-year-old child earns ₹60,000 from paintings he creates and sells himself. Assume the minor-clubbing rules. Is this income clubbed with his parent's income?","options":["Yes; all income of a minor child is clubbed","Yes, but only above ₹1,500","No, but only if the parent's income is lower","No; income from a minor's own skill, talent or specialised knowledge is not clubbed"],"answer":3,"explanation":"A minor's income is clubbed with the parent's income except income from manual work done by him or from any activity involving his skill, talent, specialised knowledge or experience.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-397","question":"A partner receives his share of the firm's profit plus salary and interest from the firm, as authorised by the partnership deed. How are these treated in his hands, assuming the firm is assessed as such?","options":["The profit share is exempt; salary and interest are taxed as business income","All three are taxed as business income","All three are exempt","Salary is taxed as 'Salaries' and the rest is exempt"],"answer":0,"explanation":"A partner's share of profit is exempt because the firm itself is taxed on it. Salary, bonus, commission and interest received from the firm are taxable as profits and gains of business or profession (to the extent the firm was allowed a deduction).","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-398","question":"Rent is received from letting out a vacant plot of land on which there is no building and which is not attached to any building. Under which head is it taxed (assume the landowner is not in the business of letting)?","options":["Income from house property","Income from other sources","Profits and gains of business","Capital gains"],"answer":1,"explanation":"House-property income covers buildings and land appurtenant to them. Rent from vacant land is not house-property income; unless it arises in a business, it falls under 'Other sources'.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-399","question":"A lender advances money to a trading firm on the terms that he will receive a share of its profits instead of fixed interest. He has no say in the business. Is he a partner?","options":["Yes; anyone who shares profits is a partner","Yes, but only for liability to outsiders","No; sharing of profits is not conclusive proof of partnership, and here there is no mutual agency","No, because a lender can never share profits"],"answer":2,"explanation":"Section 6 of the Partnership Act and Cox v Hickman: receiving a share of profits, for example as a lender, does not by itself make a person a partner. The real test is whether the business is carried on by all or any of them acting for all.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-400","question":"A firm's partnership deed is silent on interest. Partner A has contributed ₹5 lakh as capital and has also advanced ₹2 lakh to the firm as a loan. What interest is A entitled to under the Partnership Act?","options":["6% a year on ₹7 lakh","6% a year on the ₹2 lakh advance; nothing on capital","Nothing on either amount","Interest at the bank rate on the ₹2 lakh advance only"],"answer":1,"explanation":"Section 13: in the absence of agreement, no interest is payable on capital, but a partner who makes an advance beyond his agreed capital is entitled to interest at 6% a year on it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-401","question":"In a five-partner firm, three partners want to (i) change the firm's bankers and (ii) change the nature of the business from textile trading to real estate. The other two object. What is the legal position, absent any contrary agreement?","options":["Both can be decided by the majority","Both need the consent of all partners","(i) needs all partners; (ii) can be decided by the majority","(i) can be decided by the majority; (ii) needs the consent of all partners"],"answer":3,"explanation":"Section 12(c): differences over ordinary matters connected with the business may be decided by a majority, but no change in the nature of the business may be made without the consent of all partners.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-402","question":"Partner X retires. The remaining partners continue the business using the firm's assets without settling his accounts. In the absence of any contract, what is X entitled to besides his share in the firm's property?","options":["At his option, either the share of profits attributable to the use of his share of property, or interest at 6% a year on it","Only interest at the bank rate on his share","A share of all future profits for as long as the business continues","Nothing until the firm is dissolved"],"answer":0,"explanation":"Section 37: an outgoing partner (or his estate) is entitled, at his option, to the share of profits made since he ceased to be a partner that is attributable to the use of his share of the firm's property, or to interest at 6% a year on that share.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-403","question":"On dissolution, a firm's assets realise ₹1,00,000. Outside creditors are owed ₹60,000, and partner A has given the firm a loan of ₹20,000. Capitals are A ₹30,000 and B ₹10,000; profits and losses are shared equally, and both partners are solvent. How much does A receive in all?","options":["₹35,000","₹50,000","₹40,000","₹30,000"],"answer":2,"explanation":"Pay creditors 60,000, then A's loan 20,000, leaving 20,000 against capitals of 40,000: a capital loss of 20,000 shared equally. A bears 10,000 and gets 30,000 − 10,000 = 20,000 on capital; B bears 10,000 and gets nothing. A's total = 20,000 loan + 20,000 = ₹40,000.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-404","question":"Which of these is NOT a ground on which a court may order dissolution of a firm under Section 44 of the Partnership Act?","options":["The death of a partner","A partner has become permanently incapable of performing his duties","The business can be carried on only at a loss","A partner persistently breaches the partnership agreement"],"answer":0,"explanation":"Death of a partner dissolves a firm automatically under Section 42, subject to contract; it is not a ground for dissolution by the court. The other three are among the court's grounds under Section 44.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-405","question":"An LLP has two partners. One dies, and the survivor carries on the business alone for eight months, knowing he is the only partner. What is the position under the LLP Act, 2008?","options":["Nothing changes, because an LLP has perpetual succession","The LLP is automatically dissolved on the death","The survivor becomes liable for all LLP debts since its formation","For obligations incurred while it carried on with one partner for more than six months, the survivor is personally liable"],"answer":3,"explanation":"Section 6(2): if an LLP carries on business with fewer than two partners for more than six months, the person who is the only partner and knows it is personally liable for obligations incurred during that period.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-406","question":"A husband promises his wife a monthly allowance while he works abroad. Later he stops paying, and she sues on the promise. What is the likely result?","options":["She fails, because domestic arrangements between spouses are presumed not to be intended to create legal relations","She succeeds, because there was consideration in the form of her staying at home","She succeeds, because any promise made in writing is binding","She fails, because spouses cannot contract with each other at all"],"answer":0,"explanation":"In social and domestic agreements the law presumes no intention to create legal obligations (Balfour v Balfour), so no enforceable contract arises unless that presumption is rebutted. Spouses can, however, make binding contracts when they intend to.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-407","question":"A railway invites tenders, and S's tender to supply coal 'as and when ordered, up to 5,000 tonnes over a year' is accepted. After supplying three orders, S refuses to supply any more. Which statement is correct?","options":["A binding contract for the full 5,000 tonnes arose when the tender was accepted","No contract ever arose, so S need not fulfil even the orders already placed","S cannot revoke because the railway invited the tenders","S's tender was a standing offer; each order is a separate acceptance, so S must fulfil orders already placed but may revoke the offer for future orders"],"answer":3,"explanation":"A tender to supply goods as and when required is a standing offer. Each order made under it is an acceptance creating a separate contract (Great Northern Railway v Witham). The offer can be withdrawn for the future, but orders already placed are binding.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-408","question":"A writes to B offering to sell his car for ₹4 lakh. On the same day, without knowing of A's letter, B writes to A offering to buy the same car for ₹4 lakh. The letters cross in the post. Is there a contract?","options":["Yes, because the parties agree on all terms","No; identical cross offers do not make a contract because neither is an acceptance of the other","Yes, once the second letter is received","No, because the price was not negotiated"],"answer":1,"explanation":"Acceptance must be made in response to an offer with knowledge of it. Cross offers, even identical ones, are two offers, not offer and acceptance (Tinn v Hoffman). Either party could now accept the other's offer.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-409","question":"The managers of a school decide to appoint P as headmaster but do not tell him. One manager, acting without the board's authority, privately informs P. The board later changes its mind. Can P enforce the appointment?","options":["Yes; P learnt of the decision from a manager","Yes; the board's resolution itself was the acceptance","No; acceptance must be communicated by the offeree or someone authorised by him, which did not happen","No, because an appointment can never be a contract"],"answer":2,"explanation":"In Powell v Lee, information given by an unauthorised person was held not to be communication of acceptance. A mere internal decision does not conclude a contract.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-410","question":"A, of full age and free will, agrees to sell a house worth ₹80 lakh to B for ₹10 lakh. Later A says the agreement is void for inadequate consideration. Is he right?","options":["Yes; consideration must be roughly equal in value","No; inadequacy of consideration does not invalidate an agreement freely made, though it may be evidence on whether consent was free","Yes; the agreement is voidable because the price is unfair","No, but the court will increase the price to the market value"],"answer":1,"explanation":"Explanation 2 to Section 25: an agreement to which consent is freely given is not void merely because the consideration is inadequate; the inadequacy may be considered in deciding whether consent was freely given.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-411","question":"A rogue, posing as a reputable firm R & Co by mimicking its name in letters, orders goods from S by post; S sends them, believing he is dealing with R & Co. In another case, a rogue in S's shop falsely says he is a famous person and S, dealing face to face, lets him take goods on credit. What is the status of the two contracts?","options":["The postal one is void for mistake as to identity; the face-to-face one is voidable for fraud","Both are void for mistake as to identity","Both are voidable for fraud","The postal one is voidable; the face-to-face one is void"],"answer":0,"explanation":"Where the identity of the other party is vital and the seller intends to deal only with the named firm, there is no agreement (Cundy v Lindsay). Face to face, the seller is presumed to intend to deal with the person in front of him, so the contract is only voidable for fraud (Phillips v Brooks).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-412","question":"A lends money to B so that B can pay off a debt that B lost on a wager. B refuses to repay A. In most of India, can A recover the loan?","options":["No; any loan connected with a wager is void","No; the loan is illegal and A is guilty of abetment","Yes; a transaction collateral to a wagering agreement is not void, since wagers are void but not illegal","Yes, but only if B won the wager"],"answer":2,"explanation":"A wagering agreement is void under Section 30 but not illegal (except where a State law makes it so, as in Maharashtra and Gujarat). Collateral transactions, such as a loan to pay a wagering debt, are therefore enforceable (Gherulal Parakh v Mahadeodas).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-413","question":"A promises to pay B ₹1 lakh if a certain ship returns within a year. The ship returns after 14 months. What is the status of the promise?","options":["It is enforceable now that the ship has returned","It is enforceable for a proportionate amount","It becomes void only if the ship never returns","It is void, because the event did not happen within the fixed time"],"answer":3,"explanation":"Section 35: a contingent contract to do something if an event happens within a fixed time becomes void if, when that time expires, the event has not happened. The later return does not revive it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-414","question":"A owes B ₹10,000 under a contract. On the due date, A brings exactly ₹10,000 in cash to B's office at the agreed time, but B refuses to accept it. What is the effect?","options":["The debt is extinguished entirely","A is not responsible for non-performance, but the debt is not extinguished; A need not tender again and may simply pay when asked","A becomes liable to pay interest for the delay","B can sue A immediately for breach"],"answer":1,"explanation":"Section 38: a valid offer of performance that is refused means the promisor is not responsible for non-performance and does not lose his rights. For a money debt the obligation to pay remains, but no interest or damages for delay run against A.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-415","question":"A agrees to paint a portrait of B for ₹50,000, and C agrees to pay D ₹50,000 for a used car on delivery. Both A and C die before performing. What is the position?","options":["A's contract ends on his death because it depends on his personal skill; C's legal representatives must perform C's promise","Both contracts end on death","Both promises bind the legal representatives","A's legal representatives must finish the portrait using another painter"],"answer":0,"explanation":"Section 37 binds the promisor's representatives on his death unless a contrary intention appears from the contract. A portrait involves personal skill, so it ends with the painter (Section 40); paying money does not.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-416","question":"A owes B ₹50,000. C, without A's request, pays B the full amount, and B accepts it in full satisfaction. Later B sues A for the debt. What is the result?","options":["B succeeds, because C was a stranger to the contract","B succeeds, but must refund C","B fails only if A later ratifies C's payment","B fails, because he accepted performance from a third person"],"answer":3,"explanation":"Section 41: when a promisee accepts performance of the promise from a third person, he cannot afterwards enforce it against the promisor.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-417","question":"A, B and C jointly promise to pay D ₹3 lakh. D releases A from the promise by an agreement with him alone. What is the effect on B and C?","options":["They are discharged because the joint promise has been broken up","They are each liable only for ₹1 lakh","They are not discharged; D can still claim from them, though A's release does not free him from his duty to contribute to B and C","They are discharged unless they consented to the release"],"answer":2,"explanation":"Section 44: where one of joint promisors is released by the promisee, the others are not discharged, and the released promisor is not freed from responsibility to the other joint promisors.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-418","question":"A agrees to whitewash B's house for ₹20,000. B keeps the house locked and refuses to let A in. What is A's position?","options":["A must keep tendering performance until B allows access","A has no remedy because the work was not done","The contract is voidable at A's option, and A may claim compensation for loss caused by B's prevention","The contract is void for impossibility"],"answer":2,"explanation":"Section 53: when one party prevents the other from performing a reciprocal promise, the contract becomes voidable at the option of the party prevented, who can recover compensation for any loss caused.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-419","question":"A shipping company had five trawlers but licences for only three. It chose to allot the licences to three other trawlers, leaving the chartered one unlicensed, and then claimed that the charter was frustrated. Is it right?","options":["Yes; the licensing rule made performance impossible","Yes; any supervening government restriction frustrates a contract","No; frustration can never arise from government action","No; frustration cannot be pleaded when the impossibility results from the party's own choice"],"answer":3,"explanation":"Self-induced impossibility is not frustration (Maritime National Fish v Ocean Trawlers). The company itself chose which vessels to license, so the impossibility was of its own making and it remained liable.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-420","question":"A builder contracts to construct a hall for a fixed price. Because of sharp increases in cement and steel prices, the project now costs 40% more than expected. Can the builder treat the contract as frustrated?","options":["No; a rise in cost or commercial hardship does not make performance impossible","Yes; any unforeseen event making performance costlier frustrates the contract","Yes, if the cost increase is more than 25%","No, but the court must raise the contract price"],"answer":0,"explanation":"Section 56 covers performance becoming impossible or unlawful, or the commercial purpose being destroyed. Mere hardship, increased expense or market changes do not discharge a contract (e.g. Satyabrata Ghose v Mugneeram Bangur).","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-421","question":"A owes B ₹5,000. B accepts ₹2,000 at A's request in full satisfaction of the whole debt, and nothing else is given. Can B later sue for the remaining ₹3,000?","options":["Yes; part payment can never discharge a larger debt","No; under Section 63 a promisee may accept any satisfaction he thinks fit, so the debt is discharged","Yes, because there was no fresh consideration for giving up ₹3,000","No, but only if the agreement was registered"],"answer":1,"explanation":"Section 63 allows the promisee to remit wholly or partly the performance, or to accept any satisfaction he thinks fit. Illustration (b) to the section is exactly this case; Indian law does not follow the English rule in Pinnel's case.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-422","question":"B rescinds a contract with A because A obtained his consent by fraud. B had earlier received ₹1 lakh from A under that contract. What must B do?","options":["Keep the ₹1 lakh as damages for the fraud","Restore the ₹1 lakh (the benefit received) to A","Keep the ₹1 lakh because fraud makes the contract void from the start","Pay A double the amount as a penalty"],"answer":1,"explanation":"Section 64: when a person at whose option a contract is voidable rescinds it, he must restore any benefit received under it to the person from whom it was received. B may separately claim compensation for loss caused by the fraud.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-423","question":"A agrees to sing at B's theatre on two nights each week for three months and also agrees not to sing at any other theatre during that period. She breaks both promises. What remedy will a court most likely grant B?","options":["An injunction stopping her from singing elsewhere during the period, plus damages; but not an order compelling her to sing for B","Specific performance compelling her to sing for B","Only nominal damages because personal service cannot be enforced","An injunction compelling her to sing for B"],"answer":0,"explanation":"Courts will not order specific performance of personal services, but they may enforce an express negative covenant by injunction (Lumley v Wagner), leaving B also free to claim damages.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-424","question":"A seller agrees to sell a horse 'at a price to be fixed by valuer X'. X refuses to value it, and the horse has not been delivered. What is the legal position?","options":["The court will fix a reasonable price and enforce the sale","The seller may choose any other valuer","The agreement is avoided; had the buyer received and used the horse, he would have to pay a reasonable price","The buyer must pay the market price immediately"],"answer":2,"explanation":"Section 10 of the Sale of Goods Act: if the third party cannot or does not fix the price, the agreement is avoided, but a buyer who has received and appropriated the goods must pay a reasonable price for them.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-425","question":"A buyer bought a machine described as 'new, 2025 model'. It turns out to be a reconditioned 2023 model, though it works well. Which statement is correct?","options":["There is no breach because the machine is of merchantable quality","There is only a breach of warranty, so the buyer can only claim damages","Caveat emptor applies, so the buyer has no remedy","There is a breach of the implied condition that goods correspond with their description, so the buyer may reject them"],"answer":3,"explanation":"Section 15: where goods are sold by description, there is an implied condition that they correspond with the description. Words such as 'new, 2025 model' identify the goods, so a reconditioned older model breaches a condition, whatever its working order.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-426","question":"A buyer examines a second-hand car before buying it from a dealer but overlooks an obvious large dent in the door. Later she claims the car was not of merchantable quality because of the dent. Will she succeed?","options":["Yes; a dealer always guarantees merchantable quality","Yes; examination does not affect implied conditions","No; the implied condition of merchantable quality does not cover defects that the examination ought to have revealed","No; second-hand goods carry no implied conditions at all"],"answer":2,"explanation":"The proviso to Section 16(2) says that if the buyer has examined the goods, there is no implied condition as to defects that such examination ought to have revealed. Hidden defects would still be covered.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-427","question":"A contract of sale says nothing about delivery. The goods are ready at the seller's warehouse, and the buyer has not asked for them. What does the Sale of Goods Act say about the seller's duty?","options":["The seller must send the goods to the buyer's place at his own cost","The seller must deliver within seven days of the contract","The seller is discharged if the buyer does not collect within a month","The seller is not bound to deliver until the buyer applies for delivery"],"answer":3,"explanation":"Section 35: apart from any express contract, the seller of goods is not bound to deliver them until the buyer applies for delivery. Section 36 adds that, absent agreement, the place of delivery is where the goods are at the time of sale.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-428","question":"A buyer finds that the goods breach a condition of the contract but decides to keep them. What may he do?","options":["Keep the goods and refuse to pay any price","Waive the condition, or treat the breach as a breach of warranty and claim damages","Keep the goods and also rescind the contract","Nothing, because a breach of condition must lead to rejection"],"answer":1,"explanation":"Section 13(1): where a contract is subject to a condition to be fulfilled by the seller, the buyer may waive the condition or elect to treat the breach as a breach of warranty, which gives a claim for damages rather than rejection.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-429","question":"A makes a promissory note in favour of B without any consideration, purely as a favour, so that B can raise money. B endorses it for value to C, who knows that it was an accommodation note. Can C recover from A at maturity?","options":["Yes; the absence of consideration between A and B is no defence against a holder for value, even one who knew of the accommodation","No; the note has no consideration and creates no obligation","No; C knew that A received nothing","Yes, but only half the amount"],"answer":0,"explanation":"Section 43 makes a note without consideration unenforceable between the original parties, but if it is negotiated to a holder for consideration, he may recover from any prior party. The accommodation party lends his name and is liable to the holder for value.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-430","question":"A bill of exchange payable '30 days after sight' is presented and accepted on 1 March. Allowing three days of grace and assuming no holidays intervene, on what date is it payable?","options":["31 March","4 April","3 April","2 April"],"answer":2,"explanation":"In counting days after sight, the day of sight is excluded (Section 23), so 30 days runs to 31 March. Adding three days of grace (Section 22) gives 3 April. Instruments payable on demand or at sight get no grace.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-431","question":"A minor endorses a bill of exchange to C for value. The bill is dishonoured at maturity. Against whom can C proceed?","options":["Against no one, because the minor's endorsement is void","Against all parties to the bill other than the minor","Only against the minor","Only against the drawee"],"answer":1,"explanation":"Section 26: a minor may draw, endorse, deliver and negotiate an instrument so as to bind all parties except himself. The minor's endorsement passes title, so the other parties remain liable to C.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-432","question":"A foreign bill of exchange is dishonoured by non-payment. Which step is legally required for it?","options":["It needs no notice of dishonour because it is foreign","Only noting is required; protest is never needed","It must be re-drawn as an inland bill","It must be protested for dishonour, where the law of the place where it was drawn requires protest"],"answer":3,"explanation":"Section 104 requires foreign bills of exchange to be protested for dishonour when such protest is required by the law of the place where they are drawn. For inland instruments, noting and protest are optional.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-433","question":"A bill drawn by A on B in favour of C is dishonoured by non-payment. To whom must C give notice of dishonour in order to make them liable?","options":["To all parties whom he wants to make liable, such as the drawer and prior endorsers; not to the acceptor B","Only to the acceptor B","Only to the drawer A","To nobody; dishonour itself makes everyone liable"],"answer":0,"explanation":"Section 93: notice of dishonour must be given to all other parties whom the holder seeks to make liable. The acceptor is primarily liable and needs no notice; a party not given notice is discharged (subject to Section 98).","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-434","question":"A seller paints over cracks in a ship's hull before a prospective buyer inspects it. The buyer, seeing no defect, buys the ship. What is the status of the contract?","options":["Voidable at the buyer's option for fraud, because active concealment of a fact is fraud","Valid, because the buyer inspected and caveat emptor applies","Void for mutual mistake","Voidable only if the seller made a false oral statement as well"],"answer":0,"explanation":"Section 17 includes the active concealment of a fact by one having knowledge or belief of it. Hiding defects so that inspection cannot reveal them is fraud, so caveat emptor gives the seller no protection.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-435","question":"A sends a letter offering to sell goods 'subject to a formal contract to be signed by both of us'. B replies 'I accept'. Before any formal contract is signed, A withdraws. Can B enforce the deal?","options":["Yes; B's unconditional acceptance concluded the contract","Yes, because A's withdrawal came after acceptance","No; the words show that the parties did not intend to be bound until the formal contract was signed","No, but B can recover damages for wasted expenses as of right"],"answer":2,"explanation":"Where an agreement is expressly 'subject to contract', the courts generally treat it as not binding until the formal contract is executed, because the parties have shown they do not intend to be bound before that.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-436","question":"A dealer sells a new laptop whose open market value is ₹50,000. The customer pays ₹40,000 in cash and hands over his old laptop, valued at ₹10,000, in exchange. The buyer is not related to the dealer. What is the value of supply of the new laptop for GST?","options":["₹40,000","₹50,000","₹60,000","₹30,000"],"answer":1,"explanation":"Where consideration is partly non-monetary, the value is the open market value, or else money plus the money value of the non-monetary part: ₹40,000 + ₹10,000 = ₹50,000. Taking only the cash (₹40,000) ignores the exchanged goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-437","question":"A supplier's invoice for goods worth ₹2,00,000 is paid late, and it charges the buyer ₹2,000 as interest for delayed payment. GST on the goods is 18% (assume). What is the GST position of the interest?","options":["The interest is a financial service exempt from GST","The interest is outside GST because it is compensation, not consideration","The ₹2,000 is added to the value of the supply and GST of ₹360 is payable on it","GST is payable on it at the rate for financial services, not 18%"],"answer":2,"explanation":"Section 15(2)(d) includes interest, late fee or penalty for delayed payment of consideration in the value of supply, so it takes the rate of the main supply: 18% × 2,000 = ₹360.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-438","question":"A retailer runs a 'buy one shirt, get one shirt free' offer and charges ₹1,000 for the pair. Which statement reflects the GST position?","options":["Both shirts are supplied for ₹1,000; the 'free' shirt is not a free supply, and input tax credit on it is not blocked","The free shirt is a gift, so its input tax credit must be reversed","GST is payable on ₹2,000, the full value of both shirts","The free shirt is a deemed supply taxable at its open market value"],"answer":0,"explanation":"The government has clarified that a 'buy one get one free' offer is not an individual free supply: the price paid is for both items, so tax is on ₹1,000 and credit on the inputs remains available.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-439","question":"A supplier of goods (not under the composition scheme) receives an advance of ₹1,00,000 in June for goods to be supplied and invoiced in August. When is GST payable on the advance?","options":["On the advance in June, adjusted against the August invoice","Half in June and half in August","Only when the balance payment is received","Not on receipt of the advance; GST on the goods is payable on the invoice in August"],"answer":3,"explanation":"For goods, payment is no longer a trigger for the time of supply for normal taxpayers, as notified by the government; tax arises on the invoice (or the due date for issuing it). For services, an advance does attract GST.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-440","question":"A manufacturer registered in Gujarat sends a machine to a repairer registered in Maharashtra; the repairer fixes it in its Pune workshop and returns it. The manufacturer is the recipient. What is the place of supply of the repair service and which tax applies?","options":["Gujarat, the registered recipient's location; IGST","Maharashtra, where the repair is performed; CGST + SGST","Maharashtra, where the machine was physically available; IGST","Gujarat, because the machine belongs there; CGST + SGST of Gujarat"],"answer":0,"explanation":"For domestic supplies, Section 12 of the IGST Act has no 'performance on goods' rule; repair services to a registered person fall under the general rule – the recipient's location. The repairer is in Maharashtra and the recipient in Gujarat, so IGST applies.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-441","question":"A company has units registered in three states under one PAN. Its head office in Mumbai receives invoices for audit and advertising services that benefit all units. How can the credit of the tax on these common services reach the other units?","options":["The Mumbai unit simply transfers its electronic credit ledger balance","Each unit claims credit directly on the head office's invoices","Through an Input Service Distributor registration that distributes the credit to the units","It cannot; the credit stays with the Mumbai unit"],"answer":2,"explanation":"An Input Service Distributor receives invoices for input services used by distinct persons with the same PAN and distributes the credit to them by issuing ISD invoices. Credit ledger balances cannot simply be transferred between GSTINs.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-442","question":"A manufacturer sends inputs directly from its supplier's premises to a job worker for processing, without first bringing them into its own factory. Can it take input tax credit on these inputs?","options":["No; inputs must first be received in the principal's factory","Yes; credit is available even when inputs are sent directly to a job worker","Only after the processed goods return from the job worker","Only the job worker can take the credit"],"answer":1,"explanation":"Under the job-work provisions, the principal may take credit on inputs sent to a job worker, including inputs supplied directly to the job worker without coming to the principal's premises, subject to the return conditions.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-443","question":"A refinery lays a pipeline outside its factory premises to bring crude from a nearby port. Is input tax credit available on goods and services used for constructing this pipeline?","options":["Yes; pipelines are always plant and machinery","Yes, because the pipeline is used for business","Only 50% of the credit is available","No; pipelines laid outside the factory are excluded from 'plant and machinery', so credit on construction of this immovable property is blocked"],"answer":3,"explanation":"The Explanation to Section 17 defines plant and machinery to exclude land, buildings, civil structures, telecommunication towers and pipelines laid outside the factory premises. Construction of such immovable property is blocked under Section 17(5)(c)/(d).","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-444","question":"Mr N is a non-resident this year. His UK employer pays his salary for work done in the UK by crediting it directly to his savings account in a bank in India. Is the salary taxable in India?","options":["No; a non-resident is taxed only on income earned in India","Yes; income received in India is taxable even in a non-resident's hands","No; salary for services abroad is never taxable in India","Yes, but only half of it"],"answer":1,"explanation":"A non-resident is taxed on income that is received (or deemed received) in India, or that accrues or arises (or is deemed to) in India. Salary first received in an Indian bank account is received in India, wherever the work was done.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-445","question":"Ms D, now resident and ordinarily resident, remits to India this year the savings from salary she earned and spent abroad over several earlier years when she was non-resident (that salary was not taxable in India then). Is the remittance taxable this year?","options":["Yes; all money received in India by a resident is taxable","Yes, because she is now ordinarily resident","No; a mere remittance of past income is not income of this year","Only the part remitted through banking channels is taxable"],"answer":2,"explanation":"Income is taxed in the year it is earned or first received. Transferring past savings into India is a remittance of capital, not a fresh receipt of income, so it is not taxed again.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-446","question":"Under the current income-tax rules, can a business claim depreciation on goodwill that it acquired when it bought another business?","options":["Yes, as part of the block of intangible assets","Yes, but only on the price actually paid","Only if the goodwill was acquired from a related party","No; goodwill of a business is not treated as a depreciable asset"],"answer":3,"explanation":"Goodwill of a business or profession has been excluded from depreciable intangible assets, so no depreciation is allowed on it, though its cost is relevant when it is later transferred.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-447","question":"A company borrows money specifically to buy a new machine. Interest for the period before the machine is first put to use is ₹2 lakh. How is it treated?","options":["It is added to the actual cost of the machine and recovered through depreciation, not deducted as a business expense","It is fully deductible as interest in the year paid","It is disallowed altogether","It is deductible in five equal instalments"],"answer":0,"explanation":"Interest on capital borrowed for acquiring an asset, for any period before the asset is first put to use, is not allowed as a revenue deduction and is capitalised in the asset's actual cost. Interest after it is put to use is deductible.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-448","question":"A trader sells listed shares held for 8 months (assume the gain is short-term) for ₹5,00,000 and pays 1% brokerage on the sale. He bought them for ₹3,00,000, with brokerage of ₹3,000 on purchase. What is the short-term capital gain?","options":["₹1,92,000","₹2,00,000","₹1,95,000","₹1,97,000"],"answer":0,"explanation":"Full value ₹5,00,000 − transfer expenses ₹5,000 − cost of acquisition ₹3,03,000 (purchase brokerage forms part of cost) = ₹1,92,000. Ignoring both brokerages gives ₹2,00,000; ignoring only the purchase brokerage gives ₹1,95,000.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-449","question":"Assume clubbing rules apply to income from assets transferred to a spouse without adequate consideration, but not to income from the accretion of such income. Mr X gifts ₹20 lakh to his wife; she earns ₹1.6 lakh interest on it this year and reinvests that interest, earning ₹10,000 more. How much is clubbed in Mr X's income?","options":["₹1,70,000","₹10,000","Nil","₹1,60,000"],"answer":3,"explanation":"Income from the transferred asset itself (₹1,60,000) is clubbed with the transferor's income. Income earned on the reinvested interest is income from an accretion, which belongs to the wife.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-450","question":"Which of these is a revenue expenditure allowed as a business deduction (assuming it is laid out wholly for the business)?","options":["Buying a new machine to expand capacity","Replacing worn-out parts of a machine to restore it to working order","Paying income tax on business profits","Paying a penalty for breaking a law"],"answer":1,"explanation":"Current repairs that restore an asset without creating a new one are revenue in nature. A new machine is capital expenditure (depreciation only); income tax is not a business expense; penalties for infringing the law are expressly disallowed.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-451","question":"A company's directors, acting within the company's objects but beyond the powers given to them by the articles, buy a building. What can be done about the transaction?","options":["Nothing; it is void and cannot be ratified","Only the Tribunal can validate it","The shareholders in general meeting can ratify it, because it is within the company's capacity","The company is bound only if all creditors consent"],"answer":2,"explanation":"An act ultra vires the directors but intra vires the company can be ratified by the members. Only acts beyond the company's own objects are incapable of ratification (Ashbury Railway Carriage v Riche).","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-452","question":"Which of these may a company issue at a discount to its face value under the Companies Act, 2013?","options":["Equity shares in a public issue","Bonus shares","Sweat equity shares","Preference shares in a rights issue"],"answer":2,"explanation":"Section 53 prohibits issuing shares at a discount except sweat equity shares issued under Section 54 (and certain shares issued to creditors on conversion of debt under a statutory scheme). Bonus shares are fully paid without any payment, not 'at a discount'.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-453","question":"A company makes a private placement of shares. Which statement is correct?","options":["It must not release any public advertisement or use marketing channels to inform the public at large about the offer","It may advertise the offer in newspapers like a public issue","It may invite applications from anyone who responds","It needs no special resolution or offer letter"],"answer":0,"explanation":"Section 42 requires private placement to be made through a private placement offer letter to identified persons, approved by special resolution; the company must not release public advertisements or use media or marketing channels to inform the public of the offer.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-454","question":"A listed company's remuneration committee proposes to grant stock options to all its directors, including its independent directors. Is this permitted?","options":["Yes, with a special resolution","Yes, if the options are capped at 1% of share capital","No; no director can ever receive stock options","No; an independent director is not entitled to any stock option"],"answer":3,"explanation":"Section 149(9) says an independent director shall not be entitled to any stock option. He may receive sitting fees, reimbursement of expenses and profit-related commission as approved by members. Executive directors can receive options.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-455","question":"Which of these is a 'related party' of Company X under the Companies Act, 2013?","options":["A partnership firm in which a director of Company X is a partner","A customer that buys more than 20% of Company X's output","Company X's largest unsecured creditor","An unrelated firm that supplies goods to Company X at market prices"],"answer":0,"explanation":"Section 2(76) lists, among others, a director or KMP and their relatives, a firm in which a director, manager or his relative is a partner, and certain companies with common directors or members. Economic dependence alone, such as a large customer or creditor, does not create a related party.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-456","question":"Which listed company must have at least one woman director on its board under the Companies Act, 2013?","options":["Only listed companies with paid-up capital above ₹1,000 crore","Every listed company","Only government companies","None; it is only a recommendation"],"answer":1,"explanation":"The second proviso to Section 149(1) requires such class of companies as may be prescribed to have at least one woman director, and the rules prescribe every listed company (and certain large public companies).","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-457","question":"A manufacturer took input tax credit of ₹1,00,000 on a machine. After 10 quarters of use it sells the machine for ₹2,00,000 plus GST at 18% (assume). Assume the rule that on removal of used capital goods the supplier pays the higher of (a) the credit taken reduced by 5 percentage points per quarter of use and (b) the tax on the transaction value. How much must it pay?","options":["₹36,000","₹86,000","₹50,000","₹64,000"],"answer":2,"explanation":"(a) Credit reduced by 5% × 10 quarters = 50%: ₹1,00,000 × 50% = ₹50,000. (b) Tax on transaction value = 18% × 2,00,000 = ₹36,000. The higher, ₹50,000, is payable. Adding the two (₹86,000) double-counts.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-458","question":"Which of these supplies is outside the levy of GST altogether under the Constitution and the GST laws, not merely exempt by notification?","options":["Fresh vegetables","Healthcare services by a hospital","Education services by a school","Alcoholic liquor for human consumption"],"answer":3,"explanation":"Article 366(12A) defines GST to exclude the supply of alcoholic liquor for human consumption, so States continue to tax it under their own laws. Fresh vegetables, healthcare and school education are within GST but exempted by notification.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-459","question":"For petroleum crude, high-speed diesel, motor spirit (petrol), natural gas and aviation turbine fuel, what is the constitutional and statutory position under GST?","options":["They are within the GST framework, but GST is levied on them only from a date to be notified on the GST Council's recommendation; until then the earlier taxes continue","They are permanently outside GST under the Constitution","They are taxed under GST at a special rate of 28%","They are exempt from all taxes"],"answer":0,"explanation":"The Constitution and Section 9(2) of the CGST Act keep these five products within GST's scope but defer the levy to a date the government notifies on the Council's recommendation. Meanwhile, central excise and State VAT apply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-460","question":"GST is described as a destination-based consumption tax. On an inter-state sale of goods from Gujarat to a consumer in Punjab, which State ultimately gets the State share of the tax?","options":["Gujarat, the producing State","Punjab, the consuming State, through settlement of the IGST","Both States equally","Neither; inter-state tax goes wholly to the Centre"],"answer":1,"explanation":"IGST is levied by the Centre on inter-state supplies, and the State share is apportioned to the State where the goods are consumed (the place of supply). This is the destination principle.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-461","question":"A coaching firm registered in Delhi sells an online course to an unregistered individual whose address is not on its records. What is the place of supply under the general rule?","options":["Delhi, the location of the supplier","The location of the server hosting the course","The State where the student is physically present while studying","Wherever the payment is made from"],"answer":0,"explanation":"Under Section 12(2) of the IGST Act, for services to an unregistered person, the place of supply is the recipient's location if the address is on record, and otherwise the supplier's location. So the supply is intra-state in Delhi.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-462","question":"Assume an individual may treat at most two house properties as self-occupied (annual value nil), and any other house he occupies is 'deemed let out' at its expected rent. Mr A owns four houses, all used by his family and none let out. How is his house-property income computed?","options":["All four houses have nil annual value","Only one house can be self-occupied; three are deemed let out","Two houses of his choice are treated as self-occupied; the other two are taxed on their expected (notional) rent","All four are taxed on expected rent because he owns more than two"],"answer":2,"explanation":"Under the stated rule, he chooses two houses as self-occupied (nil annual value). The remaining two are deemed let out and taxed on their annual value, even though no rent is received. He would choose so as to minimise tax.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-463","question":"Which of these is deductible as 'interest on borrowed capital' when computing income from a let-out house, assuming the loan was taken to buy the house?","options":["Interest on interest that was unpaid and added to the loan","Interest payable on the housing loan for the year","Brokerage paid to arrange the loan","Principal repayment of the loan"],"answer":1,"explanation":"Only interest on capital borrowed for acquiring, constructing or repairing the property is deductible. Interest on unpaid interest, brokerage or commission for arranging the loan, and principal repayments are not deductible under this head.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-464","question":"Mr B's land was compulsorily acquired by the government three years ago, but he received the compensation only this year. In which year is the capital gain taxable?","options":["The year of acquisition","Spread equally over the three years","It is exempt because the transfer was compulsory","This year, the year in which the compensation is first received"],"answer":3,"explanation":"For compulsory acquisition, the capital gain is charged in the year in which the compensation, or part of it, is first received. Enhanced compensation is taxed in the year it is received.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-465","question":"A partner introduces his land into his firm as his capital contribution. Its market value is ₹90 lakh, but the firm records it in its books at ₹60 lakh. Assume the special rule for transfer of capital assets by a partner to a firm. What is the full value of consideration for computing the partner's capital gain?","options":["₹90 lakh, the market value","Nil, because no money is received","The average of ₹60 lakh and ₹90 lakh","₹60 lakh, the amount recorded in the firm's books"],"answer":3,"explanation":"When a partner transfers a capital asset to a firm by way of capital contribution, the amount recorded in the firm's books is deemed to be the full value of the consideration. Market value is not substituted under this specific rule.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-466","question":"A taxpayer receives a refund of excess income tax paid along with interest on the refund. How are the two treated?","options":["Both are taxable as other sources","The refund itself is not income, but the interest on it is taxable under 'Income from other sources'","Neither is taxable","Both are taxable as business income"],"answer":1,"explanation":"A refund merely returns tax paid out of income that was already taxed, so it is not income. Interest received on the refund is a fresh receipt and is taxed under 'Other sources'.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-467","question":"An individual's gross total income consists only of a short-term capital gain on listed equity shares taxed at a special rate and winnings from a lottery. He has made investments that would normally qualify for deductions from gross total income. Assume the usual rule on such deductions. What is the position?","options":["The deductions reduce the capital gain but not the lottery winnings","The deductions reduce both incomes","The deductions cannot be set against these special-rate incomes, so they are effectively lost","The deductions are carried forward to the next year"],"answer":2,"explanation":"The usual deductions from gross total income are not allowed against specified special-rate incomes such as short-term gains on listed equity taxed at the special rate, long-term capital gains and casual winnings. Unused deductions are not carried forward.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-468","question":"A partnership firm pays salary to a partner who does not work in the business (a 'sleeping partner'), as the partnership deed provides. Assume the usual rules for firms. Can the firm deduct it?","options":["No; only remuneration to working partners, as authorised by the deed and within limits, is deductible","Yes, because the deed authorises it","Yes, but only half of it","No, but the partner need not pay tax on it either"],"answer":0,"explanation":"A firm can deduct salary, bonus or commission only if paid to a working partner, authorised by the deed and within the prescribed limits. Remuneration to a non-working partner is disallowed in the firm's hands.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-469","question":"A company raised money from the public through a prospectus, and some of it is still unutilised. It now wants to change the objects for which the money was raised. What does the Companies Act, 2013 require?","options":["Only a board resolution","An ordinary resolution at the next AGM","A special resolution passed by postal ballot, publication of the details, and an exit offer to dissenting shareholders","Approval of the Tribunal only"],"answer":2,"explanation":"Section 13(8) (and Section 27 for prospectus terms) requires a special resolution by postal ballot, publication of the justification, and an exit opportunity for dissenting shareholders as per SEBI rules when unutilised issue money is to be used for changed objects.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-470","question":"A newly registered company's name closely resembles that of an existing company. On the earlier company's application, what can the Central Government do?","options":["Strike the new company off the register immediately","Direct the new company to change its name within the prescribed time","Merge the two companies","Nothing, once the certificate of incorporation is issued"],"answer":1,"explanation":"Section 16 empowers the Central Government (on its own or on application) to direct a company registered with a name identical with or too nearly resembling an existing company's name to rectify its name, and the company must change it by ordinary resolution.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-471","question":"Which statement about the audit committee of a listed company under Section 177 of the Companies Act, 2013 is correct?","options":["It must have at least three directors, with independent directors forming a majority","It must consist only of executive directors","It must be chaired by the managing director","It needs only two members, both of whom may be non-independent"],"answer":0,"explanation":"Section 177(2) requires a minimum of three directors with independent directors forming a majority, and a majority of members, including the chairperson, must be able to read and understand financial statements.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-472","question":"A director sends his resignation to the company on 10 June, stating that it is effective from 30 June. The company receives it on 12 June. From when is the resignation effective?","options":["10 June, the date of the letter","12 June, the date of receipt","Only after the board accepts it","30 June, the later of the date of receipt and the date specified"],"answer":3,"explanation":"Section 168(2): a resignation takes effect from the date on which the notice is received by the company or the date, if any, specified by the director in the notice, whichever is later. Board acceptance is not needed.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-473","question":"In a public company, a director appointed by the general meeting dies in the middle of his term. How is the casual vacancy filled, assuming the articles do not provide otherwise?","options":["Only by the general meeting","By the board, and the new director holds office only until the date the original director's term would have ended","By the Tribunal on application by the company","By the board, for a fresh full term"],"answer":1,"explanation":"Section 161(4): a casual vacancy in the office of a director appointed by the general meeting of a public company may be filled by the board at a board meeting, and the person appointed holds office only up to the date the original director would have held office.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-474","question":"A company incorporated two years ago wants to contribute to a political party. Is it allowed under the Companies Act, 2013?","options":["No; a company in existence for less than three financial years cannot make political contributions","Yes, if the board approves","Yes, up to any amount with shareholders' approval","No; no company may ever make political contributions"],"answer":0,"explanation":"Section 182 bars a government company and any other company that has been in existence for less than three financial years from making political contributions. Other companies may contribute within the conditions set by the section.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-475","question":"A principal dies. Before learning of the death, his agent sells the principal's goods to a buyer who also knows nothing of the death. Is the sale binding on the principal's estate?","options":["No; an agency ends automatically at the moment of the principal's death","Yes, but only if the legal heirs ratify it","No, but the agent is personally liable to the buyer","Yes; termination of authority takes effect for the agent and for third persons only when they come to know of it"],"answer":3,"explanation":"Section 208: termination of the agent's authority does not take effect as regards the agent before it becomes known to him, or as regards third persons before it becomes known to them. Both acted in ignorance, so the sale binds the estate.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-476","question":"A friend keeps B's bicycle for free while B is away. Through his carelessness – leaving it unlocked on the street – it is stolen. Is the friend liable to B under the Indian Contract Act?","options":["No; a gratuitous bailee is liable only for gross negligence","No; there is no contract because no consideration passed","Yes; every bailee, even a gratuitous one, must take the care a person of ordinary prudence would take of his own similar goods","Yes, but only for half the bicycle's value"],"answer":2,"explanation":"Section 151 sets one standard of care for all bailees, whether or not they are paid: the care a man of ordinary prudence would take of his own goods of the same kind. Leaving the bicycle unlocked falls short of that standard.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-477","question":"An agent appointed to sell a client's property delegates the whole task, without the client's knowledge, to another person, who sells it badly. Trade custom does not permit such delegation. What is the legal position?","options":["The person to whom it was delegated becomes the principal's own agent","The agent cannot delegate without authority; he is responsible to the principal for the acts of the person he wrongly appointed","Delegation is always permitted when the agent is busy","The principal must bear the loss because he chose the agent"],"answer":1,"explanation":"Section 190: an agent cannot lawfully employ another to perform acts he has expressly or impliedly undertaken to perform personally, unless custom or the nature of the agency allows it. Under Section 193, an agent who improperly appoints a sub-agent is responsible for his acts.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-478","question":"A landlord lets a house that had been vacant. Rent for one month, which had earlier been shown as unrealised and not taxed, is recovered from the old tenant this year. Assume the rule that unrealised rent recovered later is taxed in the year of recovery. How is it treated?","options":["It is taxed in the year to which the rent relates","It is never taxed because it was excluded earlier","It is taxed under 'Other sources'","It is taxed as income from house property in the year of recovery, whether or not he still owns the house"],"answer":3,"explanation":"Unrealised rent that was excluded from the annual value and is later realised is deemed income from house property of the year of receipt, even if the assessee no longer owns the property.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-479","question":"A business pays its director's brother ₹1,20,000 a month as a consultant, while comparable consultants are paid ₹70,000 for the same work. Assume the rule allowing the tax officer to disallow excessive payments to relatives. How much may be disallowed for the year?","options":["₹14,40,000","₹8,40,000","₹6,00,000","Nil"],"answer":2,"explanation":"The excess over the reasonable market rate may be disallowed: (₹1,20,000 − ₹70,000) × 12 = ₹6,00,000. The reasonable part (₹8,40,000) stays deductible; disallowing the whole ₹14,40,000 goes too far.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-480","question":"Assertion (A): An agreement entered into by a minor is void from the beginning.\nReason (R): Under Section 11 of the Indian Contract Act, a person who has not attained the age of majority is not competent to contract.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mohori Bibee v Dharmodas Ghose held a minor's agreement void ab initio precisely because Section 11 makes a minor incompetent to contract, so R explains A.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-481","question":"Assertion (A): An unregistered partnership firm cannot file a suit against a third party to enforce a right arising from a contract.\nReason (R): Registration of every partnership firm is compulsory under the Indian Partnership Act, 1932.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Section 69 bars suits by an unregistered firm against third parties on contractual rights, so A is true. But registration is not compulsory under the 1932 Act; non-registration merely brings these disabilities, so R is false.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-482","question":"Assertion (A): A registered person cannot use its CGST credit to pay its SGST liability.\nReason (R): CGST is levied and collected by the Centre and SGST by the State, so the credit of one government's tax cannot settle a liability owed to the other.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Section 49 bars cross-utilisation between CGST and SGST. The reason is that they are separate levies of different governments; IGST, which is settled between them, is the only bridge.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-483","question":"Assertion (A): In a contract of sale of specific goods in a deliverable state, the property usually passes to the buyer when the contract is made.\nReason (R): The time of payment and the time of delivery decide when property passes in every sale.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Section 20 says property in specific goods in a deliverable state passes when the contract is made, even if payment or delivery or both are postponed. So A is true and R is false: payment and delivery do not decide it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-484","question":"Assertion (A): Rent from a vacant plot of land, not appurtenant to any building, is not taxed as income from house property.\nReason (R): Income from house property is charged on the annual value of buildings and lands appurtenant to them.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The house-property head covers buildings or lands appurtenant thereto. A bare plot falls outside it, so its rent is taxed under 'Other sources' (or business). R gives the reason for A.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-485","question":"Assertion (A): A contract to do an act that is impossible in itself is void.\nReason (R): A promisor who knew, or with reasonable diligence could have known, that the act was impossible must compensate a promisee who did not know.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are parts of Section 56: the first paragraph voids agreements to do impossible acts; the last paragraph imposes liability for compensation on a promisor who knew of the impossibility. The second does not explain the first.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-486","question":"Which of these conditions must be satisfied for a person to be a holder in due course of a cheque?\n1. He obtained it for consideration.\n2. He became its holder before the amount was due (for a cheque, before it became stale or was dishonoured).\n3. He had no sufficient cause to believe that there was a defect in the title of the transferor.\n4. He must be the payee named on the cheque.","options":["1, 2 and 3 only","1 and 3 only","1, 2, 3 and 4","2 and 4 only"],"answer":0,"explanation":"Section 9: a holder in due course takes for consideration, before maturity, and without sufficient cause to believe in a defect of title. He need not be the payee; most holders in due course are endorsees.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-487","question":"Which statements comparing an LLP with a general partnership firm in India are correct?\n1. Registration of an LLP is compulsory, while registration of a partnership firm is optional.\n2. A body corporate can be a partner of an LLP.\n3. A partnership firm is a legal person separate from its partners.\n4. In an LLP, a partner is not personally liable for another partner's wrongful act.","options":["1 and 2 only","1, 2, 3 and 4","2, 3 and 4 only","1, 2 and 4 only"],"answer":3,"explanation":"An LLP comes into existence only on incorporation, can have bodies corporate as partners, and shields partners from each other's wrongful acts. A partnership firm is merely a collective name for its partners, not a separate legal person.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-488","question":"Which statements about GST are correct?\n1. Exports of goods and services are zero-rated.\n2. A registered person must reverse input tax credit attributable to exempt supplies.\n3. Nil-rated supplies are treated as exempt supplies for input tax credit purposes.\n4. A person making only wholly exempt supplies must register once its turnover crosses the threshold.","options":["1 and 2 only","1, 2 and 3 only","1, 2, 3 and 4","2, 3 and 4 only"],"answer":1,"explanation":"Exports are zero-rated (Section 16, IGST Act). 'Exempt supply' includes nil-rated and non-taxable supplies, and credit attributable to them is not available. Section 23 frees a person engaged exclusively in wholly exempt or non-taxable supplies from registration.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-489","question":"An agreement provides that A will indemnify B against all liability arising from a transaction B enters into at A's request. B incurs a liability that has become absolute, but he has not yet paid anything. Can B require A to meet it?","options":["No; an indemnity holder can claim only after he has actually suffered the loss","No; only damages for breach of contract are available","Yes; an indemnity holder can compel the indemnifier to discharge an absolute liability even before paying it himself","Yes, but only after a court decree against B"],"answer":2,"explanation":"In Gajanan Moreshwar v Moreshwar Madan, the Bombay High Court held that an indemnity holder whose liability has become absolute can call upon the indemnifier to save him from it, without first paying. 'Indemnity is not necessarily given by repayment after payment.'","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-490","question":"A borrows a car from B, who did not own it but had borrowed it from its true owner C without authority to lend. C recovers the car from A, and A suffers loss on a pre-booked trip. Against whom does A have a claim under the bailment provisions?","options":["Against B, because a bailor is responsible to the bailee for loss caused by his not being entitled to make the bailment","Against C, the true owner","Against nobody, because the bailment was gratuitous","Against both B and C jointly"],"answer":0,"explanation":"Section 164: the bailor is responsible to the bailee for any loss the bailee may sustain because the bailor was not entitled to make the bailment, or to receive back the goods, or to give directions about them.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-491","question":"A buyer contracts to buy a specific antique painting, which the seller then refuses to deliver. Damages would not compensate the buyer because the painting is unique. What remedy can the court give under the Sale of Goods Act?","options":["Only damages measured by the market price","Only a refund of any price paid","Specific performance, directing the seller to deliver the painting","A declaration that the contract is void"],"answer":2,"explanation":"Section 58 lets the court, in a suit for breach of contract to deliver specific or ascertained goods, direct that the contract be performed specifically. Unique goods are the classic case where damages are inadequate.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-492","question":"A cheque crossed generally is presented at the counter of the drawee bank, which pays cash across the counter to the person presenting it. The person was not entitled to it. What is the bank's position?","options":["The bank is protected because it paid the bearer","The bank is protected if it checked the presenter's identity","Only the drawer bears the loss","The bank is liable to the true owner for any loss, because a crossed cheque must be paid only to a banker"],"answer":3,"explanation":"Under Sections 126 and 129, a cheque crossed generally may be paid only to a banker. A paying bank that pays otherwise is liable to the true owner for any loss suffered as a result.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-493","question":"Under Section 10 of the Negotiable Instruments Act, which element is NOT part of 'payment in due course'?","options":["The payment is made in accordance with the apparent tenor of the instrument","The payment is made on the due date or after it in all cases, whatever the instrument's tenor","The payment is made in good faith and without negligence","The payment is made to a person in possession under circumstances not giving reasonable grounds to believe he is not entitled"],"answer":1,"explanation":"Payment in due course means payment in accordance with the apparent tenor of the instrument, in good faith and without negligence, to any person in possession of it in circumstances that do not afford a reasonable ground for believing he is not entitled to receive it.","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-494","question":"A bill of exchange is drawn in Delhi on a merchant who lives in London, and it is made payable in Mumbai. Under the Negotiable Instruments Act, is it an inland instrument?","options":["Yes; it is drawn in India and made payable in India","No; it is drawn on a person resident outside India","No; it is a foreign instrument because the acceptor is abroad","It is inland only if accepted in India"],"answer":0,"explanation":"Section 11: an instrument drawn or made in India and either made payable in India or drawn on a person resident in India is inland. Being drawn in India and payable in India is enough, even though the drawee lives abroad.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-495","question":"Under Section 271 of the Companies Act, 2013 as it now stands, which of these is NOT a ground on which the Tribunal may wind up a company?","options":["The company has resolved by special resolution to be wound up by the Tribunal","The company is unable to pay its debts","The company has defaulted in filing its financial statements or annual returns for five consecutive financial years","The Tribunal is of the opinion that it is just and equitable to wind up the company"],"answer":1,"explanation":"Since the Insolvency and Bankruptcy Code came in, inability to pay debts has been removed from Section 271; insolvency is dealt with under the IBC. The other three remain grounds for winding up by the Tribunal.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-496","question":"A non-resident company receives royalty from an Indian company for the use of a patent in the Indian company's business carried on in India. Is the royalty taxable in India in the non-resident's hands?","options":["No; a non-resident is never taxed on royalty","No, unless the royalty is received in India","Yes, but only if the non-resident has an office in India","Yes; such royalty is deemed to accrue or arise in India"],"answer":3,"explanation":"Royalty payable by a resident for rights used in a business carried on in India is deemed to accrue or arise in India, so it is taxable in the non-resident's hands (subject to any tax treaty), wherever it is paid.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-497","question":"Which statements about income tax are correct? (Assume the usual rules.)\n1. Agricultural income from land in India is exempt.\n2. A partner's share of profit from a firm assessed as a firm is exempt in his hands.\n3. Salary received by a partner from his firm is taxed under the head 'Salaries'.\n4. A casual winning from a lottery is taxed under 'Income from other sources'.","options":["1 and 2 only","1, 2, 3 and 4","1, 2 and 4 only","2, 3 and 4 only"],"answer":2,"explanation":"Agricultural income is exempt; a partner's profit share is exempt because the firm pays tax on it; casual winnings are 'other sources'. A partner is not an employee, so his salary from the firm is business income, not 'Salaries'.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-498","question":"A sells his shop's stock to B for ₹3 lakh, with B agreeing to pay A's creditor C directly. B fails to pay. Can C sue B?","options":["Yes; the contract was made for C's benefit","No, as a general rule; C is a stranger to the contract between A and B, though C can still sue A on the original debt","Yes; consideration moved from A","No; and C also loses his claim against A"],"answer":1,"explanation":"Under the doctrine of privity, only a party to a contract can sue on it, even if it benefits a third person. C is not a party (no trust, family arrangement, acknowledgment or estoppel exception applies), so he must recover from A, his debtor.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-499","question":"A surety's guarantee states that his liability shall not exceed ₹2 lakh, though the loan to the principal debtor is ₹5 lakh. The debtor defaults on the full amount. How much can the creditor recover from the surety?","options":["₹5 lakh","₹3 lakh","Nothing until the creditor exhausts remedies against the debtor","₹2 lakh"],"answer":3,"explanation":"Section 128 makes the surety's liability co-extensive with the principal debtor's 'unless it is otherwise provided by the contract'. A surety may limit his liability; here it is capped at ₹2 lakh. The creditor need not first sue the debtor.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-500","question":"At an auction of goods in lots, the auctioneer knocks down Lot 7 to B. Before B pays, the seller wants to withdraw Lot 7 because a higher private offer has come in. What is the legal position?","options":["The seller may withdraw it until B pays the price","The sale is complete only when all lots are sold","The sale of Lot 7 was complete when the hammer fell, so the seller cannot withdraw it","The seller may withdraw it if he compensates B"],"answer":2,"explanation":"Section 64: where goods are put up in lots, each lot is the subject of a separate contract of sale, and the sale is complete when the auctioneer announces its completion by the fall of the hammer. Until then, a bid may be withdrawn.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-501","question":"A company wants to accept deposits from its members. Which statement best reflects the Companies Act, 2013?","options":["It may do so only on satisfying conditions such as a members' resolution, a circular to members, a deposit repayment reserve and filing with the Registrar","Any company may accept member deposits freely without conditions","Only banking companies may ever accept deposits","It needs only a board resolution"],"answer":0,"explanation":"Section 73(2) allows a company to accept deposits from members only by passing a resolution in general meeting and complying with conditions such as issuing a circular, filing it with the Registrar, depositing a prescribed amount in a deposit repayment reserve and, where required, giving security or insurance.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-502","question":"How does a contract of guarantee differ from a contract of indemnity under the Indian Contract Act?","options":["A guarantee has two parties and an indemnity three","In both, the promisor's liability is secondary and arises only on another's default","A guarantee must be in writing, while an indemnity must be oral","A guarantee has three parties and the surety's liability is secondary; an indemnity has two parties and the indemnifier's liability is primary"],"answer":3,"explanation":"In a guarantee, the surety answers for the principal debtor's default to the creditor, so his liability is collateral. In an indemnity, the indemnifier promises the indemnity-holder directly to save him from loss, an original and primary liability. Both may be oral or written.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-503","question":"A witness who has been summoned by a court to give evidence is promised ₹10,000 by a party if he attends and testifies. He attends and testifies. Can he enforce the promise?","options":["No; doing what he was already legally bound to do is not consideration","Yes; attending court was an act done at the promisor's desire","Yes; any promise for a lawful act is enforceable","No, because the promise was not in writing"],"answer":0,"explanation":"Performing a pre-existing public duty imposed by law is not good consideration for a fresh promise (as in Collins v Godefroy). The witness gave nothing beyond what the summons already required.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-504","question":"B, an adult, agrees with A that in return for ₹5 lakh she will not marry anyone for ten years. Later she marries and A sues to recover the money. What is the status of the agreement?","options":["Valid, because B received consideration","Void, as an agreement in restraint of the marriage of a person other than a minor","Voidable at A's option","Valid, because the restraint was only partial and for a limited time"],"answer":1,"explanation":"Section 26 makes every agreement in restraint of the marriage of any person other than a minor void. Unlike the exception in Section 27 for trade, there is no exception for partial or reasonable restraints.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-505","question":"A partnership deed says that, while the partnership lasts, no partner will carry on any business other than that of the firm. One partner argues that this clause is void under Section 27 of the Contract Act. Is he right?","options":["Yes; every restraint of trade is void in India","Yes, unless the restraint is limited to the same city","No; the Partnership Act expressly allows partners to agree not to carry on any other business while they are partners","No, but only if the firm is registered"],"answer":2,"explanation":"Section 11(2) of the Partnership Act saves such a covenant despite Section 27 of the Contract Act. Similar statutory exceptions allow reasonable restraints on outgoing partners and on the sale of goodwill.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-506","question":"A loan agreement says interest is 12% a year, but if the borrower defaults, interest on the whole loan will be 24% from the date of the loan. How will an Indian court treat the 24% clause?","options":["As liquidated damages, recoverable in full","As a stipulation by way of penalty, so the lender can get only reasonable compensation up to that amount","As void, so even the 12% is lost","As valid, because the borrower agreed to it"],"answer":1,"explanation":"The Explanation to Section 74 says a stipulation for increased interest from the date of default may be a stipulation by way of penalty. Here the increase even applies backwards from the date of the loan, so the court awards only reasonable compensation not exceeding the stated sum.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-507","question":"A lets his manager B regularly buy goods on credit from C in A's name, and A always pays. A then dismisses B but tells no one. B buys more goods from C in A's name and disappears. Is A liable to C?","options":["No; B had no authority after his dismissal","No, unless A ratifies the purchase","Yes; by his conduct A led C to believe B had authority, so A is bound as to C","Yes, but only for half the price"],"answer":2,"explanation":"Section 237 binds a principal who, by words or conduct, has induced third persons to believe that acts were within the agent's authority. A's earlier course of dealing and silence about the dismissal create such an apparent authority.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-508","question":"A carrier transporting fruit for a trader finds that the fruit will rot within hours because of an unexpected road closure, and it cannot reach the trader for instructions. It sells the fruit at the best price available nearby. What is the legal position?","options":["The carrier acted as an agent of necessity and the sale binds the owner","The carrier is liable for conversion because it had no authority to sell","The sale is void and the buyer must return the fruit","The carrier must pay the full contract value of the fruit"],"answer":0,"explanation":"Section 189 gives an agent authority, in an emergency, to do all acts to protect his principal from loss that a person of ordinary prudence would do in his own case. Genuine emergency, inability to communicate and good faith make the sale binding.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-509","question":"Which of these is NOT 'goods' under the Sale of Goods Act, 1930?","options":["Growing crops agreed to be severed before sale","Shares in a company","Goodwill of a business","A debt owed to the seller by a third person"],"answer":3,"explanation":"Section 2(7) defines goods as every kind of movable property other than actionable claims and money, and includes stocks and shares, growing crops and things attached to the land agreed to be severed. A debt is an actionable claim; goodwill is treated as goods.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-510","question":"A farmer contracts in March to sell to B the wheat he expects to harvest in May from his field. What is the nature of the contract in March?","options":["A sale, because the goods are specific","Void, because the goods do not yet exist","An agreement to sell, because a contract to sell future goods cannot pass property until the goods exist","A contingent sale that is complete only on payment"],"answer":2,"explanation":"Section 6(3): where by a contract of sale the seller purports to effect a present sale of future goods, the contract operates as an agreement to sell. Property passes later, when the goods are produced and appropriated.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-511","question":"A contract of sale fixes payment within 30 days. The buyer pays on day 35. Can the seller treat the contract as at an end and refuse delivery, the contract being silent about the importance of the payment date?","options":["No; unless a different intention appears, stipulations about the time of payment are not of the essence","Yes; any delay in payment allows rescission","Yes, if the delay is more than 10% of the credit period","No, because the seller must deliver before payment in every case"],"answer":0,"explanation":"Section 11: unless a different intention appears from the contract, stipulations as to time of payment are not deemed to be of the essence of a contract of sale. The seller may claim interest or damages, but cannot rescind merely for late payment.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-512","question":"Goods sold to B are lying in a warehouse. The seller gives B a delivery order, and the warehouse keeper acknowledges to B that he now holds the goods on B's behalf. The goods are not moved. Has delivery taken place?","options":["No; delivery requires physical transfer","No, until B removes the goods","Yes, but only symbolic delivery, which passes no rights","Yes; this is constructive delivery by attornment"],"answer":3,"explanation":"Delivery may be actual, symbolic or constructive. When a third person in possession acknowledges to the buyer that he holds the goods on the buyer's behalf, there is constructive delivery (attornment), even though nothing is moved.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-513","question":"A seller fails to deliver 1,000 units contracted at ₹50 each. On the delivery date the market price is ₹58. The buyer has not paid anything. What damages can the buyer ordinarily recover for non-delivery?","options":["₹58,000","₹8,000","₹50,000","₹4,000"],"answer":1,"explanation":"Under Section 57 the usual measure is the difference between the contract price and the market price on the date fixed for delivery: (58 − 50) × 1,000 = ₹8,000, which lets the buyer buy substitutes at no extra cost.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-514","question":"A cheque dated 30 April is handed to the payee on 10 April. What is its legal status?","options":["It is void because it is post-dated","It is a valid negotiable instrument, but it is payable only on or after 30 April","It is payable immediately on 10 April","It becomes a promissory note until 30 April"],"answer":1,"explanation":"A post-dated cheque is a valid cheque payable on or after its date; until then it is in effect a bill of exchange not yet due. It can be negotiated, and the statutory period for presentment runs from the date it bears.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-515","question":"A cheque payable to 'Ravi or order' is endorsed by Ravi 'Pay Sunil only' and signed. What is the effect?","options":["It is a restrictive endorsement; Sunil can receive payment but cannot negotiate the cheque further","It is a blank endorsement; the cheque becomes payable to bearer","It is a conditional endorsement that is void","It makes Sunil a holder in due course who can negotiate freely"],"answer":0,"explanation":"Section 50: an endorsement may restrict further negotiation by express words, such as 'Pay to C only'. The endorsee gets the right to receive payment, but the instrument is no longer negotiable.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-516","question":"An endorser writes 'Notice of dishonour waived' above his signature while endorsing a bill. What does this mean?","options":["He will not be liable if the bill is dishonoured","The bill cannot be negotiated further","He is liable only if he receives a protest","He remains liable on dishonour even if the holder does not give him notice of dishonour"],"answer":3,"explanation":"This is a facultative endorsement: the endorser gives up a right that the law gives him (notice of dishonour). Section 98 also says no notice of dishonour is needed when the party entitled to it has waived it.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-517","question":"A drawer issues a cheque and then closes his bank account before it is presented. The cheque is returned 'account closed'. Can the payee prosecute under Section 138 of the Negotiable Instruments Act, if the other conditions are met?","options":["No; Section 138 covers only 'insufficient funds' returns","No; the drawer is excused because the account no longer exists","Yes; dishonour because the account has been closed is covered as a dishonour for insufficient funds","Yes, but only if the account was closed after presentment"],"answer":2,"explanation":"The Supreme Court has held (NEPC Micon v Magma Leasing) that closing the account before presentment is a species of the drawer's account being insufficient, so a dishonour with 'account closed' attracts Section 138.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-518","question":"A bearer cheque and an order cheque are each handed over by their holders to new transferees. What does negotiation require in each case?","options":["Bearer cheque: delivery alone; order cheque: endorsement and delivery","Both need endorsement and delivery","Both need delivery alone","Bearer cheque: endorsement and delivery; order cheque: delivery alone"],"answer":0,"explanation":"Section 47: an instrument payable to bearer is negotiated by mere delivery. Section 48: an instrument payable to order is negotiated by the holder's endorsement and delivery.","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-519","question":"A shareholder of a public company wants to sell his shares to an outsider; the directors dislike the buyer. Under the Companies Act, 2013, what is the general position on transfer?","options":["The board may refuse any transfer at its discretion, with no appeal","Transfer needs the consent of all members","Shares of a public company are freely transferable, and refusal to register a transfer can be challenged before the Tribunal","Shares of a public company can be transferred only to existing members"],"answer":2,"explanation":"Section 58: the securities of a public company are freely transferable (contracts between specific persons may still be enforced). If a company refuses or fails to register a transfer without sufficient cause, the transferee may appeal to the Tribunal.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-520","question":"In a company limited by guarantee, what is the liability of a member?","options":["Up to the unpaid amount on his shares only","Unlimited, like a partner","Nothing, because guarantee companies have no members","Up to the amount he has undertaken in the memorandum to contribute to the assets if the company is wound up"],"answer":3,"explanation":"Section 2(21): in a company limited by guarantee, members' liability is limited to the amount each undertakes in the memorandum to contribute in the event of winding up. If it also has share capital, the unpaid amount on shares is payable too.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-521","question":"A subsidiary wants to buy shares in its own holding company as an investment. Is this allowed under the Companies Act, 2013?","options":["Yes, with a board resolution","No; a company generally cannot hold shares in its holding company, except as a legal representative or trustee or in other limited cases","Yes, up to 10% of the holding company's capital","Yes, if the shares are bought on a stock exchange"],"answer":1,"explanation":"Section 19 prohibits a company from holding shares in its holding company and the holding company from allotting or transferring its shares to its subsidiary, subject to exceptions such as holding as a legal representative of a deceased member or as a trustee.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-522","question":"Which of these powers can the board of a company exercise only by a resolution passed at a board meeting, not by circulation?","options":["Approving the company's annual holiday list","Approving a routine purchase order within an approved budget","Approving the appointment of a junior accountant","Making calls on shareholders for money unpaid on their shares"],"answer":3,"explanation":"Section 179(3) lists powers to be exercised only by resolutions at board meetings, including making calls, authorising buy-back, issuing securities, borrowing, investing funds, granting loans, approving financial statements and approving mergers or takeovers.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-523","question":"A member of a Hindu undivided family receives ₹2 lakh from the HUF out of its income. Assume the usual rules. Is it taxable in the member's hands?","options":["No; a sum received by a member out of the HUF's income is exempt in his hands","Yes, as income from other sources","Yes, as a gift above the exempt limit","Only the part above ₹50,000 is taxable"],"answer":0,"explanation":"Amounts received by an individual as a member of an HUF out of the family's income (or out of the income of an impartible estate) are exempt, because the HUF is itself taxed on that income.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-524","question":"A dealer in shares sells shares held as stock-in-trade at a profit. Assume the usual definitions. Under which head is the profit taxed?","options":["Capital gains","Profits and gains of business or profession, because stock-in-trade is not a capital asset","Income from other sources","Exempt, because shares are financial assets"],"answer":1,"explanation":"Stock-in-trade is excluded from the definition of 'capital asset', so its sale gives business income. The same shares held as investments by the same person would give capital gains.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-525","question":"Assume unlisted shares are long-term capital assets only if held for more than 24 months. An investor received bonus shares in an unlisted company 20 months ago on original shares bought 5 years ago, and sells the bonus shares now. How is the gain classified?","options":["Long-term, because the original shares were held for 5 years","Long-term, because bonus shares are treated as acquired with the original shares","Short-term, because the holding period of bonus shares runs from their allotment","It is not a capital gain at all, because bonus shares cost nothing"],"answer":2,"explanation":"Bonus shares are a separate asset whose holding period starts on the date of allotment, with cost generally taken as nil. Held for 20 months, they are short-term under the stated rule.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-526","question":"A trader buys and sells listed shares on the same day without taking delivery (intra-day trading). Assume the usual rules. How is the result treated?","options":["As short-term capital gain or loss","As speculative business income or loss, which is kept separate from other business results","As income from other sources","As non-speculative business income"],"answer":1,"explanation":"A transaction in shares that is settled otherwise than by actual delivery is speculative. Speculation profit is business income, and speculation losses can be set off only against speculation profits.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-527","question":"A business is set up on 10 October and starts trading at once. Under the income-tax rules, what is the period of its first year (previous year / tax year) for computing income?","options":["The full year from 1 April to 31 March","Twelve months from 10 October","From 10 October to 31 December","From 10 October to the following 31 March"],"answer":3,"explanation":"For a newly set-up business or a new source of income, the first year begins on the date of setting up (or the date the new source comes into existence) and ends on the next 31 March.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-528","question":"A supplier dispatches goods on 5 May but issues the tax invoice only on 12 May. Under the CGST Act, when should the invoice for a supply of goods involving movement normally have been issued?","options":["Before or at the time of removal of the goods for supply, i.e. by 5 May","Within 30 days of removal","Within 7 days of removal","On receipt of payment"],"answer":0,"explanation":"Section 31(1) requires a tax invoice for goods to be issued before or at the time of removal of goods for supply where supply involves movement, or of delivery in other cases. The 30-day window applies to services.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-529","question":"A registered person buys a machine that it will use exclusively to make goods that are fully exempt from GST. Can it take input tax credit on the machine?","options":["Yes, because capital goods always carry full credit","Yes, but only 50% of the tax","No; credit is not available on capital goods used exclusively for exempt supplies","Yes, if it later starts taxable supplies within a year, without any reversal rules"],"answer":2,"explanation":"Section 17(2) restricts credit to the extent of use for taxable supplies (including zero-rated). Capital goods used exclusively for exempt supplies carry no credit; those used for both are apportioned under the rules.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-530","question":"Under the Consumer Protection Act, 2019, a person buys a machine to run a small tailoring business that he operates himself to earn his livelihood by self-employment. Is he a 'consumer'?","options":["Yes; goods bought exclusively for earning a livelihood by self-employment are not treated as bought for a commercial purpose","No; anything bought for a business is for commercial purpose","Yes, but only if the machine costs less than ₹1 lakh","No; consumers can only be individuals buying for household use"],"answer":0,"explanation":"The definition excludes a person who obtains goods for resale or a commercial purpose, but the Explanation says 'commercial purpose' does not include use by a person of goods bought exclusively to earn his livelihood by self-employment.","difficulty":"hard","source":"CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-531","question":"A singer contracts to sing at B's theatre on two nights a week for two months. She deliberately skips one night. B lets her sing on later nights without objecting, and then wants to end the contract because of the missed night. What is the position?","options":["B can end the contract at any time because of the earlier refusal","B can neither end the contract nor claim compensation","B cannot now end the contract on that ground, having acquiesced in its continuance, but he can claim compensation for the missed night","The contract became void when she missed the night"],"answer":2,"explanation":"Section 39 lets the promisee put an end to the contract when the promisor refuses to perform in its entirety, unless he has signified, by words or conduct, his acquiescence in its continuance. The illustration to the section covers exactly this; compensation remains available.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-532","question":"A pays B ₹1 lakh, for which B promises to deliver later either 100 bags of rice or a quantity of smuggled goods, at A's option. What is the legal position?","options":["The whole agreement is void because one alternative is illegal","A may insist on the smuggled goods because he paid","B may choose which alternative to perform","There is a valid contract to deliver the rice; the alternative of smuggled goods is void"],"answer":3,"explanation":"Section 58: in an alternative promise where one branch is legal and the other illegal, only the legal branch can be enforced. The illegality of one alternative does not taint the other.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-533","question":"B contracts to build a boat for C, with C paying in instalments as stages are completed; A is surety to C for B's due performance. Without A's knowledge, C pays B the last two instalments in advance. B abandons the work. Is A liable?","options":["No; the creditor's act of prepayment impaired the surety's eventual remedy, so A is discharged","Yes; prepayment is a private matter between C and B","Yes, but only for the instalments that were not prepaid","No, but only if A had expressly forbidden prepayment"],"answer":0,"explanation":"Section 139: if the creditor does any act inconsistent with the surety's rights, or omits to do an act his duty requires, and the surety's eventual remedy against the debtor is impaired, the surety is discharged. Prepayment removed B's incentive to finish.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-534","question":"B borrows A's car for a weekend and promises to return it by Sunday evening. B keeps it until Tuesday; on Monday, through no fault of B, it is damaged in a sudden flood. Who bears the loss?","options":["A, because the flood was an act of God","B, because a bailee who keeps goods beyond the agreed time is responsible for any loss from that time, even without negligence","A and B equally","A, because the bailment was gratuitous"],"answer":1,"explanation":"Section 161: if, by the bailee's default, the goods are not returned at the proper time, he is responsible to the bailor for any loss, destruction or deterioration from that time, regardless of care or fault.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-535","question":"A buyer receives goods and neither tells the seller that he rejects them nor returns them. Four months later, after reselling part of them, he complains that they were not as ordered. What is the position under the Sale of Goods Act?","options":["He is deemed to have accepted the goods, so he can claim damages but not reject them","He may still reject them because he never signed an acceptance","He may reject only the unsold part","He has no remedy at all because he resold some goods"],"answer":0,"explanation":"Section 42: the buyer is deemed to have accepted goods when he intimates acceptance, does an act inconsistent with the seller's ownership (such as reselling), or retains them beyond a reasonable time without intimating rejection. After acceptance, a breach of condition can be treated only as a breach of warranty.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-536","question":"Goods are sold on three months' credit. The buyer has not taken them away, and before the credit period ends the buyer becomes insolvent. Can the unpaid seller, still in possession, refuse delivery?","options":["No; the lien is suspended until the credit period ends","Yes; the seller's lien is available if the buyer becomes insolvent, even though the credit period has not expired","Yes, but only after the credit period ends","No; property has passed, so the seller must deliver"],"answer":1,"explanation":"Section 47(1): an unpaid seller in possession has a lien where goods are sold without credit, where sold on credit and the term has expired, or where the buyer becomes insolvent. Insolvency revives the lien during the credit period.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-537","question":"A cheque is presented for payment much later than a reasonable time after its issue. Before presentment, the drawee bank fails, and the payee receives only part of the amount. Under the Negotiable Instruments Act, what happens to the drawer's liability?","options":["The drawer is fully discharged because presentment was late","The drawer remains fully liable because the bank's failure is not his fault","The drawer is discharged only to the extent of the actual damage caused by the delay; for the rest he remains liable","The drawer is discharged only if the cheque was crossed"],"answer":2,"explanation":"Section 84: where a cheque is not presented within a reasonable time and the drawer suffers actual damage through the delay (such as the bank's failure), he is discharged to the extent of that damage. The holder becomes a creditor of the bank for the remainder.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-538","question":"A company's paid-up equity capital is ₹50 crore and its free reserves are ₹30 crore. Up to what amount can it buy back its shares on the authority of a board resolution alone, without a special resolution of members?","options":["₹20 crore","₹5 crore","₹12.5 crore","₹8 crore"],"answer":3,"explanation":"Section 68: buy-back up to 25% of paid-up capital and free reserves (here ₹20 crore) needs a special resolution, but up to 10% of total paid-up equity capital and free reserves may be authorised by a board resolution: 10% × 80 = ₹8 crore.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-539","question":"A shareholder asks to inspect the minutes of the company's board meetings. Is the company obliged to allow this?","options":["Yes; members may inspect all minutes of the company","No; members may inspect minutes of general meetings, but board minutes are not open to them","Yes, if the shareholder holds at least 10% of the shares","No; even general meeting minutes are confidential"],"answer":1,"explanation":"Section 119 gives members the right to inspect, and get copies of, minutes of general meetings. Board minutes are kept at the registered office but are not open to members' inspection (directors and auditors may see them).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-540","question":"A company repaints its office building and repairs its plumbing, charging the cost to the profit and loss account as routine maintenance. Is input tax credit available on the tax paid on these services?","options":["No; all credit relating to buildings is blocked","No, unless the building is used for exempt supplies","Only 50% of the credit is available","Yes; the block on construction applies to repairs only to the extent they are capitalised"],"answer":3,"explanation":"The Explanation to Section 17(5) defines 'construction' to include reconstruction, renovation, additions, alterations or repairs to the extent of capitalisation to the immovable property. Revenue repairs written off are not blocked.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-541","question":"A trader under the GST composition scheme receives legal services from an advocate, on which tax is payable under reverse charge. What is its position?","options":["It is exempt from reverse charge because it is a composition dealer","It pays tax at its composition rate instead of the normal rate","It must pay the reverse-charge tax at the normal rate in cash and cannot take credit for it","It pays the tax but can use it as input tax credit"],"answer":2,"explanation":"A composition taxpayer must still pay tax on inward supplies liable to reverse charge, at the applicable normal rates and not at the composition rate, and it cannot take input tax credit, so the tax becomes a cost.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-542","question":"A farmer also runs a shop. This year his agricultural operations (income from which is exempt) show a loss of ₹1 lakh and his shop earns ₹4 lakh. Assume the usual rules. Can he set off the agricultural loss against the shop income?","options":["No; a loss from a source whose income is exempt cannot be set off against taxable income","Yes, under inter-head set-off","Yes, but only half of it","No, but it can be carried forward against future shop profits"],"answer":0,"explanation":"Set-off is allowed only for losses from sources whose income would be taxable. Agricultural income is exempt, so its losses are ignored for computing taxable income (they matter only in the rate-computation for partial integration).","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-543","question":"A business has unabsorbed depreciation from earlier years. Assume the usual rules for unabsorbed depreciation. Which statement is correct?","options":["It can be set off only against business income and lapses after 8 years","It can be set off against income under any head other than salaries and carried forward without any time limit","It can be set off against salary income as well","It lapses if the return is filed late"],"answer":1,"explanation":"Unabsorbed depreciation is added to the next year's depreciation allowance, so it can be set off against any head except 'Salaries' and carried forward indefinitely. Unlike business losses, it is not lost for a belated return.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-544","question":"A creditor of a partnership firm is owed ₹10 lakh. Partner X is wealthy; the other partners have little. Can the creditor recover the whole ₹10 lakh from X alone?","options":["No; X is liable only for his share in the profit-sharing ratio","No; the creditor must first exhaust the firm's assets and then sue all partners together","Yes, but only if X signed the contract with the creditor","Yes; every partner is liable jointly with the others and also severally for all acts of the firm done while he is a partner"],"answer":3,"explanation":"Section 25 of the Partnership Act makes every partner liable, jointly with all the other partners and also severally, for all acts of the firm done while he is a partner. X may then claim contribution from the others.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-545","question":"A partner, while handling a client's matter in the ordinary course of the firm's business, negligently causes the client a loss of ₹5 lakh. Who is liable to the client?","options":["The firm, and so every partner, to the same extent as the negligent partner","Only the negligent partner","Only the firm's assets, not the partners personally","The partners in proportion to their capital"],"answer":0,"explanation":"Section 26: where a partner's wrongful act or omission in the ordinary course of business causes loss to a third party, the firm is liable to the same extent as the partner. Under Section 25 that liability is joint and several among all partners.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-546","question":"Partner P transfers his whole interest in a firm to T, an outsider. The other partners continue the business. Which rights does T get while the firm continues?","options":["All the rights of a partner, including management","No rights at all until the firm is dissolved","The right to receive P's share of profits as agreed, but no right to interfere in management or to demand accounts","The right to inspect the books and demand accounts"],"answer":2,"explanation":"Section 29: a transferee of a partner's interest is entitled to receive the transferor's share of profits and must accept the account of profits agreed by the partners; he cannot interfere in the conduct of business, require accounts or inspect the books. On dissolution he gets the transferor's share of assets.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-547","question":"Which statement about voidable and void contracts is correct?","options":["A voidable contract is void from the start but can be ratified","A voidable contract is valid until the aggrieved party avoids it, and a third party who acquires goods in good faith before avoidance can get a good title","A void contract binds the parties until a court declares it void","Third parties can never get title under a voidable contract"],"answer":1,"explanation":"A voidable contract is enforceable at the option of one party and remains valid until he rescinds it. Section 29 of the Sale of Goods Act protects a good-faith buyer who acquires goods from a person holding them under a voidable contract before it is rescinded.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-548","question":"A contract becomes void because of a supervening law. Before that, A had paid B ₹50,000 in advance under it, and B had received it. What must B do?","options":["Keep it, because the contract was valid when the money was paid","Keep half and return half","Restore the ₹50,000 (or compensate for it), because a person who received an advantage under a contract that becomes void must restore it","Return it only if B is shown to be at fault"],"answer":2,"explanation":"Section 65: when an agreement is discovered to be void, or a contract becomes void, any person who has received any advantage under it must restore it, or compensate for it, to the person from whom he received it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-549","question":"B buys a business after A knowingly lies about its profits. B wants both to rescind the contract and to claim damages for expenses wasted. How does fraud differ from innocent misrepresentation here?","options":["For both, B may only rescind; damages are never available","For both, B may claim damages but not rescind","For fraud B may claim damages only; for misrepresentation he may rescind only","For fraud B may rescind and also claim damages; for innocent misrepresentation he may rescind but generally has no claim for damages"],"answer":3,"explanation":"Both make the contract voidable (Section 19). Fraud is also a civil wrong (deceit), so damages are available, and Section 19 lets the defrauded party insist on being put in the position he would have been in. Innocent misrepresentation gives rescission without damages.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-550","question":"A company publicly announces a cash prize for anyone who uses its smoke ball as directed and still catches influenza. X does so, catches influenza and claims the prize without ever having told the company she accepted. Is the company liable?","options":["No; acceptance must always be communicated to the offeror","No; an advertisement is only an invitation to treat","Yes; in a general offer, performing the conditions is acceptance, and separate communication of acceptance is not required","Yes, but only if X bought the product directly from the company"],"answer":2,"explanation":"A general offer to the world can be accepted by anyone who performs its conditions with knowledge of it (Carlill v Carbolic Smoke Ball Co.; Section 8). The offeror impliedly dispenses with notice of acceptance.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-551","question":"A offers to sell his shares to B on 1 June, stating no time limit. B replies accepting on 1 December, by which time the share price has risen sharply. Is there a contract?","options":["Probably not; an offer with no stated time lapses after a reasonable time, which six months in a volatile market would exceed","Yes; an offer without a time limit stays open until revoked","Yes, because A did not revoke the offer","No, because acceptance must always be given within seven days"],"answer":0,"explanation":"Section 6(2) says a proposal is revoked by the lapse of the time prescribed for acceptance or, if none is prescribed, by the lapse of a reasonable time without communication of acceptance. What is reasonable depends on the subject matter; for shares it is short.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-552","question":"A retailer emails a wholesaler an order for 100 cartons at the list price. Without replying, the wholesaler dispatches the 100 cartons the next day. When was the order accepted?","options":["Only when the retailer receives the goods","When the wholesaler dispatched the goods, because acceptance can be made by conduct","Never, because there was no written reply","When the retailer pays the invoice"],"answer":1,"explanation":"Section 8: performance of the conditions of a proposal, or the acceptance of any consideration offered with it, is acceptance. Dispatching the goods in response to an order is acceptance by conduct.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-553","question":"A finds a valuable but perishable consignment of fruit and cannot trace the owner despite reasonable search. What does the Indian Contract Act allow him to do?","options":["Sell the goods, because they are in danger of perishing and the owner cannot be found with reasonable diligence","Nothing; he must keep the goods until the owner claims them","Keep the goods as his own after a week","Sell them only with a court's permission"],"answer":0,"explanation":"Section 169 lets a finder sell the goods when the owner cannot be found with reasonable diligence (or refuses lawful charges) and the goods are in danger of perishing or losing most of their value, or the finder's lawful charges amount to two-thirds of their value.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-554","question":"An estate agent is engaged to sell a house for a commission of 2% 'on completion of the sale'. He finds a buyer, but the buyer backs out before completion through no fault of the owner. Is the agent entitled to commission?","options":["Yes; finding a willing buyer is enough","No; unless otherwise agreed, remuneration is due only on completion of the act the agent was employed to do","Yes, half the commission for the work done","No, and he must also refund his expenses"],"answer":1,"explanation":"Section 219: in the absence of any special contract, payment for the performance of any act is not due to the agent until the completion of that act. Here the contract itself ties commission to completion of the sale.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-555","question":"Must a contract of guarantee be in writing to be enforceable under the Indian Contract Act?","options":["Yes; an oral guarantee is void","Yes, and it must also be registered","Only guarantees above ₹1 lakh must be written","No; a guarantee may be either oral or written"],"answer":3,"explanation":"Section 126 says a guarantee may be either oral or written. (English law, by contrast, requires written evidence of a guarantee under the Statute of Frauds.)","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-556","question":"Under a hire-purchase agreement, a consumer takes a car, pays a deposit and agrees to pay 24 monthly instalments, with an option to buy for a nominal sum at the end. When does ownership pass?","options":["When the car is delivered","When half the instalments are paid","Only when the last instalment is paid and the option to purchase is exercised","When the agreement is signed"],"answer":2,"explanation":"In hire purchase the hirer is a bailee until all instalments are paid and the option is exercised; only then does property pass. In a sale on instalments, by contrast, property passes at once.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-557","question":"A contract of sale says nothing about the order of performance. The buyer refuses to pay until the goods are delivered, and the seller refuses to deliver until he is paid. What does the Sale of Goods Act provide?","options":["The seller must always deliver first","Delivery and payment are concurrent conditions; each must be ready and willing to perform at the same time","The buyer must always pay first","The contract is void for uncertainty"],"answer":1,"explanation":"Section 32: unless otherwise agreed, delivery of the goods and payment of the price are concurrent conditions: the seller must be ready and willing to give possession in exchange for the price, and the buyer to pay in exchange for possession.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-558","question":"A gives his nephew a cheque for ₹50,000 as a birthday gift. It is dishonoured for insufficient funds. Can the nephew prosecute A under Section 138 of the Negotiable Instruments Act?","options":["No; Section 138 applies only to cheques issued in discharge of a legally enforceable debt or other liability","Yes; any dishonoured cheque attracts Section 138","Yes, if he sends a notice within 30 days","No, because cheques between relatives are void"],"answer":0,"explanation":"Section 138 requires the cheque to have been drawn for the discharge, wholly or partly, of a legally enforceable debt or other liability. A gift cheque discharges no liability, so the offence is not made out.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-559","question":"A promoter buys land for ₹1 crore and, without disclosing this, sells it to the company he is forming for ₹1.5 crore. The company later discovers the facts. What can it do?","options":["Nothing, because the company was not in existence when the land was bought","Only sue for the difference if the land is worth less than ₹1 crore","Nothing, because promoters owe duties only after incorporation","Rescind the contract or recover the secret profit of ₹50 lakh, because a promoter stands in a fiduciary position towards the company"],"answer":3,"explanation":"A promoter owes fiduciary duties to the company he forms and must not make a secret profit. If he does not make full disclosure to an independent board or the members, the company may rescind the contract or recover the profit.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-560","question":"What is the legal effect of a share certificate issued under the company's common seal (or as authorised by the articles)?","options":["It is conclusive proof of title that cannot be challenged","It is itself a negotiable instrument","It is prima facie evidence of the holder's title to the shares","It has no legal effect; only the register matters"],"answer":2,"explanation":"Section 46(1): a share certificate issued under the common seal, if any, or signed as specified, is prima facie evidence of the title of the person named in it to the shares. It can be rebutted, but the company may be estopped from denying it against a good-faith purchaser.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-561","question":"The board wants to make a call of ₹3 per share on some shareholders of a class but ₹5 per share on others of the same class, all holding identical partly paid shares. Is this valid?","options":["Yes, if the board approves","No; calls must be made on a uniform basis on all shares of the same class","Yes, with an ordinary resolution","Yes, if the shareholders paying more consent"],"answer":1,"explanation":"Section 49 requires calls on shares of the same class to be made on a uniform basis on all such shares; shares of the same nominal value with different amounts paid up are treated as a different class for this purpose.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-562","question":"A director is a partner in a firm with which the company proposes to enter into a contract. At the board meeting considering the contract, what must the director do?","options":["Vote, provided he discloses his interest","Nothing, because the contract is with the firm, not with him","Disclose his interest and not take part in the discussion or vote on the contract","Resign before the meeting"],"answer":2,"explanation":"Section 184(2): a director who is concerned or interested in a contract with a firm or other entity in which he is a partner, owner or member must disclose the nature of his interest and shall not participate in that meeting's discussion of it.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-563","question":"Which right does a company's statutory auditor have under the Companies Act, 2013?","options":["A right to vote at general meetings","A right to approve the financial statements","A right to appoint the internal auditor","A right of access at all times to the company's books, accounts and vouchers"],"answer":3,"explanation":"Section 143(1) gives the auditor a right of access at all times to the books of account and vouchers, whether kept at the registered office or elsewhere, and to require information and explanations. He may attend and be heard at general meetings but has no vote.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-564","question":"A director learns, through his position, of a business opportunity that the company would want and takes it for himself without the board's approval. Which duty has he breached?","options":["The duty not to achieve an undue gain or advantage for himself and to avoid conflicts of interest","The duty to attend board meetings","The duty to maintain registers","No duty, because opportunities belong to whoever finds them"],"answer":0,"explanation":"Section 166 requires a director to act in good faith in the company's interests, avoid situations of conflict of interest, and not achieve or attempt any undue gain or advantage; a director who does so is liable to pay the gain to the company.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-565","question":"A manufacturer replaces a defective part free of charge under the product's warranty, without charging the customer anything. What is the GST position, as clarified by the government?","options":["GST is payable on the open market value of the part","No GST is payable on the free replacement, and the manufacturer need not reverse input tax credit on the part","GST is not payable, but credit on the part must be reversed as a free supply","The customer must pay GST on the part under reverse charge"],"answer":1,"explanation":"The value of the original supply already covers the warranty obligation, so a replacement under warranty is not a separate taxable supply, and credit on the replacement part is not treated as a free sample to be reversed.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-566","question":"A principal sends goods to its commission agent, who sells them in his own name on the principal's behalf. No consideration passes when the goods move from principal to agent. Is that movement a supply?","options":["Yes; under Schedule I, supply of goods by a principal to an agent who supplies them on the principal's behalf is a supply even without consideration","No; there is no consideration","No; the principal still owns the goods","Only when the agent sells to a customer"],"answer":0,"explanation":"Schedule I treats supply of goods by a principal to his agent, where the agent undertakes to supply them on behalf of the principal (invoicing in his own name), as a supply even without consideration.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-567","question":"A registered company collects GST from customers on supplies that are actually exempt, and keeps the money. What does the CGST Act require?","options":["It may keep the money because no tax was legally payable","It must refund the customers but owes nothing to the government","It need do nothing unless a customer complains","It must pay the amount collected as tax to the government, even though the supplies are exempt"],"answer":3,"explanation":"Section 76: any person who collects an amount from another as tax but does not pay it to the government must pay it, whatever the reason, whether or not the supplies are taxable.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-568","question":"A registered company pays IGST under reverse charge on consultancy services imported from abroad and used for its taxable business. Can it take credit of that IGST?","options":["No; reverse-charge tax is a cost","Only after the foreign supplier registers in India","Yes; tax paid under reverse charge is available as input tax credit if used in the course of business","Only half the credit is allowed"],"answer":2,"explanation":"Tax paid by the recipient under reverse charge, including IGST on imported services, is input tax credit like any other, subject to the usual conditions. It must be paid in cash first; it then enters the credit ledger.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-569","question":"An Indian citizen working for the Government of India is posted at the Indian embassy in Paris and paid by the Government. Assume the usual rules on deemed accrual. Where is the salary deemed to accrue?","options":["In France, where the services are rendered","Nowhere; it is fully exempt","In India, because salary paid by the Government of India to an Indian citizen for services outside India is deemed to accrue in India","In India only if credited to an Indian bank account"],"answer":2,"explanation":"Income from salaries payable by the Government to a citizen of India for services rendered outside India is deemed to accrue or arise in India (though specific allowances for service abroad may be exempt).","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-570","question":"Mr H transfers a flat to his wife under an agreement to live apart. She lets it out and earns rent. Assume the clubbing provisions. Whose income is the rent?","options":["Mr H's, because the transfer was to his spouse","The wife's, because transfers in connection with an agreement to live apart are excluded from clubbing","Half each","Mr H's, unless the wife paid full value"],"answer":1,"explanation":"Income from assets transferred to a spouse without adequate consideration is clubbed, but transfers made in connection with an agreement to live apart are expressly excluded.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-571","question":"A business makes a provision for doubtful debts of ₹2 lakh and also writes off ₹1 lakh of specific debts as irrecoverable in its accounts. Assume the usual rules. How much is deductible as bad debts?","options":["₹1 lakh – only debts actually written off as irrecoverable","₹3 lakh","₹2 lakh","Nil, until the debtor is declared insolvent"],"answer":0,"explanation":"A bad debt is deductible when it is written off as irrecoverable in the accounts (having earlier been taken into income). A mere provision for doubtful debts is not a write-off, so it is not deductible.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-572","question":"Mr G receives listed shares as a gift from his father, who bought them 3 years ago for ₹2 lakh. G sells them 4 months after the gift for ₹5 lakh. Assume the usual capital-gains rules for gifted assets. What are the cost and the holding period?","options":["Cost nil, short-term","Cost equal to the market value on the date of gift, short-term","Cost ₹2 lakh, short-term because G held them for 4 months","Cost ₹2 lakh, and the father's holding period counts, so the gain is long-term"],"answer":3,"explanation":"For assets acquired by gift, the cost is the previous owner's cost and the holding period includes the previous owner's holding. So G's gain is ₹3 lakh, long-term.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-573","question":"Which statement about the composition scheme under GST is correct?","options":["A composition taxpayer can make inter-state supplies of goods freely","A composition taxpayer issues a tax invoice and charges GST","A composition taxpayer cannot collect tax from customers and cannot take input tax credit","A composition taxpayer can take credit on capital goods only"],"answer":2,"explanation":"A composition taxpayer pays tax at a concessional rate on turnover, issues a bill of supply, cannot charge tax to customers, cannot take input tax credit and is barred from inter-state outward supplies of goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-574","question":"A buyer obtains a car from a seller by paying with a cheque that he knows will bounce. Before the seller rescinds the contract, the buyer sells the car to C, who pays in full and knows nothing of the fraud. Can the seller recover the car from C?","options":["No; C acquired good title because he bought in good faith before the voidable contract was rescinded","Yes; the fraudster had no title to pass","Yes, if he returns C's money","No, but only if C has registered the car"],"answer":0,"explanation":"Section 29 of the Sale of Goods Act: where a seller has obtained possession under a contract voidable for fraud but not yet rescinded, a buyer in good faith without notice gets good title. The original seller's remedy is against the fraudster.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-575","question":"A buyer inspects oats offered by a farmer and buys them, wrongly believing they are old oats; the farmer knows they are new oats and of the buyer's mistake but says nothing and made no statement about age. Can the buyer avoid the contract?","options":["Yes; the farmer's silence amounted to fraud in every such case","No; a unilateral mistake about quality, without any misrepresentation, does not make the contract voidable","Yes; any mistake of fact by either party makes the contract void","No, but the court must reduce the price to the value of new oats"],"answer":1,"explanation":"Section 22: a contract is not voidable merely because one party was under a mistake as to a matter of fact. Without a duty to speak or a misrepresentation, the seller need not correct the buyer's private belief about quality (Smith v Hughes).","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-576","question":"A guarantees the honesty of C, a cashier employed by B at a fixed salary. Later, without A's consent, B changes C's terms so that C's pay depends on the cash he handles, giving him more temptation. C then embezzles money, both before and after the change. For which losses is A liable?","options":["For all the losses, since C's honesty was guaranteed throughout","For none, because the variance cancels the guarantee from the start","Only those after the variance, because the risk then increased","Only those before the variance; any variance without consent discharges the surety for later transactions"],"answer":3,"explanation":"Section 133: any variance made without the surety's consent in the terms of the contract between the principal debtor and the creditor discharges the surety as to transactions subsequent to the variance. His liability for earlier defaults remains.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-577","question":"An agent in Mumbai contracts in his own name to buy goods for a merchant resident abroad. Which statement reflects the Indian Contract Act?","options":["Being a foreign principal case, the agent may be personally liable on the contract unless the contrary is shown","The agent is never personally liable when acting for a disclosed principal","Only the foreign principal can be sued, never the agent","The contract is void because the principal is outside India"],"answer":0,"explanation":"Section 230 sets out cases where a contract to the contrary is presumed, so the agent is personally liable, including where he contracts for the sale or purchase of goods for a merchant resident abroad, where the principal is undisclosed, and where the principal cannot be sued.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-578","question":"A company that has defaulted in repaying deposits accepted by it, and the default subsists, wants to reduce its share capital under Section 66. What is the position?","options":["A reduction is allowed if the Tribunal confirms it as usual","A reduction is allowed by a special resolution alone","No reduction can be made while the deposit default (with interest due) continues","A reduction is allowed if the depositors are paid within a year"],"answer":2,"explanation":"The proviso to Section 66(1) says no reduction of share capital shall be made if the company is in arrears in repayment of deposits accepted by it, before or after the Act, or of interest payable on them.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-579","question":"A company proposes to hold its AGM on a national holiday at 7 p.m. at a hotel in another city. Which of these requirements of Section 96 does it break?","options":["Only the place, because the AGM must be at the registered office","Only the time, because holidays are allowed for AGMs","Both the day and the time: an AGM cannot be held on a national holiday and must be held between 9 a.m. and 6 p.m.","None, because the board may fix any time, day and place"],"answer":2,"explanation":"Section 96(2): an AGM must be called during business hours (9 a.m. to 6 p.m.) on a day that is not a national holiday, at the registered office or another place in the same city, town or village. (Some companies have exemptions on place.)","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-580","question":"A company is incorporated on 1 December 2025 and its first financial year ends on 31 March 2026. By when must it hold its first annual general meeting, and must it hold one in the calendar year of incorporation?","options":["By 31 December 2026; no AGM is required in the year of incorporation","By 30 September 2026; an AGM is also needed in 2025","By 31 March 2027; no AGM is needed before then","By 30 June 2026; an AGM is also needed in 2025"],"answer":0,"explanation":"Section 96(1): the first AGM must be held within nine months from the close of the first financial year (31 March 2026 + 9 months = 31 December 2026), and it need not be held in the year of incorporation.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-581","question":"A pharma company distributes free samples of a medicine to unrelated doctors for promotion. What is the GST position?","options":["The samples are a deemed supply valued at their market price","The samples are a supply, but credit on them is fully allowed","The samples are exempt supplies, so credit is reversed proportionately","The samples are not a supply, as there is no consideration and no Schedule I case, and credit on them is blocked"],"answer":3,"explanation":"Without consideration, a supply is taxable only if listed in Schedule I (related persons, distinct persons, agents, business assets with credit). Free samples to unrelated persons are not covered, and Section 17(5)(h) blocks credit on free samples.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-582","question":"A company sells goods to its wholly owned subsidiary at an unusually low price, and the price is not the sole consideration because the parties are related. The subsidiary makes mainly exempt supplies. How is the value of supply determined?","options":["Always the invoice price, because the parties agreed on it","Under the valuation rules for related persons, generally the open market value, not the invoice price","The cost of production plus a fixed 5% margin in every case","Nil, because supplies within a group are outside GST"],"answer":1,"explanation":"Section 15 accepts transaction value only where the parties are not related and price is the sole consideration. Between related persons, the valuation rules apply: open market value, then like-kind value, then cost-based or residual methods. The invoice-value relief applies only where the recipient can take full credit.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-583","question":"A company takes out a keyman insurance policy on its managing director's life and claims the premiums as a business expense. Later it receives ₹1 crore on maturity. Assume the usual rules. How is the sum treated?","options":["It is exempt, like any life-insurance payout","It is a capital receipt, taxed only as capital gains","It is taxable only in the director's hands as salary","It is taxable as business income in the company's hands"],"answer":3,"explanation":"Sums received under a keyman insurance policy, including bonus, are taxable: as business income for the employer, and as salary or other sources in other cases. The usual life-insurance exemption does not cover keyman policies.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-584","question":"A Hindu undivided family is totally partitioned and its land is distributed among the members. Assume the usual capital-gains rules. Is a capital gain charged on the HUF or the members at the time of partition?","options":["Yes; the HUF is taxed on the market value of the land","Yes; each member is taxed on the value of land received","No; distribution of capital assets on the total or partial partition of an HUF is not regarded as a transfer","Only if the land is sold within three years of partition"],"answer":2,"explanation":"Distribution of capital assets on partition of an HUF is excluded from 'transfer' for capital gains. When a member later sells, the cost is the HUF's cost and the HUF's holding period is included.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-585","question":"A flood threatens a partnership firm's stock at night. One partner, unable to reach the others, hires trucks at a premium to move the goods to safety. Is the firm bound by the hire contract?","options":["No; hiring trucks was beyond his implied authority","Yes; in an emergency a partner may do all acts to protect the firm from loss that a prudent person would do in his own case","No, unless all partners ratify the contract later","Only the partner who hired the trucks is personally bound"],"answer":1,"explanation":"Section 21 of the Partnership Act gives a partner authority, in an emergency, to do all acts for protecting the firm from loss that would be done by a person of ordinary prudence in his own case, acting in similar circumstances; such acts bind the firm.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-586","question":"A debtor's authorised agent writes and signs, on the debtor's behalf, a promise to pay a creditor a debt that has become time-barred. The debtor later refuses to pay. Is the promise enforceable?","options":["Yes; a written promise to pay a time-barred debt is valid if signed by the debtor or his authorised agent","No; only a promise signed personally by the debtor is valid","No; a time-barred debt can never be revived","Yes, but only if the creditor gives fresh consideration"],"answer":0,"explanation":"Section 25(3) validates a written promise, signed by the person to be charged or by his agent generally or specially authorised in that behalf, to pay wholly or in part a debt that the creditor could have enforced but for the law of limitation.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-587","question":"A wholesaler sells grain by sample. When the bulk arrives, the buyer is given no chance to compare it with the sample before being asked to accept it. Which implied condition protects him?","options":["That the bulk matches the seller's general trade description","That he shall have a reasonable opportunity of comparing the bulk with the sample","That the seller has the right to sell the grain to him","That the grain is fit for a purpose made known later"],"answer":1,"explanation":"Section 17(2) implies three conditions in a sale by sample: the bulk corresponds with the sample in quality, the buyer has a reasonable opportunity of comparing them, and the goods are free from hidden defects rendering them unmerchantable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-588","question":"An order cheque is stolen; the thief forges the payee's endorsement and cashes it at the drawee bank, which pays in due course without negligence and in good faith. Can the drawer make the bank re-credit his account?","options":["Yes; a forged endorsement means the bank never had a mandate to pay","Yes, unless the drawer had crossed the cheque","No, but the drawer can recover from the payee","No; the paying banker is discharged when it pays an order cheque in due course on an endorsement that purports to be the payee's"],"answer":3,"explanation":"Section 85(1) protects the drawee: where a cheque payable to order purports to be endorsed by or on behalf of the payee, the banker is discharged by payment in due course. The true owner's remedy lies against the thief and later holders.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-589","question":"Goods imported into India are sold by the importer to a buyer while they are still in a customs-bonded area, before they cross the customs frontier. How is this supply classified under GST law?","options":["As an intra-state supply in the state of the port","As an export of goods, so it is zero-rated","As an inter-state supply, so IGST rules apply until the goods cross the customs frontier","As neither goods nor services in every case"],"answer":2,"explanation":"Section 7(2) of the IGST Act treats the supply of goods imported into India, till they cross the customs frontiers of India, as a supply in the course of inter-state trade or commerce. (Specific transactions such as warehoused-goods sales have their own Schedule III treatment.)","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-590","question":"A small manufacturer sends samples of its new product to a prospective distributor in another state for testing, without charging anything; the distributor is unrelated. Which document should normally accompany the goods?","options":["A delivery challan, since the movement is not a supply","A tax invoice charging IGST","A bill of supply","A debit note"],"answer":0,"explanation":"Goods moved for purposes other than supply – such as samples for testing, job work or approval – travel under a delivery challan rather than a tax invoice. There is no consideration and no Schedule I case, so there is no supply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-591","question":"A registered used-car dealer opts to pay GST on the margin for second-hand goods on which no input tax credit was taken. Car X was bought from an individual for ₹4,00,000 and sold for ₹4,60,000; Car Y was bought for ₹3,00,000 and sold for ₹2,80,000. Assume GST at 18% is charged on top of the taxable value. What is the total GST payable on the two sales?","options":["₹10,800","₹7,200","₹82,800","₹9,153"],"answer":0,"explanation":"Under the margin scheme the value is selling price − purchase price: ₹60,000 on X, so tax = ₹10,800. A negative margin (Y: −₹20,000) is ignored, not set off, so netting to ₹40,000 (₹7,200) is wrong. ₹82,800 taxes the full price of X, and ₹9,153 treats the margin as tax-inclusive.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-592","question":"Goods with an assessable value of ₹10,00,000 are imported. Assume basic customs duty at 10%, a social welfare surcharge of 10% of the basic customs duty, and IGST at 18%. How much IGST is payable on import?","options":["₹1,80,000","₹1,99,800","₹1,98,000","₹3,09,800"],"answer":1,"explanation":"IGST on imports is levied on assessable value plus customs duties: 10,00,000 + 1,00,000 (BCD) + 10,000 (SWS) = 11,10,000; 18% = ₹1,99,800. ₹1,80,000 ignores the duties, ₹1,98,000 leaves out the surcharge, and ₹3,09,800 is the total of all three levies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-593","question":"A registered person files a GST return 73 days late. Its tax liability for the month was ₹1,00,000, of which ₹70,000 was paid by using input tax credit and ₹30,000 in cash. Assume interest at 18% a year and that no proceedings have been started. How much interest is payable?","options":["₹3,600","₹2,520","₹1,080","₹5,400"],"answer":2,"explanation":"For a late return, interest is charged only on the part of tax paid in cash: ₹30,000 × 18% × 73/365 = ₹1,080. Charging it on the gross liability gives ₹3,600 and on the credit portion ₹2,520; ₹5,400 is a full year's interest.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-594","question":"A manufacturer buys inputs taxed at 18% GST and sells its finished product at a 5% rate, so unused input tax credit keeps piling up in its credit ledger. What remedy does GST law provide in principle?","options":["The credit lapses at the end of each year","It can be transferred to any other taxpayer","It can be used to pay income tax","A refund of the unutilised credit that has accumulated because the tax rate on inputs is higher than on output (inverted duty structure), except for items specifically excluded"],"answer":3,"explanation":"Section 54(3) allows a refund of unutilised ITC in two cases: zero-rated supplies without tax, and an inverted duty structure. GST credit cannot be used for income tax, and it does not lapse each year.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-595","question":"A company charged and paid CGST and SGST on a supply, treating it as intra-state. A year later the authorities correctly hold that it was an inter-state supply. What is the position under GST law?","options":["It must pay IGST, without interest, and claim a refund of the CGST and SGST paid","The CGST and SGST already paid are simply adjusted against IGST","It must pay IGST with interest from the original due date, and the CGST and SGST are forfeited","No action is needed, since the total tax paid is the same"],"answer":0,"explanation":"Section 77 of the CGST Act and section 19 of the IGST Act say the taxpayer pays the correct IGST, owes no interest on it, and gets a refund of the CGST and SGST paid by mistake. There is no automatic adjustment between the two levies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-596","question":"Under Schedule III of the CGST Act, which of these is treated as neither a supply of goods nor a supply of services?","options":["Sale of lottery tickets","Assignment of a book debt (receivable) to a factoring company","Entry to a casino","Betting on horse races"],"answer":1,"explanation":"Actionable claims are outside GST except 'specified actionable claims': betting, casinos, gambling, horse racing, lottery and online money gaming. Assigning an ordinary receivable is therefore not a supply, while the other three are taxable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-597","question":"A business's year-end figures include: bonus to employees ₹5 lakh, paid after the due date of filing the return; employer's provident fund contribution ₹2 lakh, paid before that due date; bank loan interest ₹3 lakh, which the bank converted into a new loan; and leave encashment ₹1 lakh, paid during the year. Under section 43B, how much is deductible this year?","options":["₹6 lakh","₹8 lakh","₹3 lakh","₹11 lakh"],"answer":2,"explanation":"43B allows these items only on actual payment, by the due date of the return for the year-end dues. PF (₹2 lakh) and leave encashment (₹1 lakh) qualify. Bonus paid after the due date is deductible next year, and interest converted into a loan is not 'actually paid'.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-598","question":"A company sells one of its undertakings as a going concern for a lump sum of ₹5 crore (assume this equals fair value), without assigning values to individual assets. The undertaking's depreciable assets have a tax written-down value of ₹2 crore (book value ₹2.5 crore), land a book value of ₹1 crore and debtors ₹0.8 crore; its liabilities are ₹0.6 crore. What is the capital gain under the slump-sale rules?","options":["₹1.3 crore","₹1.2 crore","₹2.6 crore","₹1.8 crore"],"answer":3,"explanation":"Net worth = WDV of depreciable assets (₹2 crore, not book value) + other assets at book value (₹1 + ₹0.8 crore) − liabilities (₹0.6 crore) = ₹3.2 crore. Gain = 5 − 3.2 = ₹1.8 crore. Using book value for depreciable assets gives ₹1.3 crore, and ignoring liabilities gives ₹1.2 crore.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-599","question":"An Indian company earns income in a country with which India has a tax treaty, and also in a country with which it has none. How does Indian law relieve double taxation?","options":["Section 90 applies the treaty, and the taxpayer may use the Act's provisions where they are more beneficial; section 91 gives unilateral relief for tax paid in the non-treaty country","Only the treaty country's income gets relief, and no relief is available for the other","Treaty provisions always override the Act even when the Act is more favourable","Foreign income of a resident is exempt in India"],"answer":0,"explanation":"Under section 90, a treaty applies, but the Act prevails where it is more beneficial to the taxpayer. Section 91 gives unilateral relief, a deduction for tax paid in a non-treaty country, at the lower of the Indian and foreign rate.","difficulty":"hard","source":"Big 4 tax · MBA placement"},
  {"id":"mgmt-tax-law-600","question":"An individual buys a flat for ₹40 lakh. Assume the rule that if the stamp duty value exceeds the consideration by more than the higher of ₹50,000 and 10% of the consideration, the whole difference is taxed as income from other sources. What is taxable if the stamp duty value is (a) ₹46 lakh, and (b) ₹43 lakh?","options":["(a) ₹6 lakh; (b) ₹3 lakh","(a) ₹6 lakh; (b) nil","(a) ₹2 lakh; (b) nil","(a) nil; (b) nil"],"answer":1,"explanation":"The tolerance is the higher of ₹50,000 and 10% of ₹40 lakh = ₹4 lakh. In (a) the gap of ₹6 lakh exceeds it, so the whole ₹6 lakh (not just the excess of ₹2 lakh) is taxed. In (b) the gap of ₹3 lakh is within the tolerance, so nothing is taxed.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-601","question":"An Indian subsidiary sells 10,000 units to its foreign parent at ₹800 each, ex-works. It sells the same product to an unrelated buyer at ₹950, but that price includes ₹50 of freight that the subsidiary bears. Using the comparable uncontrolled price method, by how much should the subsidiary's income be adjusted?","options":["₹15 lakh","Nil","₹10 lakh","₹5 lakh"],"answer":2,"explanation":"The comparable price is adjusted for differences: ₹950 − ₹50 freight = ₹900 ex-works. Adjustment = (900 − 800) × 10,000 = ₹10 lakh. Leaving out the freight adjustment overstates it at ₹15 lakh.","difficulty":"hard","source":"Big 4 tax · transfer pricing · MBA placement"},
  {"id":"mgmt-tax-law-602","question":"A trader has a loss of ₹2 lakh from intraday (speculative) share trading and a profit of ₹5 lakh from his regular textile business in the same year. Under the set-off rules, what is correct?","options":["The speculative loss is set off against the textile profit, leaving ₹3 lakh","The speculative loss can be set off against salary but not business income","The speculative loss lapses at once","The speculative loss can be set off only against speculative income and is carried forward, while a non-speculative loss could have been set off against speculative profit"],"answer":3,"explanation":"Section 73 ring-fences speculation losses: they can be set off only against speculation income, now or in the next four years. The rule is one-way; an ordinary business loss can be set off against speculation profit.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-603","question":"A company's books show a ₹25 lakh 'loan' from a person whose identity it cannot establish and who has no visible means to lend. What is the tax consequence under section 68?","options":["The sum can be taxed as the company's income, because the assessee must prove the lender's identity, creditworthiness and the genuineness of the transaction","It is a liability, so it can never be taxed","It is taxed only in the lender's hands","It is treated as share capital and exempt"],"answer":0,"explanation":"For unexplained cash credits the burden is on the assessee to establish identity, creditworthiness and genuineness. If it cannot, the credit is deemed income (taxed at a special high rate), even though it is recorded as a loan.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-604","question":"A logistics company pays (i) a ₹2 lakh penalty for overloading trucks in breach of the Motor Vehicles Act and (ii) ₹3 lakh of damages to a customer for late delivery under a contract. Which can it deduct as a business expense?","options":["Both","Only the damages, because expenditure for a purpose that is an offence or prohibited by law is not deductible","Only the penalty","Neither, since both are punitive"],"answer":1,"explanation":"Explanation 1 to section 37(1) disallows expenditure incurred for any purpose that is an offence or prohibited by law, so the penalty is out. Compensation for breach of a business contract is an ordinary trading loss and is deductible.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-605","question":"A farmer-trader has a loss of ₹1.5 lakh from agriculture and taxable income of ₹6 lakh from his shop. Can he set off the agricultural loss against the shop income?","options":["Yes, under inter-head set-off","Yes, but only half of it","No, because a loss from a source whose income is exempt cannot be set off against taxable income","No, but he can carry it forward against future shop income"],"answer":2,"explanation":"Set-off rules apply only to losses from taxable sources. Agricultural income is exempt, so its loss cannot reduce taxable income or be carried forward against it (agricultural income matters only in working out the rate under partial integration).","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-606","question":"A company spends ₹50 lakh on its mandatory CSR obligation under the Companies Act, on rural education projects. How is this treated in computing its business income?","options":["Fully deductible as a business expense","Deductible only if the projects are near its factories","Deductible at 50%","Not deductible as a business expense, by an express explanation to section 37(1)"],"answer":3,"explanation":"Explanation 2 to section 37(1) states that CSR expenditure under section 135 of the Companies Act is not incurred for business purposes. Some CSR spends may separately qualify for other deductions (such as certain donations), but not under section 37.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-607","question":"A shareholder holding 1,000 shares receives a 1-for-2 rights offer and, instead of subscribing, sells (renounces) his 500 rights entitlements for ₹30 each. How is this taxed?","options":["As a short-term capital gain of ₹15,000, since the entitlement's cost is nil and it is held only from the offer date to renunciation","As a long-term capital gain, since the original shares were held for years","Not taxable, since a rights entitlement is not a capital asset","As a gain of ₹15,000 less a proportionate part of the cost of the original shares"],"answer":0,"explanation":"The cost of a renounced rights entitlement is taken as nil, so the whole ₹15,000 is the gain. Its holding period runs from the offer date to renunciation, making it short-term. The cost of the original shares is not split.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-608","question":"A retiring businessman receives ₹1 crore from a buyer of his products under an agreement not to set up a competing business for five years (not linked to any transfer of a manufacturing right or licence). How is the sum taxed?","options":["As a capital receipt, not taxable","As profits and gains of business or profession under a specific provision for non-compete receipts","As income from other sources at a special rate","As a capital gain with indexation"],"answer":1,"explanation":"Section 28(va) taxes sums received for not carrying out any activity in relation to a business or profession as business income. The exception (taxed as capital gain) covers sums received for transferring a right to manufacture or carry on business.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-609","question":"A company with a large brought-forward loss decides not to claim depreciation on its machinery this year, hoping to save it for later years. What is the tax position?","options":["It can choose not to claim and defer the depreciation","It may claim depreciation only in the year it has profits","Depreciation is deemed allowed whether or not claimed, so the asset's written-down value is reduced anyway","It loses depreciation permanently but keeps the original cost"],"answer":2,"explanation":"Explanation 5 to section 32 makes depreciation compulsory: it is allowed whether or not the assessee claims it, and the WDV falls accordingly. Unabsorbed depreciation then carries forward under its own rules.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-610","question":"A resident individual aged 68 has pension and interest income only, with tax payable of ₹90,000 after TDS. Is she required to pay advance tax?","options":["Yes, in four instalments like others","Yes, but in one instalment by March","Only if her tax exceeds ₹1 lakh","No, a resident senior citizen with no business or professional income need not pay advance tax"],"answer":3,"explanation":"Section 207(2) exempts resident individuals aged 60 or more who have no income under the head 'profits and gains of business or profession' from advance tax; they pay the balance as self-assessment tax.","difficulty":"moderate","source":"Big 4 tax · MBA placement"},
  {"id":"mgmt-tax-law-611","question":"Consider these statements under the Competition Act, 2002:\nI. A price-fixing agreement between competing cement makers is presumed to have an appreciable adverse effect on competition.\nII. A manufacturer's resale price maintenance agreement with its dealers is judged on whether it actually causes an appreciable adverse effect.\nIII. Every exclusive distribution agreement is void per se.\nWhich are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":0,"explanation":"Horizontal agreements among competitors (price fixing, output limits, market sharing, bid rigging) carry a presumption of AAEC under section 3(3). Vertical agreements such as RPM and exclusive distribution (section 3(4)) are anti-competitive only if they cause AAEC, judged on the facts.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-612","question":"Four contractors bidding for a state road project agree that each will take turns submitting the lowest bid, while the others quote higher 'cover' prices. Under the Competition Act, this is:","options":["Lawful, since each still bids separately","Bid rigging, a horizontal agreement presumed to harm competition","Abuse of dominance, which needs proof that one bidder is dominant","A combination needing prior approval"],"answer":1,"explanation":"Bid rotation with cover bids is a classic form of collusive bidding, listed under section 3(3)(d) and presumed to have an appreciable adverse effect on competition. Dominance and merger control are irrelevant.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-613","question":"A company holds 70% of the Indian market for a medical device. Which statement is correct under the Competition Act?","options":["A 70% share is illegal in itself and must be reduced","Any price cut by it is automatically predatory","Being dominant is not prohibited; abusing the dominant position (such as unfair prices, limiting supply or denying market access) is","Only government companies can be dominant"],"answer":2,"explanation":"Section 4 targets abuse of dominance, not dominance itself, which a firm may earn through superior products. Predatory pricing must be below cost with intent to reduce competition, not just any price cut.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-614","question":"A member of a cartel is the first to come forward to the Competition Commission with full, genuine evidence of the cartel before the Commission has enough evidence of its own, and it cooperates throughout. What can it expect?","options":["Immunity from all civil claims by customers","Automatic dismissal of the case against all members","A doubled penalty, for having taken part","A reduction of penalty of up to 100% under the lesser-penalty (leniency) provisions"],"answer":3,"explanation":"Section 46 and the lesser-penalty regulations reward the first applicant with up to a full reduction in penalty, with smaller reductions for later applicants. The cartel itself is still prosecuted against the others.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-615","question":"Two large firms sign an agreement to merge, and the combination crosses the thresholds requiring notice to the Competition Commission. Before approval, they plan to integrate operations and appoint common management. What is the legal position?","options":["The combination cannot take effect until the Commission approves it or the statutory waiting period expires, so integrating early is a violation","Notice can be filed after closing","Merger control applies only to cross-border deals","Integration is allowed if the firms are in different industries"],"answer":0,"explanation":"India's merger control is suspensory: a notifiable combination must not be consummated (even partly, by 'gun-jumping') before approval or the expiry of the waiting period. Penalties apply for early implementation.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-616","question":"A drug company licenses its patented process to a manufacturer on condition that the licensee keeps the process secret and uses it only for the licensed product. Under the Competition Act, are these restrictions anti-competitive?","options":["Yes, every restriction in a licence is anti-competitive","No, reasonable conditions necessary to protect intellectual property rights are permitted","Yes, unless the Commission approves the licence in advance","No, because patents are outside the Competition Act entirely, whatever the conditions"],"answer":1,"explanation":"Section 3(5) saves reasonable conditions needed to protect IP rights. Unreasonable conditions, such as tie-ins or price-fixing beyond what the IP requires, can still be challenged, and abuse of dominance by an IP holder is not excused.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-617","question":"Under FEMA, which of these transactions by a person resident in India is a capital account transaction?","options":["Paying for imported raw material","Remitting money for a child's tuition abroad","Buying a flat in Dubai","Paying interest on a foreign loan"],"answer":2,"explanation":"A capital account transaction changes a resident's assets or liabilities outside India (or a non-resident's in India), such as buying property abroad. Trade payments, education remittances and interest payments are current account transactions.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-618","question":"How are contraventions of the Foreign Exchange Management Act, 1999 generally treated, compared with its predecessor FERA?","options":["As criminal offences with arrest on suspicion","As cognisable offences tried by magistrates","As tax evasion under the Income-tax Act","As civil contraventions attracting monetary penalties, with civil imprisonment only for non-payment of a penalty"],"answer":3,"explanation":"FEMA moved from FERA's criminal approach to a civil one: contraventions attract penalties and adjudication, and detention is used only to recover unpaid penalties. Money laundering is handled separately under the PMLA.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-619","question":"A supply contract contains an arbitration clause. The buyer argues the whole contract is void because it was procured by misrepresentation, so the arbitration clause falls with it. How does the Arbitration and Conciliation Act treat this?","options":["The arbitration clause is a separate agreement, and the tribunal can rule on its own jurisdiction; a finding that the main contract is void does not by itself invalidate the clause","The clause is void if the contract is void, so courts must decide","The buyer can go to court at any stage to stop the arbitration","The seller must first prove the contract valid in a civil suit"],"answer":0,"explanation":"Section 16 embodies separability and kompetenz-kompetenz: the arbitration clause is independent of the main contract, and the tribunal may rule on its own jurisdiction, including objections about the contract's validity.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-620","question":"A company sues a vendor in a civil court despite an arbitration clause in their contract. The vendor files its written statement on the merits and only months later applies to refer the dispute to arbitration. What is the likely outcome?","options":["The court must refer the dispute at any stage","The court may refuse, because the application must be made no later than the first statement on the substance of the dispute","The court must stay the suit and decide the dispute itself","The arbitration clause becomes void automatically when a suit is filed"],"answer":1,"explanation":"Section 8 obliges a court to refer parties to arbitration only if a party applies not later than when it submits its first statement on the substance of the dispute. By pleading on the merits first, the vendor is taken to have waived arbitration.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-621","question":"A losing party challenges a domestic arbitral award under section 34, arguing only that the arbitrator weighed the evidence wrongly and should have believed its witnesses. What is the court likely to do?","options":["Re-hear the evidence and substitute its own view","Send the case back for a fresh arbitration","Refuse to interfere, because section 34 does not allow re-appreciation of evidence; it allows setting aside on limited grounds such as invalid agreement, lack of notice, excess of jurisdiction, public policy or patent illegality","Set aside the award, since any error of fact is enough"],"answer":2,"explanation":"After the 2015 amendment, section 34 expressly bars review on the merits and re-appreciation of evidence. Courts intervene only on the listed grounds, keeping arbitration final.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-622","question":"After the 2018 amendment to the Specific Relief Act, how do courts treat a suit for specific performance of a valid contract to sell commercial land?","options":["Specific performance is purely discretionary and rarely granted","Only damages are available for land","It is available only if damages cannot be measured","Specific performance is to be enforced as a rule, subject only to the limited exceptions in the Act (such as contracts not specifically enforceable)"],"answer":3,"explanation":"The amendment changed section 10 so that specific performance 'shall be enforced', removing the old discretion that made damages the norm. The statutory bars (personal service, continuous supervision, determinable contracts and so on) remain.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-623","question":"A contractor abandons a half-built warehouse. The owner gives the contractor written notice and then hires another builder to finish it, under the substituted-performance provision of the Specific Relief Act. What can the owner do afterwards?","options":["Recover the costs of substituted performance from the defaulting contractor, but not also seek specific performance","Seek specific performance against the original contractor as well","Recover nothing, since he chose another builder","Recover only if the second builder was cheaper"],"answer":0,"explanation":"Section 20 lets the affected party get the contract performed by a third party after at least 30 days' written notice and recover the expense from the defaulter, but having done so it cannot also claim specific performance.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-624","question":"A customer accepts an online subscription contract by clicking 'I agree' and later argues it is unenforceable because nothing was signed on paper. Under the Information Technology Act, 2000, what is the position?","options":["It is unenforceable without a wet-ink signature","A contract formed through electronic means is not unenforceable merely because it was formed electronically","It is valid only if stamped and registered","Only contracts with a digital signature certificate are valid"],"answer":1,"explanation":"Section 10A states that a contract formed by electronic communication of proposal and acceptance shall not be deemed unenforceable solely on that ground. The usual Contract Act requirements (free consent, lawful object and so on) still apply.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-625","question":"A company collects employees' personal data and decides why and how it is used; it hires a payroll firm that only processes the data on its instructions. Under the Digital Personal Data Protection Act, 2023, what are the company and the payroll firm?","options":["Both are data fiduciaries","Data principal and data fiduciary respectively","Data fiduciary and data processor respectively","Data processor and data fiduciary respectively"],"answer":2,"explanation":"The data fiduciary determines the purpose and means of processing and carries primary obligations; the data processor processes on its behalf. The employees are the data principals.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-626","question":"An agent in Mumbai contracts in his own name to buy machines for a merchant resident in Germany, without any express term about his personal liability. The seller is unpaid. Under the Indian Contract Act, can the seller sue the agent personally?","options":["No, an agent is never personally liable","No, the seller must sue the principal in Germany","Only if the agent was paid a commission","Yes, because a contract making the agent personally liable is presumed when he buys or sells goods for a merchant resident abroad"],"answer":3,"explanation":"Section 230 normally keeps the agent out of the contract, but presumes personal liability where the agent acts for a merchant resident abroad, does not disclose the principal, or acts for a principal who cannot be sued.","difficulty":"very-hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-627","question":"A is appointed sole agent to sell B's tractors for a fixed term of three years. After one year, without any misconduct by A, B revokes the agency with immediate effect. What is A's remedy?","options":["Compensation for the revocation without sufficient cause, and for loss caused by lack of reasonable notice","None, because a principal can always revoke at will","Specific performance of the agency for the remaining term","Only commission earned to date, with nothing else"],"answer":0,"explanation":"Under sections 205 and 206, where an agency is for a fixed period, the principal must compensate the agent for revoking it early without sufficient cause, and reasonable notice must be given. The agency cannot be forced to continue.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-628","question":"An agent engaged to sell his principal's land secretly buys it himself through a nominee at the asking price, and resells it a month later at a large profit. What can the principal do?","options":["Nothing, since he got his asking price","Repudiate the sale if the agent concealed material facts, or claim from the agent the profit he made from the transaction","Only dismiss the agent","Sue the second buyer for the land"],"answer":1,"explanation":"Sections 215 and 216 forbid an agent dealing on his own account without the principal's informed consent. The principal may repudiate the transaction, or claim any benefit the agent obtained from it.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-629","question":"A contract for 12 monthly deliveries of steel, each paid for separately, receives one defective delivery in month 3. The buyer wants to cancel the whole contract. Under the Sale of Goods Act, what decides whether he can?","options":["He can always cancel the whole contract for any defective instalment","He can never cancel; only damages are available","Whether the breach amounts to a repudiation of the whole contract or is a severable breach giving only a right to compensation depends on the terms and circumstances","The seller decides"],"answer":2,"explanation":"Section 38(2) leaves it to the contract terms and the circumstances, such as the ratio of the breach to the whole and the chance of it recurring. A single, isolated defect usually gives a right to damages for that instalment only.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-630","question":"A partnership deed is silent on expulsion. Three of four partners vote in good faith to expel the fourth for poor performance. Is the expulsion valid under the Indian Partnership Act?","options":["Yes, a majority can expel for any reason in good faith","Yes, if they pay him his capital","Yes, if the firm is registered","No, because expulsion needs a power conferred by contract between the partners, exercised in good faith by a majority"],"answer":3,"explanation":"Section 33 allows expulsion only in good faith, by a majority, and in exercise of a power conferred by the partners' contract. With no such power in the deed, even a good-faith majority cannot expel.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-631","question":"C joins an existing firm as a partner on 1 April. A supplier whose bill for goods bought in February is unpaid sues all the current partners, including C. Is C liable?","options":["No, a person introduced as a partner is not liable for acts of the firm done before he became a partner, unless he agrees otherwise","Yes, all current partners are liable for all firm debts","Yes, but only up to his capital contribution","Only if the debt was in the firm's books when he joined"],"answer":0,"explanation":"Section 31(2) protects an incoming partner from liability for acts done before he joined. He can, however, take on old debts by agreement with the creditor and the firm (novation).","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-632","question":"A retiring partner, with no agreement restraining him, opens a competing business across the road. Which of these may he lawfully do under the Indian Partnership Act?","options":["Use the old firm's name for the new business","Advertise his new business","Approach the old firm's customers and persuade them to switch","Represent himself as still carrying on the old firm's business"],"answer":1,"explanation":"Section 36 lets an outgoing partner compete and advertise, but forbids using the firm name, representing that he carries on the firm's business, or soliciting the firm's existing customers, unless agreed otherwise.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-633","question":"Directors who control the majority vote of a company divert a lucrative contract to their own firm and use their majority to ratify it. A minority shareholder sues. Why can he sue despite the rule that the company is the proper plaintiff?","options":["Any shareholder can sue for any wrong","The majority rule applies only to private companies","'Fraud on the minority' by those in control is a recognised exception to the rule in Foss v Harbottle","Directors cannot be sued once the majority ratifies"],"answer":2,"explanation":"Foss v Harbottle says the company is the proper plaintiff and the majority decides. Exceptions include ultra vires or illegal acts, fraud on the minority by wrongdoers in control, bypassing a special majority, and infringement of personal rights.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-634","question":"In the winding up of a company, it emerges that its managing director kept taking customer advances for orders he knew the company could never fulfil, to keep the business afloat. Under section 339 of the Companies Act, what can the Tribunal do?","options":["Nothing, since a company has limited liability","Only order him to return his salary","Only fine the company","Declare him personally responsible, without limitation of liability, for the company's debts as directed, for knowingly carrying on business with intent to defraud creditors"],"answer":3,"explanation":"Section 339 lifts the corporate veil for fraudulent conduct of business: persons knowingly party to it can be made personally liable without limit, besides facing criminal liability.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-635","question":"A listed company wants to reward its independent directors. Which of these may it give them under the Companies Act, 2013?","options":["Sitting fees and, subject to limits, profit-related commission, but not stock options","Stock options, like other directors","A monthly salary as employees","Any remuneration the board approves"],"answer":0,"explanation":"Sections 149(9) and 197(7) bar independent directors from stock options, to protect their independence, but allow sitting fees, reimbursement of expenses and profit-related commission approved by members.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-636","question":"A consumer wants a District Consumer Commission to declare a clause in a builder's standard agreement 'unfair' and void. Under the Consumer Protection Act, 2019, what is the position?","options":["Any District Commission can declare such terms void","Complaints about unfair contracts lie with the State or National Commission, which can declare unfair terms null and void","Only civil courts can rule on contract terms","Only the Central Consumer Protection Authority can"],"answer":1,"explanation":"The 2019 Act gives the power to declare unfair contract terms null and void only to the State and National Commissions, depending on value; the District Commission has no such jurisdiction.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-637","question":"A film star endorses a hair oil that claims to 'stop hair fall in 7 days'. The claim is false and the Central Consumer Protection Authority acts. Can the star be penalised?","options":["No, only the manufacturer is liable for an advertisement","Yes, regardless of any checks she made","Yes, the Authority can penalise an endorser of a false or misleading advertisement, unless she exercised due diligence to verify the claims","Only if she owns shares in the company"],"answer":2,"explanation":"Section 21 lets the CCPA impose penalties on endorsers and bar them from endorsing for a period, but an endorser who has exercised due diligence to verify the claims is not liable.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-638","question":"A spice company's blend recipe is unpatented and known only to a few staff, who signed confidentiality agreements. A former employee leaks it to a rival. On what basis can the company act in India?","options":["Under the Patents Act","Under the Trade Marks Act","Under the Copyright Act, since a recipe is a literary work","Through contract (the confidentiality agreement) and the equitable action for breach of confidence, as India has no specific trade-secret statute"],"answer":3,"explanation":"India protects trade secrets through contract and common-law breach of confidence (injunctions and damages). Patents require public disclosure, trademarks protect brand signs, and copyright protects expression, not the recipe itself.","difficulty":"hard","source":"Business law · IPR · MBA placement"},
  {"id":"mgmt-tax-law-639","question":"A furniture maker creates an original chair design that could be registered under the Designs Act but never registers it, relying on copyright. Assume the rule that copyright in such a design ceases once an article bearing it is reproduced more than 50 times by an industrial process. It has now made 5,000 chairs. What protection does it have?","options":["Copyright in the design has ceased, and with no design registration the shape is largely unprotected","Full copyright for the author's life plus 60 years","Design protection arises automatically without registration","Patent protection, since the chair is novel"],"answer":0,"explanation":"Section 15(2) of the Copyright Act ends copyright in a registrable but unregistered design once it is industrially reproduced more than 50 times. Industrial designs are meant to be protected by registration under the Designs Act.","difficulty":"very-hard","source":"Business law · IPR · MBA placement"},
  {"id":"mgmt-tax-law-640","question":"A CFO mentions an unannounced merger to a friend at dinner. The friend buys the company's shares the next morning, before the announcement. Under SEBI's insider-trading regulations, who has violated them?","options":["Only the CFO, since the friend is not connected to the company","Both: the CFO for communicating unpublished price-sensitive information, and the friend, an insider by being in possession of it, for trading","Only the friend, since the CFO did not trade","Neither, since the merger was certain to be announced"],"answer":1,"explanation":"An 'insider' includes anyone in possession of unpublished price-sensitive information, not only connected persons. Communicating UPSI without a legitimate purpose and trading while in possession of it are both prohibited.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-641","question":"A state government announces a three-year sales-tax exemption for new industries. Relying on it, a company sets up a plant; the government then withdraws the exemption early without overriding public interest. On which principle can the company challenge this?","options":["Privity of contract","Frustration","Promissory estoppel, which can bind even the government when a party has altered its position relying on a clear promise, unless the promise conflicts with law","Quantum meruit"],"answer":2,"explanation":"Indian courts (as in Motilal Padampat Sugar Mills) hold the government to its promises through promissory estoppel where the promisee acted on them, subject to statute and overriding public interest. No formal contract or consideration is needed.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-642","question":"A government corporation's standard employment contract lets it dismiss any permanent employee on three months' notice without reason. Employees had no real choice but to sign. How did the Supreme Court treat such a clause?","options":["As valid, because the employees signed it","As valid but subject to damages","As a matter for labour courts only","As an unconscionable term in a contract between unequal parties, void under section 23 of the Contract Act as opposed to public policy"],"answer":3,"explanation":"In Central Inland Water Transport v Brojo Nath Ganguly, the Court struck down such a clause as unconscionable, holding that unfair terms imposed by a party with overwhelming bargaining power can be void as opposed to public policy.","difficulty":"very-hard","source":"Business law · MBA placement"},
];

export default questions;
